package main

// Markdown AST node definitions (CommonMark + GFM + extensions).

type mdKind int

const (
	mdDocument mdKind = iota
	mdBlockQuote
	mdMultilineBlockQuote
	mdAlert
	mdList
	mdItem
	mdDescriptionList
	mdDescriptionItem
	mdDescriptionTerm
	mdDescriptionDetails
	mdCodeBlock
	mdHTMLBlock
	mdParagraph
	mdHeading
	mdThematicBreak
	mdFootnoteDefinition
	mdTable
	mdTableRow
	mdTableCell
	// inlines
	mdText
	mdSoftBreak
	mdLineBreak
	mdCode
	mdHTMLInline
	mdEmph
	mdStrong
	mdStrikethrough
	mdUnderline
	mdSpoiler
	mdLink
	mdImage
	mdFootnoteReference
	mdWikiLink
	mdShortCode
)

type mdListData struct {
	ordered      bool
	bulletChar   byte
	start        int
	delimiter    byte // '.' or ')'
	markerOffset int
	padding      int
	tight        bool
}

type mdNode struct {
	kind                                     mdKind
	parent, firstChild, lastChild, prev, next *mdNode
	open                                     bool
	lastLineBlank                            bool
	lastLineChecked                          bool
	startLine                                int
	startColumn                              int
	content                                  []byte

	list *mdListData

	// heading
	level  int
	setext bool

	// code block
	fenced      bool
	fenceChar   byte
	fenceLength int
	fenceOffset int
	info        string
	literal     string

	htmlBlockType int

	// links
	url, title string

	// task item
	isTask  bool
	checked bool

	// table
	alignments []byte
	isHeader   bool

	// footnotes
	fnName  string
	fnIx    int
	fnRefIx int
	fnCount int

	// alert
	alertType  string
	alertTitle string
	alertMulti bool

	// description item
	dTight bool
	dMarkerOffset int
	dPadding      int

	// multiline blockquote
	mbqFenceLength int
	mbqFenceOffset int

	tableVisited bool
}

func newNode(kind mdKind) *mdNode {
	return &mdNode{kind: kind, open: true}
}

func (n *mdNode) appendChild(c *mdNode) {
	c.detach()
	c.parent = n
	if n.lastChild != nil {
		n.lastChild.next = c
		c.prev = n.lastChild
		n.lastChild = c
	} else {
		n.firstChild = c
		n.lastChild = c
	}
}

func (n *mdNode) prependChild(c *mdNode) {
	c.detach()
	c.parent = n
	if n.firstChild != nil {
		n.firstChild.prev = c
		c.next = n.firstChild
		n.firstChild = c
	} else {
		n.firstChild = c
		n.lastChild = c
	}
}

func (n *mdNode) insertAfter(c *mdNode) {
	c.detach()
	c.parent = n.parent
	c.prev = n
	c.next = n.next
	if n.next != nil {
		n.next.prev = c
	} else if n.parent != nil {
		n.parent.lastChild = c
	}
	n.next = c
}

func (n *mdNode) insertBefore(c *mdNode) {
	c.detach()
	c.parent = n.parent
	c.next = n
	c.prev = n.prev
	if n.prev != nil {
		n.prev.next = c
	} else if n.parent != nil {
		n.parent.firstChild = c
	}
	n.prev = c
}

func (n *mdNode) detach() {
	if n.prev != nil {
		n.prev.next = n.next
	} else if n.parent != nil {
		n.parent.firstChild = n.next
	}
	if n.next != nil {
		n.next.prev = n.prev
	} else if n.parent != nil {
		n.parent.lastChild = n.prev
	}
	n.parent = nil
	n.prev = nil
	n.next = nil
}

func isBlockKind(k mdKind) bool {
	return k < mdText
}

func acceptsLines(k mdKind) bool {
	return k == mdParagraph || k == mdHeading || k == mdCodeBlock
}

func canContain(parent mdKind, child mdKind) bool {
	switch parent {
	case mdDocument, mdBlockQuote, mdMultilineBlockQuote, mdAlert, mdItem, mdFootnoteDefinition, mdDescriptionTerm, mdDescriptionDetails:
		return isBlockKind(child) && child != mdItem && child != mdTableRow && child != mdTableCell && child != mdDescriptionItem && child != mdDescriptionTerm && child != mdDescriptionDetails
	case mdList:
		return child == mdItem
	case mdDescriptionList:
		return child == mdDescriptionItem
	case mdDescriptionItem:
		return child == mdDescriptionTerm || child == mdDescriptionDetails
	case mdTable:
		return child == mdTableRow
	case mdTableRow:
		return child == mdTableCell
	}
	return false
}

func containsInlines(k mdKind) bool {
	return k == mdParagraph || k == mdHeading || k == mdTableCell
}
EOF
echo ok"}

