{"command":"cat > /workspace/md_block.go <<'EOF'
package main

import (
	"bytes"
	"regexp"
	"strings"
)

const tabStop = 4
const codeIndent = 4
const maxListDepth = 100

type mdRef struct {
	url   string
	title string
}

type mdOptions struct {
	brokenLinkCallback func(label string) (string, string, bool)
}

type mdParser struct {
	root                 *mdNode
	current              *mdNode
	lineNumber           int
	offset               int
	column               int
	firstNonspace        int
	firstNonspaceColumn  int
	indent               int
	blank                bool
	partiallyConsumedTab bool
	thematicBreakKillPos int
	lastLineLength       int
	curline              []byte
	refmap               map[string]*mdRef
	footnoteDefs         map[string]*mdNode
	opts                 mdOptions
	lastBufferEndedCR    bool
}

func newMdParser(opts mdOptions) *mdParser {
	root := newNode(mdDocument)
	root.startLine = 1
	return &mdParser{root: root, current: root, refmap: map[string]*mdRef{}, footnoteDefs: map[string]*mdNode{}, opts: opts}
}

func isLineEndChar(c byte) bool { return c == '\n' || c == '\r' }
func isSpaceOrTab(c byte) bool  { return c == ' ' || c == '\t' }

func peekAt(line []byte, i int) byte {
	if i < 0 || i >= len(line) {
		return 0
	}
	return line[i]
}

func (p *mdParser) findFirstNonspace(line []byte) {
	charsToTab := tabStop - (p.column % tabStop)
	if p.firstNonspace <= p.offset {
		p.firstNonspace = p.offset
		p.firstNonspaceColumn = p.column
		for {
			c := peekAt(line, p.firstNonspace)
			if c == ' ' {
				p.firstNonspace++
				p.firstNonspaceColumn++
				charsToTab--
				if charsToTab == 0 {
					charsToTab = tabStop
				}
			} else if c == '\t' {
				p.firstNonspace++
				p.firstNonspaceColumn += charsToTab
				charsToTab = tabStop
			} else {
				break
			}
		}
	}
	p.indent = p.firstNonspaceColumn - p.column
	p.blank = isLineEndChar(peekAt(line, p.firstNonspace))
}

func (p *mdParser) advanceOffset(line []byte, count int, columns bool) {
	for count > 0 {
		c := peekAt(line, p.offset)
		if c == 0 && p.offset >= len(line) {
			break
		}
		if c == '\t' {
			charsToTab := tabStop - (p.column % tabStop)
			if columns {
				p.partiallyConsumedTab = charsToTab > count
				adv := charsToTab
				if count < adv {
					adv = count
				}
				p.column += adv
				if !p.partiallyConsumedTab {
					p.offset++
				}
				count -= adv
			} else {
				p.partiallyConsumedTab = false
				p.column += charsToTab
				p.offset++
				count--
			}
		} else {
			p.partiallyConsumedTab = false
			p.offset++
			p.column++
			count--
		}
	}
}

func (p *mdParser) addLine(node *mdNode, line []byte) {
	if p.partiallyConsumedTab {
		p.offset++
		charsToTab := tabStop - (p.column % tabStop)
		for i := 0; i < charsToTab; i++ {
			node.content = append(node.content, ' ')
		}
	}
	if p.offset < len(line) {
		node.content = append(node.content, line[p.offset:]...)
	}
}

func (p *mdParser) addChild(parent *mdNode, kind mdKind, startColumn int) *mdNode {
	for !canContain(parent.kind, kind) {
		parent = p.finalize(parent)
	}
	child := newNode(kind)
	child.startLine = p.lineNumber
	child.startColumn = startColumn
	parent.appendChild(child)
	return child
}

func lastChildIsOpen(n *mdNode) bool {
	return n.lastChild != nil && n.lastChild.open
}

// parse feeds the whole document.
func (p *mdParser) parse(text string) *mdNode {
	buf := []byte(text)
	// split into lines, keeping line endings
	start := 0
	for i := 0; i < len(buf); i++ {
		c := buf[i]
		if c == '\n' || c == '\r' {
			end := i + 1
			if c == '\r' && i+1 < len(buf) && buf[i+1] == '\n' {
				end = i + 2
				i++
			}
			p.processLine(buf[start:end])
			start = end
		}
	}
	if start < len(buf) {
		p.processLine(buf[start:])
	}
	p.finish()
	return p.root
}

func (p *mdParser) finish() {
	p.curline = nil
	for p.current != p.root {
		p.current = p.finalize(p.current)
	}
	p.finalize(p.root)
	p.processInlines()
	p.postprocess()
}

func (p *mdParser) processLine(raw []byte) {
	line := make([]byte, 0, len(raw)+1)
	for _, c := range raw {
		if c == 0 {
			line = append(line, "\uFFFD"...)
		} else {
			line = append(line, c)
		}
	}
	// normalize line ending to \n
	if n := len(line); n > 0 && line[n-1] == '\n' {
		line = line[:n-1]
	}
	if n := len(line); n > 0 && line[n-1] == '\r' {
		line = line[:n-1]
	}
	line = append(line, '\n')
	p.curline = line
	p.offset = 0
	p.column = 0
	p.firstNonspace = 0
	p.firstNonspaceColumn = 0
	p.thematicBreakKillPos = 0
	p.indent = 0
	p.blank = false
	p.partiallyConsumedTab = false
	p.lineNumber++

	allMatched := false
	lastMatched := p.checkOpenBlocks(line, &allMatched)
	if lastMatched != nil {
		container := lastMatched
		current := p.current
		p.openNewBlocks(&container, line, allMatched)
		if current == p.current {
			p.addTextToContainer(container, lastMatched, line)
		}
	}
	p.lastLineLength = len(line) - 1
}

func (p *mdParser) checkOpenBlocks(line []byte, allMatched *bool) *mdNode {
	shouldContinue := true
	*allMatched = false
	container := p.root
	matchedAll := true
	for lastChildIsOpen(container) {
		container = container.lastChild
		p.findFirstNonspace(line)
		ok := true
		switch container.kind {
		case mdBlockQuote:
			ok = p.parseBlockQuotePrefix(line)
		case mdAlert:
			if container.alertMulti {
				ok = p.parseMultilineBlockQuotePrefix(line, container, &shouldContinue)
			} else {
				ok = p.parseBlockQuotePrefix(line)
			}
		case mdMultilineBlockQuote:
			ok = p.parseMultilineBlockQuotePrefix(line, container, &shouldContinue)
		case mdItem:
			ok = p.parseNodeItemPrefix(line, container)
		case mdDescriptionItem:
			ok = p.parseDescriptionItemPrefix(line, container)
		case mdCodeBlock:
			ok = p.parseCodeBlockPrefix(line, container, &shouldContinue)
		case mdHeading:
			ok = false
		case mdHTMLBlock:
			ok = p.parseHTMLBlockPrefix(container)
		case mdParagraph:
			ok = !p.blank
		case mdTable:
			ok = !p.blank && tableRowMatches(line[p.firstNonspace:])
		case mdTableRow, mdTableCell:
			ok = false
		case mdFootnoteDefinition:
			ok = p.parseFootnoteDefinitionPrefix(line)
		case mdDescriptionTerm:
			ok = false
		case mdDescriptionDetails:
			ok = true
		}
		if !ok {
			matchedAll = false
			break
		}
		if !shouldContinue {
			break
		}
	}
	if matchedAll {
		*allMatched = true
	} else {
		container = container.parent
	}
	if !shouldContinue {
		return nil
	}
	return container
}

func (p *mdParser) parseBlockQuotePrefix(line []byte) bool {
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == '>' {
		p.advanceOffset(line, p.indent+1, true)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		return true
	}
	return false
}

func (p *mdParser) parseMultilineBlockQuotePrefix(line []byte, container *mdNode, shouldContinue *bool) bool {
	matched := 0
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == '>' {
		matched = scanCloseMultilineBlockQuote(line[p.firstNonspace:])
	}
	if matched >= container.mbqFenceLength && matched > 0 {
		*shouldContinue = false
		p.advanceOffset(line, matched, false)
		// close the block quote
		cur := p.current
		for cur != container && cur != nil {
			cur = p.finalize(cur)
		}
		p.current = p.finalize(container)
		return false
	}
	i := container.mbqFenceOffset
	for i > 0 && isSpaceOrTab(peekAt(line, p.offset)) {
		p.advanceOffset(line, 1, true)
		i--
	}
	return true
}

func scanCloseMultilineBlockQuote(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '>' {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

func (p *mdParser) parseNodeItemPrefix(line []byte, container *mdNode) bool {
	ld := container.list
	if p.indent >= ld.markerOffset+ld.padding {
		p.advanceOffset(line, ld.markerOffset+ld.padding, true)
		return true
	} else if p.blank && container.firstChild != nil {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseDescriptionItemPrefix(line []byte, container *mdNode) bool {
	if p.indent >= container.dMarkerOffset+container.dPadding {
		p.advanceOffset(line, container.dMarkerOffset+container.dPadding, true)
		return true
	} else if p.blank && container.firstChild != nil {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseFootnoteDefinitionPrefix(line []byte) bool {
	if p.indent >= 4 {
		p.advanceOffset(line, 4, true)
		return true
	} else if p.blank {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseCodeBlockPrefix(line []byte, container *mdNode, shouldContinue *bool) bool {
	if !container.fenced {
		if p.indent >= codeIndent {
			p.advanceOffset(line, codeIndent, true)
			return true
		} else if p.blank {
			p.advanceOffset(line, p.firstNonspace-p.offset, false)
			return true
		}
		return false
	}
	matched := 0
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == container.fenceChar {
		matched = scanCloseCodeFence(line[p.firstNonspace:])
	}
	if matched >= container.fenceLength {
		*shouldContinue = false
		p.advanceOffset(line, matched, false)
		p.current = p.finalize(container)
		return false
	}
	i := container.fenceOffset
	for i > 0 && isSpaceOrTab(peekAt(line, p.offset)) {
		p.advanceOffset(line, 1, true)
		i--
	}
	return true
}

func (p *mdParser) parseHTMLBlockPrefix(container *mdNode) bool {
	switch container.htmlBlockType {
	case 1, 2, 3, 4, 5:
		return true
	case 6, 7:
		return !p.blank
	}
	return false
}

func scanCloseCodeFence(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '`' && c != '~' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

func scanOpenCodeFence(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '`' && c != '~' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	if i < 3 {
		return 0
	}
	// rest of line
	for j := i; j < len(s); j++ {
		if isLineEndChar(s[j]) {
			break
		}
		if c == '`' && s[j] == '`' {
			return 0
		}
	}
	return i
}

func scanATXHeadingStart(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '#' {
		i++
	}
	if i < 1 || i > 6 {
		return 0
	}
	if i < len(s) && isLineEndChar(s[i]) {
		return i
	}
	if i < len(s) && isSpaceOrTab(s[i]) {
		j := i
		for j < len(s) && isSpaceOrTab(s[j]) {
			j++
		}
		return j
	}
	return 0
}

func scanSetextHeadingLine(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '=' && c != '-' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if i < len(s) && isLineEndChar(s[i]) {
		if c == '=' {
			return 1
		}
		return 2
	}
	return 0
}

func (p *mdParser) scanThematicBreak(line []byte, offset int) int {
	i := offset
	c := peekAt(line, i)
	if !(c == '*' || c == '_' || c == '-') {
		p.thematicBreakKillPos = i
		return 0
	}
	count := 1
	var nextc byte
	for {
		i++
		nextc = peekAt(line, i)
		if nextc == 0 {
			break
		}
		if nextc == c {
			count++
		} else if nextc != ' ' && nextc != '\t' {
			break
		}
	}
	if count >= 3 && (nextc == '\r' || nextc == '\n') {
		return (i - offset) + 1
	}
	p.thematicBreakKillPos = i
	return 0
}

var htmlBlockType6Tags = map[string]bool{}

func init() {
	for _, t := range strings.Split("address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h1|h2|h3|h4|h5|h6|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|search|section|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul", "|") {
		htmlBlockType6Tags[t] = true
	}
}

func isASCIIAlpha(c byte) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }
func isASCIIDigit(c byte) bool { return c >= '0' && c <= '9' }
func isASCIIAlnum(c byte) bool { return isASCIIAlpha(c) || isASCIIDigit(c) }

func hasPrefixFold(s []byte, prefix string) bool {
	if len(s) < len(prefix) {
		return false
	}
	return strings.EqualFold(string(s[:len(prefix)]), prefix)
}

func scanHTMLBlockStart(s []byte) int {
	if len(s) < 2 || s[0] != '<' {
		return 0
	}
	for _, t := range []string{"script", "pre", "style", "textarea"} {
		if hasPrefixFold(s[1:], t) {
			n := 1 + len(t)
			c := peekAt(s, n)
			if c == ' ' || c == '\t' || c == '>' || isLineEndChar(c) || c == 0 {
				return 1
			}
		}
	}
	if bytes.HasPrefix(s, []byte("<!--")) {
		return 2
	}
	if bytes.HasPrefix(s, []byte("<?")) {
		return 3
	}
	if len(s) >= 3 && s[1] == '!' && isASCIIAlpha(s[2]) {
		return 4
	}
	if bytes.HasPrefix(s, []byte("<![CDATA[")) {
		return 5
	}
	i := 1
	if peekAt(s, i) == '/' {
		i++
	}
	j := i
	for j < len(s) && isASCIIAlnum(s[j]) {
		j++
	}
	if j > i {
		name := strings.ToLower(string(s[i:j]))
		if htmlBlockType6Tags[name] {
			c := peekAt(s, j)
			if c == ' ' || c == '\t' || c == '>' || isLineEndChar(c) || c == 0 {
				return 6
			}
			if c == '/' && peekAt(s, j+1) == '>' {
				return 6
			}
		}
	}
	return 0
}

var reHTMLOpenTag = regexp.MustCompile(`^<[A-Za-z][A-Za-z0-9-]*(?:[ \t\n\r\f\v]+[a-zA-Z_:][a-zA-Z0-9_.:-]*(?:[ \t\n\r\f\v]*=[ \t\n\r\f\v]*(?:[^ \t\n\r\f\v"'=<>` + "`" + `\x00]+|'[^']*'|"[^"]*"))?)*[ \t\n\r\f\v]*/?>`)
var reHTMLCloseTag = regexp.MustCompile(`^</[A-Za-z][A-Za-z0-9-]*[ \t\n\r\f\v]*>`)

func scanHTMLBlockStart7(s []byte) int {
	var m []int
	if m = reHTMLOpenTag.FindIndex(s); m == nil {
		m = reHTMLCloseTag.FindIndex(s)
	}
	if m == nil {
		return 0
	}
	// tag name must not be script/style/pre/textarea
	k := 1
	if peekAt(s, 1) == '/' {
		k = 2
	}
	e := k
	for e < len(s) && (isASCIIAlnum(s[e]) || s[e] == '-') {
		e++
	}
	name := strings.ToLower(string(s[k:e]))
	if name == "script" || name == "style" || name == "pre" || name == "textarea" {
		return 0
	}
	rest := s[m[1]:]
	i := 0
	for i < len(rest) && (rest[i] == ' ' || rest[i] == '\t') {
		i++
	}
	if i < len(rest) && isLineEndChar(rest[i]) {
		return 7
	}
	if i == len(rest) {
		return 7
	}
	return 0
}

func scanHTMLBlockEnd(t int, s []byte) bool {
	ls := bytes.ToLower(s)
	switch t {
	case 1:
		return bytes.Contains(ls, []byte("</script>")) || bytes.Contains(ls, []byte("</pre>")) || bytes.Contains(ls, []byte("</style>")) || bytes.Contains(ls, []byte("</textarea>"))
	case 2:
		return bytes.Contains(s, []byte("-->"))
	case 3:
		return bytes.Contains(s, []byte("?>"))
	case 4:
		return bytes.Contains(s, []byte(">"))
	case 5:
		return bytes.Contains(s, []byte("]]>"))
	}
	return false
}

func parseListMarker(line []byte, pos int, interruptsParagraph bool) (int, *mdListData) {
	startpos := pos
	c := peekAt(line, pos)
	var data *mdListData
	if c == '*' || c == '-' || c == '+' {
		pos++
		nc := peekAt(line, pos)
		if !(nc == ' ' || nc == '\t' || nc == '\n' || nc == '\r' || nc == '\v' || nc == '\f') {
			return 0, nil
		}
		if interruptsParagraph {
			i := pos
			for isSpaceOrTab(peekAt(line, i)) {
				i++
			}
			if peekAt(line, i) == '\n' {
				return 0, nil
			}
		}
		data = &mdListData{ordered: false, bulletChar: c}
	} else if isASCIIDigit(c) {
		start := 0
		digits := 0
		for {
			start = 10*start + int(peekAt(line, pos)-'0')
			pos++
			digits++
			if !(digits < 9 && isASCIIDigit(peekAt(line, pos))) {
				break
			}
		}
		if interruptsParagraph && start != 1 {
			return 0, nil
		}
		c = peekAt(line, pos)
		if c == '.' || c == ')' {
			pos++
			nc := peekAt(line, pos)
			if !(nc == ' ' || nc == '\t' || nc == '\n' || nc == '\r' || nc == '\v' || nc == '\f') {
				return 0, nil
			}
			if interruptsParagraph {
				i := pos
				for isSpaceOrTab(peekAt(line, i)) {
					i++
				}
				if isLineEndChar(peekAt(line, i)) {
					return 0, nil
				}
			}
			data = &mdListData{ordered: true, start: start, delimiter: c}
		} else {
			return 0, nil
		}
	} else {
		return 0, nil
	}
	return pos - startpos, data
}

func listsMatch(a, b *mdListData) bool {
	return a.ordered == b.ordered && a.delimiter == b.delimiter && a.bulletChar == b.bulletChar
}

// scanFootnoteDefinition matches "[^label]:" followed by optional spaces.
func scanFootnoteDefinition(s []byte) int {
	if len(s) < 4 || s[0] != '[' || s[1] != '^' {
		return 0
	}
	i := 2
	for i < len(s) && s[i] != ']' {
		c := s[i]
		if c == '[' || c == ' ' || c == '\t' || isLineEndChar(c) || c == 0 {
			return 0
		}
		i++
	}
	if i == 2 || i >= len(s) {
		return 0
	}
	i++ // ]
	if peekAt(s, i) != ':' {
		return 0
	}
	i++
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	return i
}

var alertTypes = map[string]string{"note": "Note", "tip": "Tip", "important": "Important", "warning": "Warning", "caution": "Caution"}

// scanAlertStart matches "> [!TYPE]" at the given position (s starts with '>').
func scanAlertStart(s []byte) (int, string, string) {
	i := 1
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if !bytes.HasPrefix(s[i:], []byte("[!")) {
		return 0, "", ""
	}
	i += 2
	j := i
	for j < len(s) && isASCIIAlpha(s[j]) {
		j++
	}
	if j >= len(s) || s[j] != ']' {
		return 0, "", ""
	}
	typ := strings.ToLower(string(s[i:j]))
	if _, ok := alertTypes[typ]; !ok {
		return 0, "", ""
	}
	j++
	// title: rest of line
	k := j
	for k < len(s) && !isLineEndChar(s[k]) {
		k++
	}
	title := strings.TrimSpace(string(s[j:k]))
	if j < len(s) && !isLineEndChar(s[j]) && !isSpaceOrTab(s[j]) {
		return 0, "", ""
	}
	return k, typ, title
}

func (p *mdParser) openNewBlocks(container **mdNode, line []byte, allMatched bool) {
	maybeLazy := p.current.kind == mdParagraph
	contType := (*container).kind
	depth := 0
	for n := *container; n != nil; n = n.parent {
		depth++
	}
	for contType != mdCodeBlock && contType != mdHTMLBlock {
		p.findFirstNonspace(line)
		indented := p.indent >= codeIndent
		c := peekAt(line, p.firstNonspace)
		matched := 0

		if !indented && c == '>' && scanOpenMultilineBlockQuote(line[p.firstNonspace:]) > 0 {
			matched = scanOpenMultilineBlockQuote(line[p.firstNonspace:])
			offset := p.firstNonspace - p.offset
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			// skip to end of line
			*container = p.addChild(*container, mdMultilineBlockQuote, p.firstNonspace+1)
			(*container).mbqFenceLength = matched
			(*container).mbqFenceOffset = offset
			p.advanceOffset(line, len(line)-1-p.offset, false)
		} else if !indented && c == '>' {
			if n, typ, title := scanAlertStart(line[p.firstNonspace:]); n > 0 {
				*container = p.addChild(*container, mdAlert, p.firstNonspace+1)
				(*container).alertType = typ
				(*container).alertTitle = title
				p.advanceOffset(line, len(line)-1-p.offset, false)
			} else {
				bqStart := p.firstNonspace
				p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
				if isSpaceOrTab(peekAt(line, p.offset)) {
					p.advanceOffset(line, 1, true)
				}
				*container = p.addChild(*container, mdBlockQuote, bqStart+1)
			}
		} else if matched = scanATXHeadingStart(line[p.firstNonspace:]); !indented && matched > 0 {
			hstart := p.firstNonspace
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			*container = p.addChild(*container, mdHeading, hstart+1)
			level := 0
			hp := hstart
			for peekAt(line, hp) == '#' {
				level++
				hp++
			}
			(*container).level = level
			(*container).setext = false
		} else if matched = scanOpenCodeFence(line[p.firstNonspace:]); !indented && matched > 0 {
			*container = p.addChild(*container, mdCodeBlock, p.firstNonspace+1)
			(*container).fenced = true
			(*container).fenceChar = peekAt(line, p.firstNonspace)
			(*container).fenceLength = matched
			(*container).fenceOffset = p.firstNonspace - p.offset
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
		} else if !indented && func() bool {
			matched = scanHTMLBlockStart(line[p.firstNonspace:])
			if matched == 0 && contType != mdParagraph {
				matched = scanHTMLBlockStart7(line[p.firstNonspace:])
			}
			return matched > 0
		}() {
			*container = p.addChild(*container, mdHTMLBlock, p.firstNonspace+1)
			(*container).htmlBlockType = matched
		} else if lev := scanSetextHeadingLine(line[p.firstNonspace:]); !indented && contType == mdParagraph && lev > 0 {
			hasContent := p.resolveReferenceLinkDefinitions(*container)
			if hasContent {
				(*container).kind = mdHeading
				(*container).level = lev
				(*container).setext = true
				p.advanceOffset(line, len(line)-1-p.offset, false)
			}
		} else if !indented && !(contType == mdParagraph && !allMatched) && p.thematicBreakKillPos <= p.firstNonspace && func() bool { matched = p.scanThematicBreak(line, p.firstNonspace); return matched > 0 }() {
			*container = p.addChild(*container, mdThematicBreak, p.firstNonspace+1)
			p.advanceOffset(line, len(line)-1-p.offset, false)
		} else if matched = scanFootnoteDefinition(line[p.firstNonspace:]); !indented && depth < maxListDepth && matched > 0 {
			seg := line[p.firstNonspace+2 : p.firstNonspace+matched]
			k := bytes.LastIndexByte(seg, ']')
			name := string(seg[:k])
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			*container = p.addChild(*container, mdFootnoteDefinition, p.firstNonspace+matched+1)
			(*container).fnName = name
		} else if !indented && c == ':' && p.parseDescListDetails(container, line) {
			// handled
		} else if ml, data := parseListMarker(line, p.firstNonspace, (*container).kind == mdParagraph); (!indented || contType == mdList) && p.indent < 4 && depth < maxListDepth && ml > 0 {
			p.advanceOffset(line, p.firstNonspace+ml-p.offset, false)
			savePCT := p.partiallyConsumedTab
			saveOffset := p.offset
			saveColumn := p.column
			for p.column-saveColumn <= 5 && isSpaceOrTab(peekAt(line, p.offset)) {
				p.advanceOffset(line, 1, true)
			}
			i := p.column - saveColumn
			if i >= 5 || i < 1 || isLineEndChar(peekAt(line, p.offset)) {
				data.padding = ml + 1
				p.offset = saveOffset
				p.column = saveColumn
				p.partiallyConsumedTab = savePCT
				if i > 0 {
					p.advanceOffset(line, 1, true)
				}
			} else {
				data.padding = ml + i
			}
			data.markerOffset = p.indent
			if (*container).kind != mdList || !listsMatch((*container).list, data) {
				*container = p.addChild(*container, mdList, p.firstNonspace+1)
				ld := *data
				(*container).list = &ld
			}
			*container = p.addChild(*container, mdItem, p.firstNonspace+1)
			ld := *data
			(*container).list = &ld
		} else if indented && !maybeLazy && !p.blank {
			p.advanceOffset(line, codeIndent, true)
			*container = p.addChild(*container, mdCodeBlock, p.offset+1)
			(*container).fenced = false
		} else {
			replaced := false
			if !indented {
				if nc, ok := p.tryOpeningTable(*container, line); ok {
					*container = nc
					replaced = true
				}
			}
			if !replaced {
				break
			}
		}
		if acceptsLines((*container).kind) {
			break
		}
		contType = (*container).kind
		maybeLazy = false
	}
}

func scanOpenMultilineBlockQuote(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '>' {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

// parseDescListDetails handles ": details" lines following a term paragraph.
func (p *mdParser) parseDescListDetails(container **mdNode, line []byte) bool {
	// must be ':' followed by space
	nc := peekAt(line, p.firstNonspace+1)
	if !(nc == ' ' || nc == '\t') {
		return false
	}
	tight := true
	lastChild := (*container).lastChild
	cont := *container
	var para *mdNode
	if cont.kind == mdParagraph {
		// details directly after the term, no blank line between
		para = cont
		cont = cont.parent
	} else if lastChild != nil && lastChild.kind == mdParagraph && !lastChild.open {
		para = lastChild
		tight = false
	} else if lastChild != nil && lastChild.kind == mdDescriptionList {
		// another details for the previous item
		item := lastChild.lastChild
		if item == nil {
			return false
		}
		// reopen
		_ = item
	}
	if para != nil {
		// finalize the paragraph
		if para.open {
			p.finalizeNoParent(para)
		}
		if para.parent == nil {
			return false
		}
		parent := para.parent
		var list *mdNode
		if para.prev != nil && para.prev.kind == mdDescriptionList {
			list = para.prev
		} else {
			list = newNode(mdDescriptionList)
			list.startLine = para.startLine
			para.insertBefore(list)
		}
		item := newNode(mdDescriptionItem)
		item.startLine = para.startLine
		item.dMarkerOffset = p.indent
		item.dPadding = 2
		item.dTight = tight
		list.appendChild(item)
		term := newNode(mdDescriptionTerm)
		term.open = false
		item.appendChild(term)
		term.appendChild(para)
		_ = parent
		details := newNode(mdDescriptionDetails)
		details.startLine = p.lineNumber
		item.appendChild(details)
		p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		*container = details
		p.current = details
		return true
	}
	if lastChild != nil && lastChild.kind == mdDescriptionList && lastChild.lastChild != nil {
		item := lastChild.lastChild
		if !lastChild.open {
			lastChild.open = true
		}
		item.open = true
		details := newNode(mdDescriptionDetails)
		details.startLine = p.lineNumber
		item.appendChild(details)
		p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		*container = details
		p.current = details
		return true
	}
	return false
}

func (p *mdParser) finalizeNoParent(b *mdNode) {
	if !b.open {
		return
	}
	// finalize b and any open descendants
	for c := b.lastChild; c != nil && c.open; c = b.lastChild {
		p.finalizeNoParent(c)
		break
	}
	p.finalize(b)
}

func (p *mdParser) addTextToContainer(container, lastMatched *mdNode, line []byte) {
	p.findFirstNonspace(line)
	if p.blank && container.lastChild != nil {
		container.lastChild.lastLineBlank = true
	}
	ctype := container.kind
	lastLineBlank := p.blank && ctype != mdBlockQuote && ctype != mdAlert && ctype != mdHeading && ctype != mdThematicBreak &&
		!(ctype == mdCodeBlock && container.fenced) &&
		!(ctype == mdItem && container.firstChild == nil && container.startLine == p.lineNumber)
	container.lastLineBlank = lastLineBlank
	for tmp := container; tmp.parent != nil; tmp = tmp.parent {
		tmp.parent.lastLineBlank = false
	}

	if p.current != lastMatched && container == lastMatched && !p.blank && p.current.kind == mdParagraph {
		p.addLine(p.current, line)
		return
	}
	for p.current != lastMatched {
		p.current = p.finalize(p.current)
	}
	switch {
	case container.kind == mdCodeBlock:
		p.addLine(container, line)
	case container.kind == mdHTMLBlock:
		p.addLine(container, line)
		if scanHTMLBlockEnd(container.htmlBlockType, line[p.firstNonspace:]) {
			container = p.finalize(container)
		}
	case p.blank:
		// nothing
	case acceptsLines(container.kind):
		if container.kind == mdHeading && !container.setext {
			line = chopTrailingHashtags(line)
		}
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		p.addLine(container, line)
	case container.kind == mdTable || container.kind == mdTableRow:
		// rows are handled by tryOpeningTable
	default:
		container = p.addChild(container, mdParagraph, p.firstNonspace+1)
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		p.addLine(container, line)
	}
	p.current = container
}

func chopTrailingHashtags(line []byte) []byte {
	l := bytes.TrimRight(line, " \t\r\n\v\f")
	n := len(l) - 1
	orig := n
	for n >= 0 && l[n] == '#' {
		n--
	}
	if n != orig && n >= 0 && isSpaceOrTab(l[n]) {
		l = bytes.TrimRight(l[:n], " \t\r\n\v\f")
	} else if n != orig && n < 0 {
		// whole remainder is hashes
		l = l[:0]
	}
	return l
}

func (p *mdParser) finalize(b *mdNode) *mdNode {
	parent := b.parent
	b.open = false
	switch b.kind {
	case mdParagraph:
		hasContent := p.resolveReferenceLinkDefinitions(b)
		if !hasContent {
			b.detach()
		}
	case mdCodeBlock:
		if !b.fenced {
			// remove trailing blank lines
			content := b.content
			lines := bytes.Split(content, []byte("\n"))
			// find last non-blank
			end := len(content)
			for end > 0 {
				// find start of last line
				st := bytes.LastIndexByte(content[:end-1+boolToInt(end > 0 && content[end-1] != '\n')], '\n')
				_ = st
				break
			}
			_ = lines
			b.content = removeTrailingBlankLines(content)
			b.content = append(b.content, '\n')
		} else {
			pos := 0
			for pos < len(b.content) && !isLineEndChar(b.content[pos]) {
				pos++
			}
			infoRaw := b.content[:pos]
			info := strings.TrimSpace(unescapeHTMLEntities(string(infoRaw)))
			info = unescapeBackslash(info)
			b.info = info
			if pos < len(b.content) && b.content[pos] == '\r' {
				pos++
			}
			if pos < len(b.content) && b.content[pos] == '\n' {
				pos++
			}
			b.content = b.content[pos:]
		}
		b.literal = string(b.content)
		b.content = nil
	case mdHTMLBlock:
		b.literal = string(b.content)
		b.content = nil
	case mdList:
		b.list.tight = true
		for item := b.firstChild; item != nil; item = item.next {
			if item.lastLineBlank && item.next != nil {
				b.list.tight = false
				break
			}
			for sub := item.firstChild; sub != nil; sub = sub.next {
				if (item.next != nil || sub.next != nil) && endsWithBlankLine(sub) {
					b.list.tight = false
					break
				}
			}
			if !b.list.tight {
				break
			}
		}
	case mdFootnoteDefinition:
		if _, exists := p.footnoteDefs[normalizeLabel(b.fnName)]; !exists {
			p.footnoteDefs[normalizeLabel(b.fnName)] = b
		}
	}
	return parent
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func removeTrailingBlankLines(content []byte) []byte {
	i := len(content) - 1
	for ; i >= 0; i-- {
		c := content[i]
		if c != ' ' && c != '\t' && !isLineEndChar(c) {
			break
		}
	}
	if i < 0 {
		return content[:0]
	}
	for ; i < len(content); i++ {
		if isLineEndChar(content[i]) {
			break
		}
	}
	return content[:i]
}

func endsWithBlankLine(n *mdNode) bool {
	if n.lastLineChecked {
		return n.lastLineBlank
	}
	if (n.kind == mdList || n.kind == mdItem) && n.lastChild != nil {
		n.lastLineChecked = true
		return endsWithBlankLine(n.lastChild)
	}
	n.lastLineChecked = true
	return n.lastLineBlank
}

func (p *mdParser) resolveReferenceLinkDefinitions(b *mdNode) bool {
	content := b.content
	for len(content) > 0 && content[0] == '[' {
		n := p.parseReferenceInline(content)
		if n == 0 {
			break
		}
		content = content[n:]
	}
	b.content = content
	return !isBlankBytes(b.content)
}

func isBlankBytes(b []byte) bool {
	for _, c := range b {
		if !(c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f') {
			return false
		}
	}
	return true
}

// ---------- tables ----------

type tableCell struct {
	content string
}

func tableCellEnd(s []byte) int {
	if len(s) == 0 || s[0] != '|' {
		return 0
	}
	i := 1
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	return i
}

func tableRowEnd(s []byte) int {
	i := 0
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if i < len(s) && isLineEndChar(s[i]) {
		i++
		if s[i-1] == '\r' && i < len(s) && s[i] == '\n' {
			i++
		}
		return i
	}
	return 0
}

func tableCellScan(s []byte) int {
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '\\' && i+1 < len(s) && s[i+1] == '|' {
			i += 2
			continue
		}
		if c == '|' || isLineEndChar(c) {
			break
		}
		i++
	}
	return i
}

func unescapePipes(s []byte) []byte {
	var out []byte
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) && s[i+1] == '|' {
			out = append(out, '|')
			i++
			continue
		}
		out = append(out, s[i])
	}
	return out
}

type tableRowParse struct {
	paragraphOffset int
	cells           []string
}

func parseTableRow(s []byte) *tableRowParse {
	l := len(s)
	var cells []string
	offset := tableCellEnd(s)
	paragraphOffset := 0
	expectMore := true
	for offset < l && expectMore {
		cellMatched := tableCellScan(s[offset:])
		pipeMatched := tableCellEnd(s[offset+cellMatched:])
		if cellMatched > 0 || pipeMatched > 0 {
			cell := unescapePipes(s[offset : offset+cellMatched])
			cells = append(cells, strings.Trim(string(cell), " \t\r\n\v\f"))
		}
		offset += cellMatched + pipeMatched
		if pipeMatched > 0 {
			expectMore = true
		} else {
			rowEnd := tableRowEnd(s[offset:])
			offset += rowEnd
			if rowEnd > 0 && offset != l {
				paragraphOffset = offset
				cells = nil
				offset += tableCellEnd(s[offset:])
				expectMore = true
			} else {
				expectMore = false
			}
		}
	}
	if offset != l || len(cells) == 0 {
		return nil
	}
	return &tableRowParse{paragraphOffset: paragraphOffset, cells: cells}
}

func tableRowMatches(s []byte) bool {
	return parseTableRow(s) != nil
}

var reTableStart = regexp.MustCompile(`^\|?[ \t]*:?-+:?[ \t]*(\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*\r?\n$`)

func (p *mdParser) tryOpeningTable(container *mdNode, line []byte) (*mdNode, bool) {
	if container.kind == mdParagraph {
		rest := line[p.firstNonspace:]
		if !reTableStart.Match(rest) {
			return nil, false
		}
		delim := parseTableRow(rest)
		if delim == nil {
			return nil, false
		}
		header := parseTableRow(container.content)
		if header == nil {
			return nil, false
		}
		if len(header.cells) != len(delim.cells) {
			return nil, false
		}
		if header.paragraphOffset > 0 {
			// split paragraph: preceding lines remain a paragraph
			para := newNode(mdParagraph)
			para.content = append([]byte{}, container.content[:header.paragraphOffset]...)
			para.startLine = container.startLine
			container.insertBefore(para)
			p.finalize(para)
			if para.parent == nil {
				// all ref defs
			}
		}
		var aligns []byte
		for _, c := range delim.cells {
			left := len(c) > 0 && c[0] == ':'
			right := len(c) > 0 && c[len(c)-1] == ':'
			switch {
			case left && right:
				aligns = append(aligns, 'c')
			case left:
				aligns = append(aligns, 'l')
			case right:
				aligns = append(aligns, 'r')
			default:
				aligns = append(aligns, 0)
			}
		}
		table := newNode(mdTable)
		table.startLine = container.startLine
		table.alignments = aligns
		container.insertAfter(table)
		container.detach()
		if p.current == container {
			p.current = table
		}
		row := newNode(mdTableRow)
		row.isHeader = true
		row.open = false
		table.appendChild(row)
		for _, h := range header.cells {
			cell := newNode(mdTableCell)
			cell.open = false
			cell.content = []byte(h)
			row.appendChild(cell)
		}
		p.advanceOffset(line, len(line)-1-p.offset, false)
		p.current = table
		return table, true
	}
	if container.kind == mdTable {
		if p.blank {
			return nil, false
		}
		r := parseTableRow(line[p.firstNonspace:])
		if r == nil {
			return nil, false
		}
		row := newNode(mdTableRow)
		row.open = false
		container.appendChild(row)
		i := 0
		for ; i < len(container.alignments) && i < len(r.cells); i++ {
			cell := newNode(mdTableCell)
			cell.open = false
			cell.content = []byte(r.cells[i])
			row.appendChild(cell)
		}
		for ; i < len(container.alignments); i++ {
			cell := newNode(mdTableCell)
			cell.open = false
			row.appendChild(cell)
		}
		p.advanceOffset(line, len(line)-1-p.offset, false)
		return container, true
	}
	return nil, false
}
EOF
echo done"}

actions.command:
cat > /workspace/md_block.go <<'EOF'
package main

import (
	"bytes"
	"regexp"
	"strings"
)

const tabStop = 4
const codeIndent = 4
const maxListDepth = 100

type mdRef struct {
	url   string
	title string
}

type mdOptions struct {
	brokenLinkCallback func(label string) (string, string, bool)
}

type mdParser struct {
	root                 *mdNode
	current              *mdNode
	lineNumber           int
	offset               int
	column               int
	firstNonspace        int
	firstNonspaceColumn  int
	indent               int
	blank                bool
	partiallyConsumedTab bool
	thematicBreakKillPos int
	lastLineLength       int
	curline              []byte
	refmap               map[string]*mdRef
	footnoteDefs         map[string]*mdNode
	opts                 mdOptions
	lastBufferEndedCR    bool
}

func newMdParser(opts mdOptions) *mdParser {
	root := newNode(mdDocument)
	root.startLine = 1
	return &mdParser{root: root, current: root, refmap: map[string]*mdRef{}, footnoteDefs: map[string]*mdNode{}, opts: opts}
}

func isLineEndChar(c byte) bool { return c == '\n' || c == '\r' }
func isSpaceOrTab(c byte) bool  { return c == ' ' || c == '\t' }

func peekAt(line []byte, i int) byte {
	if i < 0 || i >= len(line) {
		return 0
	}
	return line[i]
}

func (p *mdParser) findFirstNonspace(line []byte) {
	charsToTab := tabStop - (p.column % tabStop)
	if p.firstNonspace <= p.offset {
		p.firstNonspace = p.offset
		p.firstNonspaceColumn = p.column
		for {
			c := peekAt(line, p.firstNonspace)
			if c == ' ' {
				p.firstNonspace++
				p.firstNonspaceColumn++
				charsToTab--
				if charsToTab == 0 {
					charsToTab = tabStop
				}
			} else if c == '\t' {
				p.firstNonspace++
				p.firstNonspaceColumn += charsToTab
				charsToTab = tabStop
			} else {
				break
			}
		}
	}
	p.indent = p.firstNonspaceColumn - p.column
	p.blank = isLineEndChar(peekAt(line, p.firstNonspace))
}

func (p *mdParser) advanceOffset(line []byte, count int, columns bool) {
	for count > 0 {
		c := peekAt(line, p.offset)
		if c == 0 && p.offset >= len(line) {
			break
		}
		if c == '\t' {
			charsToTab := tabStop - (p.column % tabStop)
			if columns {
				p.partiallyConsumedTab = charsToTab > count
				adv := charsToTab
				if count < adv {
					adv = count
				}
				p.column += adv
				if !p.partiallyConsumedTab {
					p.offset++
				}
				count -= adv
			} else {
				p.partiallyConsumedTab = false
				p.column += charsToTab
				p.offset++
				count--
			}
		} else {
			p.partiallyConsumedTab = false
			p.offset++
			p.column++
			count--
		}
	}
}

func (p *mdParser) addLine(node *mdNode, line []byte) {
	if p.partiallyConsumedTab {
		p.offset++
		charsToTab := tabStop - (p.column % tabStop)
		for i := 0; i < charsToTab; i++ {
			node.content = append(node.content, ' ')
		}
	}
	if p.offset < len(line) {
		node.content = append(node.content, line[p.offset:]...)
	}
}

func (p *mdParser) addChild(parent *mdNode, kind mdKind, startColumn int) *mdNode {
	for !canContain(parent.kind, kind) {
		parent = p.finalize(parent)
	}
	child := newNode(kind)
	child.startLine = p.lineNumber
	child.startColumn = startColumn
	parent.appendChild(child)
	return child
}

func lastChildIsOpen(n *mdNode) bool {
	return n.lastChild != nil && n.lastChild.open
}

// parse feeds the whole document.
func (p *mdParser) parse(text string) *mdNode {
	buf := []byte(text)
	// split into lines, keeping line endings
	start := 0
	for i := 0; i < len(buf); i++ {
		c := buf[i]
		if c == '\n' || c == '\r' {
			end := i + 1
			if c == '\r' && i+1 < len(buf) && buf[i+1] == '\n' {
				end = i + 2
				i++
			}
			p.processLine(buf[start:end])
			start = end
		}
	}
	if start < len(buf) {
		p.processLine(buf[start:])
	}
	p.finish()
	return p.root
}

func (p *mdParser) finish() {
	p.curline = nil
	for p.current != p.root {
		p.current = p.finalize(p.current)
	}
	p.finalize(p.root)
	p.processInlines()
	p.postprocess()
}

func (p *mdParser) processLine(raw []byte) {
	line := make([]byte, 0, len(raw)+1)
	for _, c := range raw {
		if c == 0 {
			line = append(line, "\uFFFD"...)
		} else {
			line = append(line, c)
		}
	}
	// normalize line ending to \n
	if n := len(line); n > 0 && line[n-1] == '\n' {
		line = line[:n-1]
	}
	if n := len(line); n > 0 && line[n-1] == '\r' {
		line = line[:n-1]
	}
	line = append(line, '\n')
	p.curline = line
	p.offset = 0
	p.column = 0
	p.firstNonspace = 0
	p.firstNonspaceColumn = 0
	p.thematicBreakKillPos = 0
	p.indent = 0
	p.blank = false
	p.partiallyConsumedTab = false
	p.lineNumber++

	allMatched := false
	lastMatched := p.checkOpenBlocks(line, &allMatched)
	if lastMatched != nil {
		container := lastMatched
		current := p.current
		p.openNewBlocks(&container, line, allMatched)
		if current == p.current {
			p.addTextToContainer(container, lastMatched, line)
		}
	}
	p.lastLineLength = len(line) - 1
}

func (p *mdParser) checkOpenBlocks(line []byte, allMatched *bool) *mdNode {
	shouldContinue := true
	*allMatched = false
	container := p.root
	matchedAll := true
	for lastChildIsOpen(container) {
		container = container.lastChild
		p.findFirstNonspace(line)
		ok := true
		switch container.kind {
		case mdBlockQuote:
			ok = p.parseBlockQuotePrefix(line)
		case mdAlert:
			if container.alertMulti {
				ok = p.parseMultilineBlockQuotePrefix(line, container, &shouldContinue)
			} else {
				ok = p.parseBlockQuotePrefix(line)
			}
		case mdMultilineBlockQuote:
			ok = p.parseMultilineBlockQuotePrefix(line, container, &shouldContinue)
		case mdItem:
			ok = p.parseNodeItemPrefix(line, container)
		case mdDescriptionItem:
			ok = p.parseDescriptionItemPrefix(line, container)
		case mdCodeBlock:
			ok = p.parseCodeBlockPrefix(line, container, &shouldContinue)
		case mdHeading:
			ok = false
		case mdHTMLBlock:
			ok = p.parseHTMLBlockPrefix(container)
		case mdParagraph:
			ok = !p.blank
		case mdTable:
			ok = !p.blank && tableRowMatches(line[p.firstNonspace:])
		case mdTableRow, mdTableCell:
			ok = false
		case mdFootnoteDefinition:
			ok = p.parseFootnoteDefinitionPrefix(line)
		case mdDescriptionTerm:
			ok = false
		case mdDescriptionDetails:
			ok = true
		}
		if !ok {
			matchedAll = false
			break
		}
		if !shouldContinue {
			break
		}
	}
	if matchedAll {
		*allMatched = true
	} else {
		container = container.parent
	}
	if !shouldContinue {
		return nil
	}
	return container
}

func (p *mdParser) parseBlockQuotePrefix(line []byte) bool {
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == '>' {
		p.advanceOffset(line, p.indent+1, true)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		return true
	}
	return false
}

func (p *mdParser) parseMultilineBlockQuotePrefix(line []byte, container *mdNode, shouldContinue *bool) bool {
	matched := 0
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == '>' {
		matched = scanCloseMultilineBlockQuote(line[p.firstNonspace:])
	}
	if matched >= container.mbqFenceLength && matched > 0 {
		*shouldContinue = false
		p.advanceOffset(line, matched, false)
		// close the block quote
		cur := p.current
		for cur != container && cur != nil {
			cur = p.finalize(cur)
		}
		p.current = p.finalize(container)
		return false
	}
	i := container.mbqFenceOffset
	for i > 0 && isSpaceOrTab(peekAt(line, p.offset)) {
		p.advanceOffset(line, 1, true)
		i--
	}
	return true
}

func scanCloseMultilineBlockQuote(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '>' {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

func (p *mdParser) parseNodeItemPrefix(line []byte, container *mdNode) bool {
	ld := container.list
	if p.indent >= ld.markerOffset+ld.padding {
		p.advanceOffset(line, ld.markerOffset+ld.padding, true)
		return true
	} else if p.blank && container.firstChild != nil {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseDescriptionItemPrefix(line []byte, container *mdNode) bool {
	if p.indent >= container.dMarkerOffset+container.dPadding {
		p.advanceOffset(line, container.dMarkerOffset+container.dPadding, true)
		return true
	} else if p.blank && container.firstChild != nil {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseFootnoteDefinitionPrefix(line []byte) bool {
	if p.indent >= 4 {
		p.advanceOffset(line, 4, true)
		return true
	} else if p.blank {
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		return true
	}
	return false
}

func (p *mdParser) parseCodeBlockPrefix(line []byte, container *mdNode, shouldContinue *bool) bool {
	if !container.fenced {
		if p.indent >= codeIndent {
			p.advanceOffset(line, codeIndent, true)
			return true
		} else if p.blank {
			p.advanceOffset(line, p.firstNonspace-p.offset, false)
			return true
		}
		return false
	}
	matched := 0
	if p.indent <= 3 && peekAt(line, p.firstNonspace) == container.fenceChar {
		matched = scanCloseCodeFence(line[p.firstNonspace:])
	}
	if matched >= container.fenceLength {
		*shouldContinue = false
		p.advanceOffset(line, matched, false)
		p.current = p.finalize(container)
		return false
	}
	i := container.fenceOffset
	for i > 0 && isSpaceOrTab(peekAt(line, p.offset)) {
		p.advanceOffset(line, 1, true)
		i--
	}
	return true
}

func (p *mdParser) parseHTMLBlockPrefix(container *mdNode) bool {
	switch container.htmlBlockType {
	case 1, 2, 3, 4, 5:
		return true
	case 6, 7:
		return !p.blank
	}
	return false
}

func scanCloseCodeFence(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '`' && c != '~' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

func scanOpenCodeFence(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '`' && c != '~' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	if i < 3 {
		return 0
	}
	// rest of line
	for j := i; j < len(s); j++ {
		if isLineEndChar(s[j]) {
			break
		}
		if c == '`' && s[j] == '`' {
			return 0
		}
	}
	return i
}

func scanATXHeadingStart(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '#' {
		i++
	}
	if i < 1 || i > 6 {
		return 0
	}
	if i < len(s) && isLineEndChar(s[i]) {
		return i
	}
	if i < len(s) && isSpaceOrTab(s[i]) {
		j := i
		for j < len(s) && isSpaceOrTab(s[j]) {
			j++
		}
		return j
	}
	return 0
}

func scanSetextHeadingLine(s []byte) int {
	if len(s) == 0 {
		return 0
	}
	c := s[0]
	if c != '=' && c != '-' {
		return 0
	}
	i := 0
	for i < len(s) && s[i] == c {
		i++
	}
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if i < len(s) && isLineEndChar(s[i]) {
		if c == '=' {
			return 1
		}
		return 2
	}
	return 0
}

func (p *mdParser) scanThematicBreak(line []byte, offset int) int {
	i := offset
	c := peekAt(line, i)
	if !(c == '*' || c == '_' || c == '-') {
		p.thematicBreakKillPos = i
		return 0
	}
	count := 1
	var nextc byte
	for {
		i++
		nextc = peekAt(line, i)
		if nextc == 0 {
			break
		}
		if nextc == c {
			count++
		} else if nextc != ' ' && nextc != '\t' {
			break
		}
	}
	if count >= 3 && (nextc == '\r' || nextc == '\n') {
		return (i - offset) + 1
	}
	p.thematicBreakKillPos = i
	return 0
}

var htmlBlockType6Tags = map[string]bool{}

func init() {
	for _, t := range strings.Split("address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h1|h2|h3|h4|h5|h6|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|search|section|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul", "|") {
		htmlBlockType6Tags[t] = true
	}
}

func isASCIIAlpha(c byte) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') }
func isASCIIDigit(c byte) bool { return c >= '0' && c <= '9' }
func isASCIIAlnum(c byte) bool { return isASCIIAlpha(c) || isASCIIDigit(c) }

func hasPrefixFold(s []byte, prefix string) bool {
	if len(s) < len(prefix) {
		return false
	}
	return strings.EqualFold(string(s[:len(prefix)]), prefix)
}

func scanHTMLBlockStart(s []byte) int {
	if len(s) < 2 || s[0] != '<' {
		return 0
	}
	for _, t := range []string{"script", "pre", "style", "textarea"} {
		if hasPrefixFold(s[1:], t) {
			n := 1 + len(t)
			c := peekAt(s, n)
			if c == ' ' || c == '\t' || c == '>' || isLineEndChar(c) || c == 0 {
				return 1
			}
		}
	}
	if bytes.HasPrefix(s, []byte("<!--")) {
		return 2
	}
	if bytes.HasPrefix(s, []byte("<?")) {
		return 3
	}
	if len(s) >= 3 && s[1] == '!' && isASCIIAlpha(s[2]) {
		return 4
	}
	if bytes.HasPrefix(s, []byte("<![CDATA[")) {
		return 5
	}
	i := 1
	if peekAt(s, i) == '/' {
		i++
	}
	j := i
	for j < len(s) && isASCIIAlnum(s[j]) {
		j++
	}
	if j > i {
		name := strings.ToLower(string(s[i:j]))
		if htmlBlockType6Tags[name] {
			c := peekAt(s, j)
			if c == ' ' || c == '\t' || c == '>' || isLineEndChar(c) || c == 0 {
				return 6
			}
			if c == '/' && peekAt(s, j+1) == '>' {
				return 6
			}
		}
	}
	return 0
}

var reHTMLOpenTag = regexp.MustCompile(`^<[A-Za-z][A-Za-z0-9-]*(?:[ \t\n\r\f\v]+[a-zA-Z_:][a-zA-Z0-9_.:-]*(?:[ \t\n\r\f\v]*=[ \t\n\r\f\v]*(?:[^ \t\n\r\f\v"'=<>` + "`" + `\x00]+|'[^']*'|"[^"]*"))?)*[ \t\n\r\f\v]*/?>`)
var reHTMLCloseTag = regexp.MustCompile(`^</[A-Za-z][A-Za-z0-9-]*[ \t\n\r\f\v]*>`)

func scanHTMLBlockStart7(s []byte) int {
	var m []int
	if m = reHTMLOpenTag.FindIndex(s); m == nil {
		m = reHTMLCloseTag.FindIndex(s)
	}
	if m == nil {
		return 0
	}
	// tag name must not be script/style/pre/textarea
	k := 1
	if peekAt(s, 1) == '/' {
		k = 2
	}
	e := k
	for e < len(s) && (isASCIIAlnum(s[e]) || s[e] == '-') {
		e++
	}
	name := strings.ToLower(string(s[k:e]))
	if name == "script" || name == "style" || name == "pre" || name == "textarea" {
		return 0
	}
	rest := s[m[1]:]
	i := 0
	for i < len(rest) && (rest[i] == ' ' || rest[i] == '\t') {
		i++
	}
	if i < len(rest) && isLineEndChar(rest[i]) {
		return 7
	}
	if i == len(rest) {
		return 7
	}
	return 0
}

func scanHTMLBlockEnd(t int, s []byte) bool {
	ls := bytes.ToLower(s)
	switch t {
	case 1:
		return bytes.Contains(ls, []byte("</script>")) || bytes.Contains(ls, []byte("</pre>")) || bytes.Contains(ls, []byte("</style>")) || bytes.Contains(ls, []byte("</textarea>"))
	case 2:
		return bytes.Contains(s, []byte("-->"))
	case 3:
		return bytes.Contains(s, []byte("?>"))
	case 4:
		return bytes.Contains(s, []byte(">"))
	case 5:
		return bytes.Contains(s, []byte("]]>"))
	}
	return false
}

func parseListMarker(line []byte, pos int, interruptsParagraph bool) (int, *mdListData) {
	startpos := pos
	c := peekAt(line, pos)
	var data *mdListData
	if c == '*' || c == '-' || c == '+' {
		pos++
		nc := peekAt(line, pos)
		if !(nc == ' ' || nc == '\t' || nc == '\n' || nc == '\r' || nc == '\v' || nc == '\f') {
			return 0, nil
		}
		if interruptsParagraph {
			i := pos
			for isSpaceOrTab(peekAt(line, i)) {
				i++
			}
			if peekAt(line, i) == '\n' {
				return 0, nil
			}
		}
		data = &mdListData{ordered: false, bulletChar: c}
	} else if isASCIIDigit(c) {
		start := 0
		digits := 0
		for {
			start = 10*start + int(peekAt(line, pos)-'0')
			pos++
			digits++
			if !(digits < 9 && isASCIIDigit(peekAt(line, pos))) {
				break
			}
		}
		if interruptsParagraph && start != 1 {
			return 0, nil
		}
		c = peekAt(line, pos)
		if c == '.' || c == ')' {
			pos++
			nc := peekAt(line, pos)
			if !(nc == ' ' || nc == '\t' || nc == '\n' || nc == '\r' || nc == '\v' || nc == '\f') {
				return 0, nil
			}
			if interruptsParagraph {
				i := pos
				for isSpaceOrTab(peekAt(line, i)) {
					i++
				}
				if isLineEndChar(peekAt(line, i)) {
					return 0, nil
				}
			}
			data = &mdListData{ordered: true, start: start, delimiter: c}
		} else {
			return 0, nil
		}
	} else {
		return 0, nil
	}
	return pos - startpos, data
}

func listsMatch(a, b *mdListData) bool {
	return a.ordered == b.ordered && a.delimiter == b.delimiter && a.bulletChar == b.bulletChar
}

// scanFootnoteDefinition matches "[^label]:" followed by optional spaces.
func scanFootnoteDefinition(s []byte) int {
	if len(s) < 4 || s[0] != '[' || s[1] != '^' {
		return 0
	}
	i := 2
	for i < len(s) && s[i] != ']' {
		c := s[i]
		if c == '[' || c == ' ' || c == '\t' || isLineEndChar(c) || c == 0 {
			return 0
		}
		i++
	}
	if i == 2 || i >= len(s) {
		return 0
	}
	i++ // ]
	if peekAt(s, i) != ':' {
		return 0
	}
	i++
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	return i
}

var alertTypes = map[string]string{"note": "Note", "tip": "Tip", "important": "Important", "warning": "Warning", "caution": "Caution"}

// scanAlertStart matches "> [!TYPE]" at the given position (s starts with '>').
func scanAlertStart(s []byte) (int, string, string) {
	i := 1
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if !bytes.HasPrefix(s[i:], []byte("[!")) {
		return 0, "", ""
	}
	i += 2
	j := i
	for j < len(s) && isASCIIAlpha(s[j]) {
		j++
	}
	if j >= len(s) || s[j] != ']' {
		return 0, "", ""
	}
	typ := strings.ToLower(string(s[i:j]))
	if _, ok := alertTypes[typ]; !ok {
		return 0, "", ""
	}
	j++
	// title: rest of line
	k := j
	for k < len(s) && !isLineEndChar(s[k]) {
		k++
	}
	title := strings.TrimSpace(string(s[j:k]))
	if j < len(s) && !isLineEndChar(s[j]) && !isSpaceOrTab(s[j]) {
		return 0, "", ""
	}
	return k, typ, title
}

func (p *mdParser) openNewBlocks(container **mdNode, line []byte, allMatched bool) {
	maybeLazy := p.current.kind == mdParagraph
	contType := (*container).kind
	depth := 0
	for n := *container; n != nil; n = n.parent {
		depth++
	}
	for contType != mdCodeBlock && contType != mdHTMLBlock {
		p.findFirstNonspace(line)
		indented := p.indent >= codeIndent
		c := peekAt(line, p.firstNonspace)
		matched := 0

		if !indented && c == '>' && scanOpenMultilineBlockQuote(line[p.firstNonspace:]) > 0 {
			matched = scanOpenMultilineBlockQuote(line[p.firstNonspace:])
			offset := p.firstNonspace - p.offset
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			// skip to end of line
			*container = p.addChild(*container, mdMultilineBlockQuote, p.firstNonspace+1)
			(*container).mbqFenceLength = matched
			(*container).mbqFenceOffset = offset
			p.advanceOffset(line, len(line)-1-p.offset, false)
		} else if !indented && c == '>' {
			if n, typ, title := scanAlertStart(line[p.firstNonspace:]); n > 0 {
				*container = p.addChild(*container, mdAlert, p.firstNonspace+1)
				(*container).alertType = typ
				(*container).alertTitle = title
				p.advanceOffset(line, len(line)-1-p.offset, false)
			} else {
				bqStart := p.firstNonspace
				p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
				if isSpaceOrTab(peekAt(line, p.offset)) {
					p.advanceOffset(line, 1, true)
				}
				*container = p.addChild(*container, mdBlockQuote, bqStart+1)
			}
		} else if matched = scanATXHeadingStart(line[p.firstNonspace:]); !indented && matched > 0 {
			hstart := p.firstNonspace
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			*container = p.addChild(*container, mdHeading, hstart+1)
			level := 0
			hp := hstart
			for peekAt(line, hp) == '#' {
				level++
				hp++
			}
			(*container).level = level
			(*container).setext = false
		} else if matched = scanOpenCodeFence(line[p.firstNonspace:]); !indented && matched > 0 {
			*container = p.addChild(*container, mdCodeBlock, p.firstNonspace+1)
			(*container).fenced = true
			(*container).fenceChar = peekAt(line, p.firstNonspace)
			(*container).fenceLength = matched
			(*container).fenceOffset = p.firstNonspace - p.offset
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
		} else if !indented && func() bool {
			matched = scanHTMLBlockStart(line[p.firstNonspace:])
			if matched == 0 && contType != mdParagraph {
				matched = scanHTMLBlockStart7(line[p.firstNonspace:])
			}
			return matched > 0
		}() {
			*container = p.addChild(*container, mdHTMLBlock, p.firstNonspace+1)
			(*container).htmlBlockType = matched
		} else if lev := scanSetextHeadingLine(line[p.firstNonspace:]); !indented && contType == mdParagraph && lev > 0 {
			hasContent := p.resolveReferenceLinkDefinitions(*container)
			if hasContent {
				(*container).kind = mdHeading
				(*container).level = lev
				(*container).setext = true
				p.advanceOffset(line, len(line)-1-p.offset, false)
			}
		} else if !indented && !(contType == mdParagraph && !allMatched) && p.thematicBreakKillPos <= p.firstNonspace && func() bool { matched = p.scanThematicBreak(line, p.firstNonspace); return matched > 0 }() {
			*container = p.addChild(*container, mdThematicBreak, p.firstNonspace+1)
			p.advanceOffset(line, len(line)-1-p.offset, false)
		} else if matched = scanFootnoteDefinition(line[p.firstNonspace:]); !indented && depth < maxListDepth && matched > 0 {
			seg := line[p.firstNonspace+2 : p.firstNonspace+matched]
			k := bytes.LastIndexByte(seg, ']')
			name := string(seg[:k])
			p.advanceOffset(line, p.firstNonspace+matched-p.offset, false)
			*container = p.addChild(*container, mdFootnoteDefinition, p.firstNonspace+matched+1)
			(*container).fnName = name
		} else if !indented && c == ':' && p.parseDescListDetails(container, line) {
			// handled
		} else if ml, data := parseListMarker(line, p.firstNonspace, (*container).kind == mdParagraph); (!indented || contType == mdList) && p.indent < 4 && depth < maxListDepth && ml > 0 {
			p.advanceOffset(line, p.firstNonspace+ml-p.offset, false)
			savePCT := p.partiallyConsumedTab
			saveOffset := p.offset
			saveColumn := p.column
			for p.column-saveColumn <= 5 && isSpaceOrTab(peekAt(line, p.offset)) {
				p.advanceOffset(line, 1, true)
			}
			i := p.column - saveColumn
			if i >= 5 || i < 1 || isLineEndChar(peekAt(line, p.offset)) {
				data.padding = ml + 1
				p.offset = saveOffset
				p.column = saveColumn
				p.partiallyConsumedTab = savePCT
				if i > 0 {
					p.advanceOffset(line, 1, true)
				}
			} else {
				data.padding = ml + i
			}
			data.markerOffset = p.indent
			if (*container).kind != mdList || !listsMatch((*container).list, data) {
				*container = p.addChild(*container, mdList, p.firstNonspace+1)
				ld := *data
				(*container).list = &ld
			}
			*container = p.addChild(*container, mdItem, p.firstNonspace+1)
			ld := *data
			(*container).list = &ld
		} else if indented && !maybeLazy && !p.blank {
			p.advanceOffset(line, codeIndent, true)
			*container = p.addChild(*container, mdCodeBlock, p.offset+1)
			(*container).fenced = false
		} else {
			replaced := false
			if !indented {
				if nc, ok := p.tryOpeningTable(*container, line); ok {
					*container = nc
					replaced = true
				}
			}
			if !replaced {
				break
			}
		}
		if acceptsLines((*container).kind) {
			break
		}
		contType = (*container).kind
		maybeLazy = false
	}
}

func scanOpenMultilineBlockQuote(s []byte) int {
	i := 0
	for i < len(s) && s[i] == '>' {
		i++
	}
	if i < 3 {
		return 0
	}
	j := i
	for j < len(s) && isSpaceOrTab(s[j]) {
		j++
	}
	if j < len(s) && isLineEndChar(s[j]) {
		return i
	}
	return 0
}

// parseDescListDetails handles ": details" lines following a term paragraph.
func (p *mdParser) parseDescListDetails(container **mdNode, line []byte) bool {
	// must be ':' followed by space
	nc := peekAt(line, p.firstNonspace+1)
	if !(nc == ' ' || nc == '\t') {
		return false
	}
	tight := true
	lastChild := (*container).lastChild
	cont := *container
	var para *mdNode
	if cont.kind == mdParagraph {
		// details directly after the term, no blank line between
		para = cont
		cont = cont.parent
	} else if lastChild != nil && lastChild.kind == mdParagraph && !lastChild.open {
		para = lastChild
		tight = false
	} else if lastChild != nil && lastChild.kind == mdDescriptionList {
		// another details for the previous item
		item := lastChild.lastChild
		if item == nil {
			return false
		}
		// reopen
		_ = item
	}
	if para != nil {
		// finalize the paragraph
		if para.open {
			p.finalizeNoParent(para)
		}
		if para.parent == nil {
			return false
		}
		parent := para.parent
		var list *mdNode
		if para.prev != nil && para.prev.kind == mdDescriptionList {
			list = para.prev
		} else {
			list = newNode(mdDescriptionList)
			list.startLine = para.startLine
			para.insertBefore(list)
		}
		item := newNode(mdDescriptionItem)
		item.startLine = para.startLine
		item.dMarkerOffset = p.indent
		item.dPadding = 2
		item.dTight = tight
		list.appendChild(item)
		term := newNode(mdDescriptionTerm)
		term.open = false
		item.appendChild(term)
		term.appendChild(para)
		_ = parent
		details := newNode(mdDescriptionDetails)
		details.startLine = p.lineNumber
		item.appendChild(details)
		p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		*container = details
		p.current = details
		return true
	}
	if lastChild != nil && lastChild.kind == mdDescriptionList && lastChild.lastChild != nil {
		item := lastChild.lastChild
		if !lastChild.open {
			lastChild.open = true
		}
		item.open = true
		details := newNode(mdDescriptionDetails)
		details.startLine = p.lineNumber
		item.appendChild(details)
		p.advanceOffset(line, p.firstNonspace+1-p.offset, false)
		if isSpaceOrTab(peekAt(line, p.offset)) {
			p.advanceOffset(line, 1, true)
		}
		*container = details
		p.current = details
		return true
	}
	return false
}

func (p *mdParser) finalizeNoParent(b *mdNode) {
	if !b.open {
		return
	}
	// finalize b and any open descendants
	for c := b.lastChild; c != nil && c.open; c = b.lastChild {
		p.finalizeNoParent(c)
		break
	}
	p.finalize(b)
}

func (p *mdParser) addTextToContainer(container, lastMatched *mdNode, line []byte) {
	p.findFirstNonspace(line)
	if p.blank && container.lastChild != nil {
		container.lastChild.lastLineBlank = true
	}
	ctype := container.kind
	lastLineBlank := p.blank && ctype != mdBlockQuote && ctype != mdAlert && ctype != mdHeading && ctype != mdThematicBreak &&
		!(ctype == mdCodeBlock && container.fenced) &&
		!(ctype == mdItem && container.firstChild == nil && container.startLine == p.lineNumber)
	container.lastLineBlank = lastLineBlank
	for tmp := container; tmp.parent != nil; tmp = tmp.parent {
		tmp.parent.lastLineBlank = false
	}

	if p.current != lastMatched && container == lastMatched && !p.blank && p.current.kind == mdParagraph {
		p.addLine(p.current, line)
		return
	}
	for p.current != lastMatched {
		p.current = p.finalize(p.current)
	}
	switch {
	case container.kind == mdCodeBlock:
		p.addLine(container, line)
	case container.kind == mdHTMLBlock:
		p.addLine(container, line)
		if scanHTMLBlockEnd(container.htmlBlockType, line[p.firstNonspace:]) {
			container = p.finalize(container)
		}
	case p.blank:
		// nothing
	case acceptsLines(container.kind):
		if container.kind == mdHeading && !container.setext {
			line = chopTrailingHashtags(line)
		}
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		p.addLine(container, line)
	case container.kind == mdTable || container.kind == mdTableRow:
		// rows are handled by tryOpeningTable
	default:
		container = p.addChild(container, mdParagraph, p.firstNonspace+1)
		p.advanceOffset(line, p.firstNonspace-p.offset, false)
		p.addLine(container, line)
	}
	p.current = container
}

func chopTrailingHashtags(line []byte) []byte {
	l := bytes.TrimRight(line, " \t\r\n\v\f")
	n := len(l) - 1
	orig := n
	for n >= 0 && l[n] == '#' {
		n--
	}
	if n != orig && n >= 0 && isSpaceOrTab(l[n]) {
		l = bytes.TrimRight(l[:n], " \t\r\n\v\f")
	} else if n != orig && n < 0 {
		// whole remainder is hashes
		l = l[:0]
	}
	return l
}

func (p *mdParser) finalize(b *mdNode) *mdNode {
	parent := b.parent
	b.open = false
	switch b.kind {
	case mdParagraph:
		hasContent := p.resolveReferenceLinkDefinitions(b)
		if !hasContent {
			b.detach()
		}
	case mdCodeBlock:
		if !b.fenced {
			// remove trailing blank lines
			content := b.content
			lines := bytes.Split(content, []byte("\n"))
			// find last non-blank
			end := len(content)
			for end > 0 {
				// find start of last line
				st := bytes.LastIndexByte(content[:end-1+boolToInt(end > 0 && content[end-1] != '\n')], '\n')
				_ = st
				break
			}
			_ = lines
			b.content = removeTrailingBlankLines(content)
			b.content = append(b.content, '\n')
		} else {
			pos := 0
			for pos < len(b.content) && !isLineEndChar(b.content[pos]) {
				pos++
			}
			infoRaw := b.content[:pos]
			info := strings.TrimSpace(unescapeHTMLEntities(string(infoRaw)))
			info = unescapeBackslash(info)
			b.info = info
			if pos < len(b.content) && b.content[pos] == '\r' {
				pos++
			}
			if pos < len(b.content) && b.content[pos] == '\n' {
				pos++
			}
			b.content = b.content[pos:]
		}
		b.literal = string(b.content)
		b.content = nil
	case mdHTMLBlock:
		b.literal = string(b.content)
		b.content = nil
	case mdList:
		b.list.tight = true
		for item := b.firstChild; item != nil; item = item.next {
			if item.lastLineBlank && item.next != nil {
				b.list.tight = false
				break
			}
			for sub := item.firstChild; sub != nil; sub = sub.next {
				if (item.next != nil || sub.next != nil) && endsWithBlankLine(sub) {
					b.list.tight = false
					break
				}
			}
			if !b.list.tight {
				break
			}
		}
	case mdFootnoteDefinition:
		if _, exists := p.footnoteDefs[normalizeLabel(b.fnName)]; !exists {
			p.footnoteDefs[normalizeLabel(b.fnName)] = b
		}
	}
	return parent
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func removeTrailingBlankLines(content []byte) []byte {
	i := len(content) - 1
	for ; i >= 0; i-- {
		c := content[i]
		if c != ' ' && c != '\t' && !isLineEndChar(c) {
			break
		}
	}
	if i < 0 {
		return content[:0]
	}
	for ; i < len(content); i++ {
		if isLineEndChar(content[i]) {
			break
		}
	}
	return content[:i]
}

func endsWithBlankLine(n *mdNode) bool {
	if n.lastLineChecked {
		return n.lastLineBlank
	}
	if (n.kind == mdList || n.kind == mdItem) && n.lastChild != nil {
		n.lastLineChecked = true
		return endsWithBlankLine(n.lastChild)
	}
	n.lastLineChecked = true
	return n.lastLineBlank
}

func (p *mdParser) resolveReferenceLinkDefinitions(b *mdNode) bool {
	content := b.content
	for len(content) > 0 && content[0] == '[' {
		n := p.parseReferenceInline(content)
		if n == 0 {
			break
		}
		content = content[n:]
	}
	b.content = content
	return !isBlankBytes(b.content)
}

func isBlankBytes(b []byte) bool {
	for _, c := range b {
		if !(c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f') {
			return false
		}
	}
	return true
}

// ---------- tables ----------

type tableCell struct {
	content string
}

func tableCellEnd(s []byte) int {
	if len(s) == 0 || s[0] != '|' {
		return 0
	}
	i := 1
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	return i
}

func tableRowEnd(s []byte) int {
	i := 0
	for i < len(s) && isSpaceOrTab(s[i]) {
		i++
	}
	if i < len(s) && isLineEndChar(s[i]) {
		i++
		if s[i-1] == '\r' && i < len(s) && s[i] == '\n' {
			i++
		}
		return i
	}
	return 0
}

func tableCellScan(s []byte) int {
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '\\' && i+1 < len(s) && s[i+1] == '|' {
			i += 2
			continue
		}
		if c == '|' || isLineEndChar(c) {
			break
		}
		i++
	}
	return i
}

func unescapePipes(s []byte) []byte {
	var out []byte
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) && s[i+1] == '|' {
			out = append(out, '|')
			i++
			continue
		}
		out = append(out, s[i])
	}
	return out
}

type tableRowParse struct {
	paragraphOffset int
	cells           []string
}

func parseTableRow(s []byte) *tableRowParse {
	l := len(s)
	var cells []string
	offset := tableCellEnd(s)
	paragraphOffset := 0
	expectMore := true
	for offset < l && expectMore {
		cellMatched := tableCellScan(s[offset:])
		pipeMatched := tableCellEnd(s[offset+cellMatched:])
		if cellMatched > 0 || pipeMatched > 0 {
			cell := unescapePipes(s[offset : offset+cellMatched])
			cells = append(cells, strings.Trim(string(cell), " \t\r\n\v\f"))
		}
		offset += cellMatched + pipeMatched
		if pipeMatched > 0 {
			expectMore = true
		} else {
			rowEnd := tableRowEnd(s[offset:])
			offset += rowEnd
			if rowEnd > 0 && offset != l {
				paragraphOffset = offset
				cells = nil
				offset += tableCellEnd(s[offset:])
				expectMore = true
			} else {
				expectMore = false
			}
		}
	}
	if offset != l || len(cells) == 0 {
		return nil
	}
	return &tableRowParse{paragraphOffset: paragraphOffset, cells: cells}
}

func tableRowMatches(s []byte) bool {
	return parseTableRow(s) != nil
}

var reTableStart = regexp.MustCompile(`^\|?[ \t]*:?-+:?[ \t]*(\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*\r?\n$`)

func (p *mdParser) tryOpeningTable(container *mdNode, line []byte) (*mdNode, bool) {
	if container.kind == mdParagraph {
		rest := line[p.firstNonspace:]
		if !reTableStart.Match(rest) {
			return nil, false
		}
		delim := parseTableRow(rest)
		if delim == nil {
			return nil, false
		}
		header := parseTableRow(container.content)
		if header == nil {
			return nil, false
		}
		if len(header.cells) != len(delim.cells) {
			return nil, false
		}
		if header.paragraphOffset > 0 {
			// split paragraph: preceding lines remain a paragraph
			para := newNode(mdParagraph)
			para.content = append([]byte{}, container.content[:header.paragraphOffset]...)
			para.startLine = container.startLine
			container.insertBefore(para)
			p.finalize(para)
			if para.parent == nil {
				// all ref defs
			}
		}
		var aligns []byte
		for _, c := range delim.cells {
			left := len(c) > 0 && c[0] == ':'
			right := len(c) > 0 && c[len(c)-1] == ':'
			switch {
			case left && right:
				aligns = append(aligns, 'c')
			case left:
				aligns = append(aligns, 'l')
			case right:
				aligns = append(aligns, 'r')
			default:
				aligns = append(aligns, 0)
			}
		}
		table := newNode(mdTable)
		table.startLine = container.startLine
		table.alignments = aligns
		container.insertAfter(table)
		container.detach()
		if p.current == container {
			p.current = table
		}
		row := newNode(mdTableRow)
		row.isHeader = true
		row.open = false
		table.appendChild(row)
		for _, h := range header.cells {
			cell := newNode(mdTableCell)
			cell.open = false
			cell.content = []byte(h)
			row.appendChild(cell)
		}
		p.advanceOffset(line, len(line)-1-p.offset, false)
		p.current = table
		return table, true
	}
	if container.kind == mdTable {
		if p.blank {
			return nil, false
		}
		r := parseTableRow(line[p.firstNonspace:])
		if r == nil {
			return nil, false
		}
		row := newNode(mdTableRow)
		row.open = false
		container.appendChild(row)
		i := 0
		for ; i < len(container.alignments) && i < len(r.cells); i++ {
			cell := newNode(mdTableCell)
			cell.open = false
			cell.content = []byte(r.cells[i])
			row.appendChild(cell)
		}
		for ; i < len(container.alignments); i++ {
			cell := newNode(mdTableCell)
			cell.open = false
			row.appendChild(cell)
		}
		p.advanceOffset(line, len(line)-1-p.offset, false)
		return container, true
	}
	return nil, false
}
