		return 0
	}
	s.pos += n
	beforeTitle := s.pos
	s.spnl()
	matchlen := 0
	if s.pos != beforeTitle {
		matchlen = scanLinkTitle(s.input, s.pos)
	}
	title := ""
	if matchlen > 0 {
		title = string(s.input[s.pos : s.pos+matchlen])
		s.pos += matchlen
	} else {
		s.pos = beforeTitle
	}
	s.skipSpaces()
	if !s.skipLineEndStrict() {
		if matchlen > 0 {
			s.pos = beforeTitle
			s.skipSpaces()
			if !s.skipLineEndStrict() {
