	if strings.HasPrefix(lab, "^") {
		// footnote-like labels are not reference definitions
	}
	if _, exists := p.refmap[norm]; !exists {
		p.refmap[norm] = &mdRef{url: cleanURL(urlChunk), title: cleanTitle(title)}
	}
	return s.pos
}

func (s *mdSubject) skipLineEndStrict() bool {
	if s.eof() {
		return true
	}
	seen := false
	if s.peek() == '\r' {
		s.pos++
		seen = true
	}
	if s.peek() == '\n' {
		s.pos++
		seen = true
	}
	return seen
}

func (s *mdSubject) spnl() {
	s.skipSpaces()
	if s.skipLineEndStrictNoEOF() {
		s.skipSpaces()
	}
}

func (s *mdSubject) skipLineEndStrictNoEOF() bool {
	seen := false
	if s.peek() == '\r' {
		s.pos++
		seen = true
	}
	if s.peek() == '\n' {
		s.pos++
		seen = true
	}
	return seen
}
