func (s *mdSubject) peek() byte {
	if s.pos < len(s.input) {
		return s.input[s.pos]
	}
	return 0
}

func (s *mdSubject) peekAt(i int) byte {
	if i >= 0 && i < len(s.input) {
		return s.input[i]
	}
	return 0
}

func (s *mdSubject) eof() bool { return s.pos >= len(s.input) }

func makeText(t string) *mdNode {
