	n.literal = t
	n.open = false
	return n
}

func (p *mdParser) processInlines() {
	var walk func(n *mdNode)
	walk = func(n *mdNode) {
		if containsInlines(n.kind) {
			p.parseInlines(n)
			return
		}
		for c := n.firstChild; c != nil; {
			next := c.next
			walk(c)
			c = next
		}
	}
	walk(p.root)
}

func (p *mdParser) parseInlines(parent *mdNode) {
	content := parent.content
	parent.content = nil
	// rtrim
	end := len(content)
	for end > 0 {
		c := content[end-1]
