			end--
		} else {
			break
		}
	}
	content = content[:end]
	if parent.kind == mdHeading || parent.kind == mdTableCell {
		// leading whitespace trimmed too
		st := 0
		for st < len(content) && (content[st] == ' ' || content[st] == '\t') {
			st++
		}
		content = content[st:]
