func isSpecialChar(c byte) bool {
	switch c {
	case '\n', '\r', '_', '*', '"', '`', '\\', '&', '<', '[', ']', '!', '~', '|', ':', 'w', '\'':
		return true
	}
	return false
}

func (s *mdSubject) findSpecialChar() int {
	n := s.pos + 1
	for n < len(s.input) {
		if isSpecialChar(s.input[n]) {
			return n
		}
		n++
	}
	return len(s.input)
}

func (s *mdSubject) parseInline(parent *mdNode) bool {
	c := s.peek()
	if s.eof() {
		return false
	}
	var newInl *mdNode
	switch c {
	case '\r', '\n':
		newInl = s.handleNewline()
	case '`':
		newInl = s.handleBackticks()
	case '\\':
		newInl = s.handleBackslash()
	case '&':
		newInl = s.handleEntity()
	case '<':
		newInl = s.handlePointyBrace()
	case ':':
		newInl = s.handleColon()
	case '*', '_', '\'', '"':
		newInl = s.handleDelim(c)
	case '~':
		newInl = s.handleDelim(c)
	case '|':
		newInl = s.handleDelim(c)
	case '[':
		s.pos++
		if !s.withinBrackets && s.peek() == '[' {
			if wl := s.handleWikilink(); wl != nil {
				newInl = wl
				break
			}
		}
		newInl = makeText("[")
		s.pushBracket(false, newInl)
		s.withinBrackets = true
	case ']':
		s.withinBrackets = false
		newInl = s.handleCloseBracket()
	case '!':
		s.pos++
		if s.peek() == '[' {
			s.pos++
			newInl = makeText("![")
			s.pushBracket(true, newInl)
			s.withinBrackets = true
		} else {
			newInl = makeText("!")
		}
	default:
		endpos := s.findSpecialChar()
		contents := s.input[s.pos:endpos]
		s.pos = endpos
		if isLineEndChar(s.peek()) {
			contents = rtrimBytes(contents)
		}
		newInl = makeText(string(contents))
	}
	if newInl != nil {
		parent.appendChild(newInl)
	}
	return true
}

func rtrimBytes(b []byte) []byte {
	e := len(b)
	for e > 0 {
		c := b[e-1]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f' {
			e--
		} else {
			break
		}
	}
	return b[:e]
}

func (s *mdSubject) skipSpaces() {
	for s.peek() == ' ' || s.peek() == '\t' {
		s.pos++
	}
}

func (s *mdSubject) skipLineEnd() bool {
	seen := false
	if s.peek() == '\r' {
		s.pos++
		seen = true
	}
	if s.peek() == '\n' {
		s.pos++
		seen = true
	}
	return seen || s.eof()
}

func (s *mdSubject) handleNewline() *mdNode {
	nlpos := s.pos
	if s.peek() == '\r' {
		s.pos++
	}
	if s.peek() == '\n' {
		s.pos++
	}
	s.skipSpaces()
	if nlpos > 1 && s.peekAt(nlpos-1) == ' ' && s.peekAt(nlpos-2) == ' ' {
		n := newNode(mdLineBreak)
		n.open = false
		return n
	}
	n := newNode(mdSoftBreak)
	n.open = false
	return n
}

func (s *mdSubject) scanToClosingBackticks(openLen int) int {
	if openLen > 80 {
		return 0
	}
	if s.scannedForBackticks && s.backticks[openLen] <= s.pos {
		return 0
	}
	for {
		for !s.eof() && s.peek() != '`' {
			s.pos++
		}
		if s.eof() {
			break
		}
		numticks := 0
		for s.peek() == '`' {
			s.pos++
			numticks++
		}
		if numticks <= 80 {
			s.backticks[numticks] = s.pos - numticks
		}
		if numticks == openLen {
			return s.pos
		}
	}
	s.scannedForBackticks = true
	return 0
}

func (s *mdSubject) handleBackticks() *mdNode {
	start := s.pos
	for s.peek() == '`' {
		s.pos++
	}
	openticks := s.input[start:s.pos]
	startpos := s.pos
	endpos := s.scanToClosingBackticks(len(openticks))
	if endpos == 0 {
		s.pos = startpos
		return makeText(string(openticks))
	}
	buf := s.input[startpos : endpos-len(openticks)]
	n := newNode(mdCode)
	n.open = false
	n.literal = normalizeCode(buf)
	return n
}

func normalizeCode(b []byte) string {
	out := make([]byte, 0, len(b))
	containsNonspace := false
	for r := 0; r < len(b); r++ {
		switch b[r] {
		case '\r':
			if r+1 >= len(b) || b[r+1] != '\n' {
				out = append(out, ' ')
			}
		case '\n':
			out = append(out, ' ')
		default:
			out = append(out, b[r])
		}
		if b[r] != ' ' {
			containsNonspace = true
		}
	}
	if containsNonspace && len(out) >= 2 && out[0] == ' ' && out[len(out)-1] == ' ' {
		out = out[1 : len(out)-1]
	}
	return string(out)
}

func isASCIIPunct(c byte) bool {
	return (c >= 33 && c <= 47) || (c >= 58 && c <= 64) || (c >= 91 && c <= 96) || (c >= 123 && c <= 126)
}

func (s *mdSubject) handleBackslash() *mdNode {
	s.pos++
	next := s.peek()
	if isASCIIPunct(next) {
		s.pos++
		return makeText(string([]byte{next}))
	} else if !s.eof() && (next == '\n' || next == '\r') {
		s.skipLineEnd()
		n := newNode(mdLineBreak)
		n.open = false
		return n
	}
	return makeText("\\")
}

// unescapeEntityAt tries to decode an entity at src (after '&'); returns decoded and length consumed.
func unescapeEntityAt(src []byte) (string, int) {
	size := len(src)
	if size >= 3 && src[0] == '#' {
		codepoint := 0
		numDigits := 0
		maxDigits := 7
		i := 0
		if isASCIIDigit(src[1]) {
			for i = 1; i < size && isASCIIDigit(src[i]); i++ {
				codepoint = codepoint*10 + int(src[i]-'0')
				if codepoint >= 0x110000 {
					codepoint = 0x110000
				}
			}
			numDigits = i - 1
			maxDigits = 7
		} else if src[1] == 'x' || src[1] == 'X' {
			for i = 2; i < size && isHexDigit(src[i]); i++ {
				codepoint = codepoint*16 + hexVal(src[i])
				if codepoint >= 0x110000 {
					codepoint = 0x110000
				}
			}
			numDigits = i - 2
			maxDigits = 6
		}
		if numDigits >= 1 && numDigits <= maxDigits && i < size && src[i] == ';' {
			if codepoint == 0 || (codepoint >= 0xD800 && codepoint < 0xE000) || codepoint >= 0x110000 {
				codepoint = 0xFFFD
			}
			return string(rune(codepoint)), i + 1
		}
		return "", 0
	}
	if size > 32 {
		size = 32
	}
	for i := 2; i < size; i++ {
		if src[i] == ' ' {
			break
		}
		if src[i] == ';' {
			if v, ok := htmlEntities[string(src[:i])]; ok {
				return v, i + 1
			}
			break
		}
	}
	return "", 0
}

func isHexDigit(c byte) bool {
	return isASCIIDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	default:
		return int(c-'A') + 10
	}
}

func (s *mdSubject) handleEntity() *mdNode {
	s.pos++
	dec, n := unescapeEntityAt(s.input[s.pos:])
	if n == 0 {
		return makeText("&")
	}
	s.pos += n
	return makeText(dec)
}

// unescapeHTMLEntities decodes all entities in a string.
func unescapeHTMLEntities(str string) string {
	if !strings.Contains(str, "&") {
		return str
	}
	b := []byte(str)
	var out []byte
	for i := 0; i < len(b); i++ {
		if b[i] == '&' {
			dec, n := unescapeEntityAt(b[i+1:])
			if n > 0 {
				out = append(out, dec...)
				i += n
				continue
			}
		}
		out = append(out, b[i])
	}
	return string(out)
}

func unescapeBackslash(str string) string {
	if !strings.Contains(str, "\\") {
		return str
	}
	b := []byte(str)
	var out []byte
	for i := 0; i < len(b); i++ {
		if b[i] == '\\' && i+1 < len(b) && isASCIIPunct(b[i+1]) {
			out = append(out, b[i+1])
			i++
			continue
		}
		out = append(out, b[i])
	}
	return string(out)
}

var reAutolinkURI = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9.+-]{1,31}:[^\x00-\x20<>]*>`)
var reAutolinkEmail = regexp.MustCompile(`^[a-zA-Z0-9.!#$%&'*+/=?^_` + "`" + `{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*>`)

var reInlineOpenTag = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9-]*(?:[ \t\n\r\f\v]+[a-zA-Z_:][a-zA-Z0-9_.:-]*(?:[ \t\n\r\f\v]*=[ \t\n\r\f\v]*(?:[^ \t\n\r\f\v"'=<>` + "`" + `\x00]+|'[^']*'|"[^"]*"))?)*[ \t\n\r\f\v]*/?>`)
var reInlineCloseTag = regexp.MustCompile(`^/[A-Za-z][A-Za-z0-9-]*[ \t\n\r\f\v]*>`)
var reInlineDecl = regexp.MustCompile(`^![A-Za-z][^>]*>`)

func scanInlineHTML(b []byte) int {
	// b starts after '<'
	if m := reInlineOpenTag.FindIndex(b); m != nil {
		return m[1]
	}
	if m := reInlineCloseTag.FindIndex(b); m != nil {
		return m[1]
	}
	if len(b) >= 3 && b[0] == '!' && b[1] == '-' && b[2] == '-' {
		rest := b[3:]
		if len(rest) > 0 && rest[0] == '>' {
			return 4
		}
		if len(rest) > 1 && rest[0] == '-' && rest[1] == '>' {
			return 5
		}
		idx := strings.Index(string(rest), "-->")
		if idx >= 0 {
			return 3 + idx + 3
		}
		return 0
	}
	if len(b) >= 1 && b[0] == '?' {
		idx := strings.Index(string(b[1:]), "?>")
		if idx >= 0 {
			return 1 + idx + 2
		}
		return 0
	}
	if strings.HasPrefix(string(b), "![CDATA[") {
		idx := strings.Index(string(b[8:]), "]]>")
		if idx >= 0 {
			return 8 + idx + 3
		}
		return 0
	}
	if m := reInlineDecl.FindIndex(b); m != nil {
		return m[1]
	}
	return 0
}

func (s *mdSubject) handlePointyBrace() *mdNode {
	s.pos++
	rest := s.input[s.pos:]
	if m := reAutolinkURI.FindIndex(rest); m != nil {
		contents := string(rest[:m[1]-1])
		s.pos += m[1]
		return makeAutolink(contents, false)
	}
	if m := reAutolinkEmail.FindIndex(rest); m != nil {
		contents := string(rest[:m[1]-1])
		s.pos += m[1]
		return makeAutolink(contents, true)
	}
	if n := scanInlineHTML(rest); n > 0 {
		node := newNode(mdHTMLInline)
		node.open = false
		node.literal = "<" + string(rest[:n])
		s.pos += n
		return node
	}
	return makeText("<")
}

func makeAutolink(contents string, email bool) *mdNode {
	n := newNode(mdLink)
	n.open = false
	u := cleanAutolink(contents)
	if email {
		u = "mailto:" + u
	}
	n.url = u
	n.appendChild(makeText(unescapeHTMLEntities(contents)))
	return n
}

func cleanAutolink(s string) string {
	s = strings.TrimSpace(s)
	return unescapeHTMLEntities(s)
}

func (s *mdSubject) handleColon() *mdNode {
	// emoji shortcodes
	rest := s.input[s.pos+1:]
	i := 0
	for i < len(rest) {
		c := rest[i]
		if isASCIIAlnum(c) || c == '_' || c == '+' || c == '-' {
			i++
			continue
		}
		break
	}
	if i > 0 && i < len(rest) && rest[i] == ':' {
		name := string(rest[:i])
		if e, ok := emojiShortcodes[name]; ok {
			s.pos += i + 2
			n := newNode(mdShortCode)
			n.open = false
			n.literal = e
			return n
		}
	}
	s.pos++
	return makeText(":")
}

func isUnicodeSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v' || unicode.Is(unicode.Zs, r)
}

func isUnicodePunct(r rune) bool {
	if r < 128 {
		return isASCIIPunct(byte(r))
	}
	return unicode.IsPunct(r) || unicode.IsSymbol(r)
}

func (s *mdSubject) scanDelims(c byte) (int, bool, bool) {
	numdelims := 0
	var before rune = '\n'
	if s.pos > 0 {
		bp := s.pos - 1
		for bp > 0 && s.input[bp]>>6 == 2 {
			bp--
		}
		r, size := utf8.DecodeRune(s.input[bp:s.pos])
		if r == utf8.RuneError && size <= 1 {
			before = '\n'
		} else {
			before = r
		}
	}
	if c == '\'' || c == '"' {
		numdelims++
		s.pos++
	} else {
		for s.peek() == c && !s.eof() {
			numdelims++
			s.pos++
		}
	}
	var after rune = '\n'
	if s.pos < len(s.input) {
		r, size := utf8.DecodeRune(s.input[s.pos:])
		if !(r == utf8.RuneError && size <= 1) {
			after = r
		}
	}
	leftFlanking := numdelims > 0 && !isUnicodeSpace(after) && (!isUnicodePunct(after) || isUnicodeSpace(before) || isUnicodePunct(before))
	rightFlanking := numdelims > 0 && !isUnicodeSpace(before) && (!isUnicodePunct(before) || isUnicodeSpace(after) || isUnicodePunct(after))
	var canOpen, canClose bool
	if c == '_' {
		canOpen = leftFlanking && (!rightFlanking || isUnicodePunct(before))
		canClose = rightFlanking && (!leftFlanking || isUnicodePunct(after))
	} else if c == '\'' || c == '"' {
		canOpen = leftFlanking && !rightFlanking && before != ']' && before != ')'
		canClose = rightFlanking
	} else {
		canOpen = leftFlanking
		canClose = rightFlanking
	}
	return numdelims, canOpen, canClose
}

func (s *mdSubject) handleDelim(c byte) *mdNode {
	start := s.pos
	numdelims, canOpen, canClose := s.scanDelims(c)
	contents := string(s.input[start:s.pos])
	inl := makeText(contents)
	if c == '~' && numdelims > 2 {
		return inl
	}
	if c == '|' && numdelims < 2 {
		// a single pipe is not a spoiler delimiter on its own
	}
	if (canOpen || canClose) && !(c == '\'' || c == '"') {
		s.pushDelimiter(c, canOpen, canClose, inl, start, numdelims)
	}
	return inl
}

func (s *mdSubject) pushDelimiter(c byte, canOpen, canClose bool, inl *mdNode, pos, length int) {
	d := &mdDelim{delimChar: c, canOpen: canOpen, canClose: canClose, inl: inl, position: pos, length: length, prev: s.lastDelim}
	if s.lastDelim != nil {
		s.lastDelim.next = d
	}
	s.lastDelim = d
}

func (s *mdSubject) removeDelimiter(d *mdDelim) {
	if d == nil {
		return
	}
	if d.next != nil {
		d.next.prev = d.prev
	} else {
		s.lastDelim = d.prev
	}
	if d.prev != nil {
		d.prev.next = d.next
	}
}

func (s *mdSubject) pushBracket(image bool, inl *mdNode) {
	if s.lastBracket != nil {
		s.lastBracket.bracketAfter = true
	}
	b := &mdBracket{prev: s.lastBracket, inlText: inl, position: s.pos, image: image, active: true, prevDelim: s.lastDelim}
	s.lastBracket = b
}

func (s *mdSubject) popBracket() {
	if s.lastBracket != nil {
		s.lastBracket = s.lastBracket.prev
	}
}

func delimIndex(d *mdDelim) int {
	switch d.delimChar {
	case '|':
		return 0
	case '~':
		return 1
	case '^':
		return 2
	case '"':
		return 3
	case '\'':
		return 4
	case '_':
		return 5
	case '*':
		ix := 6
		if d.canOpen {
			ix += 3
		}
		return ix + d.length%3
	}
	return 0
}

func (s *mdSubject) processEmphasis(stackBottom *mdDelim) {
	bottomPos := -1
	if stackBottom != nil {
		bottomPos = stackBottom.position
	}
	var openersBottom [15]int
	for i := range openersBottom {
		openersBottom[i] = bottomPos
	}
	// find first closer above stackBottom
	candidate := s.lastDelim
	var closer *mdDelim
	for candidate != nil && candidate.position > bottomPos && candidate != stackBottom {
		closer = candidate
		candidate = candidate.prev
	}
	for closer != nil {
		c := closer
		if c.canClose {
			ix := delimIndex(c)
			opener := c.prev
			openerFound := false
			mod3 := false
			for opener != nil && opener.position > openersBottom[ix] && opener != stackBottom {
				o := opener
				if o.canOpen && o.delimChar == c.delimChar {
					oddMatch := (c.canOpen || o.canClose) && ((o.length+c.length)%3 == 0) && !(o.length%3 == 0 && c.length%3 == 0)
					if !oddMatch {
						openerFound = true
						break
					}
					mod3 = true
				}
				opener = o.prev
			}
			oldC := c
			if openerFound {
				var ok bool
				closer, ok = s.insertEmph(opener, c)
				if !ok {
					closer = nil
				}
			} else {
				closer = c.next
			}
			if !openerFound {
				if !mod3 {
					openersBottom[ix] = oldC.position
				}
				if !oldC.canOpen {
					s.removeDelimiter(oldC)
				}
			}
		} else {
			closer = c.next
		}
	}
	// remove delimiters above stack bottom
	for s.lastDelim != nil && s.lastDelim != stackBottom {
		s.removeDelimiter(s.lastDelim)
	}
}

func (s *mdSubject) insertEmph(opener, closer *mdDelim) (*mdDelim, bool) {
	openerChar := opener.delimChar
	openerNum := len(opener.inl.literal)
	closerNum := len(closer.inl.literal)
	useDelims := 1
	if closerNum >= 2 && openerNum >= 2 {
		useDelims = 2
	}
	openerNum -= useDelims
	closerNum -= useDelims
	if openerChar == '~' && (openerNum != closerNum || openerNum > 0) {
		return nil, false
	}
	opener.inl.literal = opener.inl.literal[:openerNum]
	closer.inl.literal = closer.inl.literal[:closerNum]
	// remove delimiters between opener and closer
	d := closer.prev
	for d != nil && d != opener {
		prev := d.prev
		s.removeDelimiter(d)
		d = prev
	}
	var kind mdKind
	escapedPipe := false
	switch {
	case openerChar == '~':
		kind = mdStrikethrough
	case openerChar == '|':
		if useDelims == 2 {
			kind = mdSpoiler
		} else {
			escapedPipe = true
			kind = mdSpoiler
		}
	case openerChar == '_' && useDelims == 2:
		kind = mdUnderline
	case useDelims == 1:
		kind = mdEmph
	default:
		kind = mdStrong
	}
	emph := newNode(kind)
	emph.open = false
	if escapedPipe {
		emph.literal = "|"
	}
	tmp := opener.inl.next
	for tmp != nil && tmp != closer.inl {
		next := tmp.next
		emph.appendChild(tmp)
		tmp = next
	}
	opener.inl.insertAfter(emph)
	if openerNum == 0 {
		opener.inl.detach()
		s.removeDelimiter(opener)
	}
	if closerNum == 0 {
		closer.inl.detach()
		next := closer.next
		s.removeDelimiter(closer)
		return next, true
	}
	return closer, true
}

// ----- links -----

func scanSpacechars(b []byte, pos int) int {
	i := pos
	for i < len(b) && (b[i] == ' ' || b[i] == '\t' || b[i] == '\n' || b[i] == '\r' || b[i] == '\v' || b[i] == '\f') {
		i++
	}
	return i - pos
}

func isCntrl(c byte) bool { return c < 0x20 || c == 0x7f }

func manualScanLinkURL2(b []byte, offset int) (int, string) {
	i := offset
	nbp := 0
	for i < len(b) {
		if b[i] == '\\' && i+1 < len(b) && isASCIIPunct(b[i+1]) {
			i += 2
		} else if b[i] == '(' {
			nbp++
			i++
			if nbp > 32 {
				return -1, ""
			}
		} else if b[i] == ')' {
			if nbp == 0 {
				break
			}
			nbp--
			i++
		} else if b[i] == ' ' || b[i] == '\t' || b[i] == '\n' || b[i] == '\r' || b[i] == '\v' || b[i] == '\f' || isCntrl(b[i]) {
			if i == offset {
				return -1, ""
			}
			break
		} else {
			i++
		}
	}
	if i >= len(b) || nbp != 0 {
		return -1, ""
	}
	return i - offset, string(b[offset:i])
}

func manualScanLinkURL(b []byte, offset int) (int, string) {
	i := offset
	if i < len(b) && b[i] == '<' {
		i++
		for i < len(b) {
			if b[i] == '>' {
				i++
				break
			} else if b[i] == '\\' {
				i += 2
			} else if b[i] == '\n' || b[i] == '<' {
				return -1, ""
			} else {
				i++
			}
		}
	} else {
		return manualScanLinkURL2(b, offset)
	}
	if i >= len(b) {
		return -1, ""
	}
	return i - offset, string(b[offset+1 : i-1])
}

func scanLinkTitle(b []byte, pos int) int {
	if pos >= len(b) {
		return 0
	}
	open := b[pos]
	var close byte
	switch open {
	case '"':
		close = '"'
	case '\'':
		close = '\''
	case '(':
		close = ')'
	default:
		return 0
	}
	i := pos + 1
	for i < len(b) {
		c := b[i]
		if c == '\\' && i+1 < len(b) {
			i += 2
			continue
		}
		if c == close {
			return i + 1 - pos
		}
		if open == '(' && c == '(' {
			return 0
		}
		i++
	}
	return 0
}

func cleanURL(u string) string {
	u = strings.Trim(u, " \t\n\r\v\f")
	if u == "" {
		return ""
	}
	return unescapeHTMLEntities(unescapeBackslash(u))
}

func cleanTitle(t string) string {
	if t == "" {
		return ""
	}
	first := t[0]
	last := t[len(t)-1]
	if (first == '\'' && last == '\'') || (first == '(' && last == ')') || (first == '"' && last == '"') {
		t = t[1 : len(t)-1]
	}
	return unescapeHTMLEntities(unescapeBackslash(t))
}

func (s *mdSubject) linkLabel() (string, bool) {
	startpos := s.pos
	if s.peek() != '[' {
		return "", false
	}
	s.pos++
	length := 0
	for !s.eof() {
		c := s.peek()
		if c == '[' || c == ']' {
			break
		}
		if c == '\\' {
			s.pos++
			length++
			if isASCIIPunct(s.peek()) {
				s.pos++
				length++
			}
		} else {
			s.pos++
			length++
		}
		if length > 1000 {
			s.pos = startpos
			return "", false
		}
	}
	if s.peek() == ']' {
		raw := strings.Trim(string(s.input[startpos+1:s.pos]), " \t\n\r\v\f")
		s.pos++
		return raw, true
	}
	s.pos = startpos
	return "", false
}

func normalizeLabel(s string) string {
	s = strings.Trim(s, " \t\n\r\v\f")
	s = caseFold(s)
	// collapse whitespace
	var b strings.Builder
	inSpace := false
	for _, r := range s {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f' {
			if !inSpace {
				b.WriteByte(' ')
			}
			inSpace = true
		} else {
			b.WriteRune(r)
			inSpace = false
		}
	}
	return b.String()
}

func caseFold(s string) string {
	s = strings.ToLower(strings.ToUpper(s))
	return strings.ReplaceAll(s, "ß", "ss")
}

func (s *mdSubject) handleCloseBracket() *mdNode {
	s.pos++
	initialPos := s.pos
	opener := s.lastBracket
	if opener == nil {
		return makeText("]")
	}
	if !opener.active {
		s.popBracket()
		return makeText("]")
	}
	isImage := opener.image
	afterLinkTextPos := s.pos

	// inline link
	if s.peek() == '(' {
		sps := scanSpacechars(s.input, s.pos+1)
		n, urlChunk := manualScanLinkURL(s.input, s.pos+1+sps)
		if n > -1 {
			endurl := s.pos + 1 + sps + n
			starttitle := endurl + scanSpacechars(s.input, endurl)
			endtitle := starttitle
			if starttitle != endurl {
				endtitle = starttitle + scanLinkTitle(s.input, starttitle)
			}
			endall := endtitle + scanSpacechars(s.input, endtitle)
			if s.peekAt(endall) == ')' {
				s.pos = endall + 1
				u := cleanURL(urlChunk)
				t := cleanTitle(string(s.input[starttitle:endtitle]))
				s.closeBracketMatch(opener, isImage, u, t)
				return nil
			}
			s.pos = afterLinkTextPos
		}
	}

	rawLabel, found := s.linkLabel()
	if !found {
		s.pos = initialPos
	}
	if (!found || rawLabel == "") && !opener.bracketAfter {
		rawLabel = string(s.input[opener.position : initialPos-1])
		found = true
	}
	var ref *mdRef
	if found {
		ref = s.p.refmap[normalizeLabel(rawLabel)]
	}
	if ref != nil {
		s.closeBracketMatch(opener, isImage, ref.url, ref.title)
		return nil
	}

	// footnote reference
	if n := opener.inlText.next; n != nil && n.kind == mdText && strings.HasPrefix(n.literal, "^") {
		text := ""
		for sib := opener.inlText.next; sib != nil; sib = sib.next {
			if sib.kind == mdText {
				text += sib.literal
			}
		}
		if len(text) > 1 {
			fr := newNode(mdFootnoteReference)
			fr.open = false
			fr.fnName = text[1:]
			opener.inlText.insertBefore(fr)
			for sib := opener.inlText; sib != nil; {
				next := sib.next
				if sib.kind == mdText || sib.kind == mdHTMLInline {
					sib.detach()
				}
				sib = next
			}
			s.popBracket()
			return nil
		}
	}

	if found && s.p.opts.brokenLinkCallback != nil {
		if u, t, ok := s.p.opts.brokenLinkCallback(rawLabel); ok {
			s.closeBracketMatch(opener, isImage, u, t)
			return nil
		}
	}

	s.popBracket()
	s.pos = initialPos
	return makeText("]")
}

func (s *mdSubject) closeBracketMatch(opener *mdBracket, isImage bool, u, t string) {
	kind := mdLink
	if isImage {
		kind = mdImage
	}
	inl := newNode(kind)
	inl.open = false
	inl.url = u
	inl.title = t
	opener.inlText.insertBefore(inl)
	tmp := opener.inlText.next
	for tmp != nil {
		next := tmp.next
		inl.appendChild(tmp)
		tmp = next
	}
	opener.inlText.detach()
	s.processEmphasis(opener.prevDelim)
	s.popBracket()
	if !isImage {
		o := s.lastBracket
		for o != nil {
			if !o.image {
				if !o.active {
					break
				}
				o.active = false
			}
			o = o.prev
		}
	}
}

// ----- wikilinks -----

func (s *mdSubject) wikilinkComponent() bool {
	startpos := s.pos
	if s.peek() != '[' && s.peek() != '|' {
		return false
	}
	s.pos++
	length := 0
	for !s.eof() {
		c := s.peek()
		if c == '[' || c == ']' || c == '|' {
			break
		}
		if c == '\\' {
			s.pos++
			length++
			if isASCIIPunct(s.peek()) {
				s.pos++
				length++
			}
		} else {
			s.pos++
			length++
		}
		if length > 1000 {
			s.pos = startpos
			return false
		}
	}
	return true
}

func (s *mdSubject) handleWikilink() *mdNode {
	// s.pos at second '['
	leftStart := s.pos
	if !s.wikilinkComponent() {
		s.pos = leftStart
		return nil
	}
	left := strings.Trim(string(s.input[leftStart+1:s.pos]), " \t\n\r\v\f")
	var urlPart, label string
	hasLabel := false
	if s.peek() == ']' && s.peekAt(s.pos+1) == ']' {
		s.pos += 2
		urlPart = left
	} else if s.peek() != '|' {
		s.pos = leftStart
		return nil
	} else {
		rightStart := s.pos
		if !s.wikilinkComponent() {
			s.pos = leftStart
			return nil
		}
		right := strings.Trim(string(s.input[rightStart+1:s.pos]), " \t\n\r\v\f")
		if s.peek() == ']' && s.peekAt(s.pos+1) == ']' {
			s.pos += 2
			// title before pipe
			urlPart = right
			label = left
			hasLabel = true
		} else {
			s.pos = leftStart
			return nil
		}
	}
	u := cleanURL(urlPart)
	if !hasLabel {
		label = urlPart
	}
	label = unescapeHTMLEntities(label)
	n := newNode(mdWikiLink)
	n.open = false
	n.url = u
	n.appendChild(makeText(unescapeBackslash(label)))
	return n
}

// ----- reference definitions -----

func (p *mdParser) parseReferenceInline(input []byte) int {
	s := &mdSubject{p: p, input: input}
	lab, ok := s.linkLabel()
	if !ok || lab == "" {
		return 0
	}
	if s.peek() != ':' {
		return 0
	}
	s.pos++
	s.spnl()
	n, urlChunk := manualScanLinkURL(s.input, s.pos)
	if n <= -1 {
		return 0
	}
	if n == 0 && !(s.pos < len(s.input) && s.input[s.pos] == '<') {
		return 0
	}
	s.pos += n
	beforeTitle := s.pos
	s.spnl()
	matchlen := 0
	if s.pos != beforeTitle {
		matchlen = scanLinkTitle(s.input, s.pos)
	}
	title := ""
	if matchlen > 0 {
		title = string(s.input[s.pos : s.pos+matchlen])
		s.pos += matchlen
	} else {
		s.pos = beforeTitle
	}
	s.skipSpaces()
	if !s.skipLineEndStrict() {
		if matchlen > 0 {
			s.pos = beforeTitle
			s.skipSpaces()
			if !s.skipLineEndStrict() {
				return 0
			}
			title = ""
		} else {
			return 0
		}
	}
	norm := normalizeLabel(lab)
	if norm == "" {
		return 0
	}
	if strings.HasPrefix(lab, "^") {
		// footnote-like labels are not reference definitions
	}
	if _, exists := p.refmap[norm]; !exists {
		p.refmap[norm] = &mdRef{url: cleanURL(urlChunk), title: cleanTitle(title)}
	}
	return s.pos
}

func (s *mdSubject) skipLineEndStrict() bool {
	if s.eof() {
		return true
	}
	seen := false
	if s.peek() == '\r' {
		s.pos++
		seen = true
	}
	if s.peek() == '\n' {
		s.pos++
		seen = true
	}
	return seen
}

func (s *mdSubject) spnl() {
	s.skipSpaces()
	if s.skipLineEndStrictNoEOF() {
		s.skipSpaces()
	}
}

func (s *mdSubject) skipLineEndStrictNoEOF() bool {
	seen := false
	if s.peek() == '\r' {
		s.pos++
		seen = true
	}
	if s.peek() == '\n' {
		s.pos++
		seen = true
	}
	return seen
}
