package main

import (
	"strings"
	"unicode/utf8"
)

func (p *mdParser) postprocess() {
	p.postprocessTextNodes(p.root)
	p.processFootnotes()
}

func (p *mdParser) postprocessTextNodes(node *mdNode) {
	for n := node.firstChild; n != nil; {
		if n.kind == mdText {
			// merge adjacent text nodes
			for n.next != nil && n.next.kind == mdText {
				n.literal += n.next.literal
				n.next.detach()
			}
			p.processTasklist(n)
			next := p.processAutolinks(n)
			n = next
			continue
		}
		if n.kind == mdLink || n.kind == mdImage || n.kind == mdWikiLink {
			n = n.next
			continue
		}
		p.postprocessTextNodes(n)
		n = n.next
	}
}

func (p *mdParser) processTasklist(n *mdNode) {
	text := n.literal
	// pattern: optional whitespace, '[', char, ']', then space/tab or end
	i := 0
	for i < len(text) && (text[i] == ' ' || text[i] == '\t' || text[i] == '\n') {
		i++
	}
	if i+2 >= len(text) || text[i] != '[' {
		return
	}
	r, size := utf8.DecodeRuneInString(text[i+1:])
	if i+1+size >= len(text)+1 {
		return
	}
	if i+1+size >= len(text) || text[i+1+size] != ']' {
		return
	}
	if !(r == ' ' || r == 'x' || r == 'X') {
		return
	}
	end := i + 1 + size + 1
	if end < len(text) {
		if !(text[end] == ' ' || text[end] == '\t') {
			return
		}
		end++
	} else {
		// must be followed by end of line: check next sibling
		if n.next != nil && !(n.next.kind == mdSoftBreak || n.next.kind == mdLineBreak) {
			return
		}
	}
	parent := n.parent
