func (r *mdRenderer) anchorize(header string) string {
	id := strings.ToLower(header)
	var b strings.Builder
	for _, ch := range id {
		if ch == ' ' || ch == '-' || isAnchorKeep(ch) {
			b.WriteRune(ch)
		}
	}
	id = strings.ReplaceAll(b.String(), " ", "-")
	uniq := 0
	for {
		anchor := id
		if uniq > 0 {
			anchor = fmt.Sprintf("%s-%d", id, uniq)
		}
