func isTightParagraph(n *mdNode) bool {
	if n.parent != nil {
		if n.parent.kind == mdDescriptionTerm {
			return true
		}
		gp := n.parent.parent
		if gp != nil {
			if gp.kind == mdList {
				return gp.list.tight
			}
			if gp.kind == mdDescriptionItem {
				return gp.dTight
			}
		}
	}
	return false
}

func (r *mdRenderer) render(n *mdNode) {
	switch n.kind {
	case mdDocument:
		r.renderChildren(n)
		if r.footnoteIx > 0 {
			r.out.WriteString("</ol>\n</section>\n")
		}
	case mdBlockQuote, mdMultilineBlockQuote:
		r.cr()
		r.out.WriteString("<blockquote>\n")
		r.renderChildren(n)
		r.cr()
		r.out.WriteString("</blockquote>\n")
	case mdAlert:
		r.cr()
		r.out.WriteString("<div class=\"markdown-alert markdown-alert-" + n.alertType + "\">\n")
		title := n.alertTitle
		if title == "" {
			title = alertTypes[n.alertType]
		}
		r.out.WriteString("<p class=\"markdown-alert-title\">" + escapeHTML(title) + "</p>\n")
		r.renderChildren(n)
		r.cr()
		r.out.WriteString("</div>\n")
	case mdList:
		r.cr()
		if !n.list.ordered {
			r.out.WriteString("<ul>\n")
		} else if n.list.start == 1 {
			r.out.WriteString("<ol>\n")
		} else {
			fmt.Fprintf(&r.out, "<ol start=\"%d\">\n", n.list.start)
		}
		r.renderChildren(n)
		if !n.list.ordered {
			r.out.WriteString("</ul>\n")
		} else {
			r.out.WriteString("</ol>\n")
		}
	case mdItem:
		r.cr()
		r.out.WriteString("<li>")
		if n.isTask {
			r.out.WriteString("<input type=\"checkbox\"")
			if n.checked {
				r.out.WriteString(" checked=\"\"")
			}
			r.out.WriteString(" disabled=\"\" /> ")
		}
		r.renderChildren(n)
		r.out.WriteString("</li>\n")
	case mdDescriptionList:
		r.cr()
		r.out.WriteString("<dl>\n")
		r.renderChildren(n)
		r.out.WriteString("</dl>\n")
	case mdDescriptionItem:
		r.renderChildren(n)
	case mdDescriptionTerm:
		r.out.WriteString("<dt>")
		r.renderChildren(n)
		r.out.WriteString("</dt>\n")
	case mdDescriptionDetails:
		r.out.WriteString("<dd>")
		r.renderChildren(n)
		r.out.WriteString("</dd>\n")
	case mdHeading:
		r.cr()
		fmt.Fprintf(&r.out, "<h%d>", n.level)
		var tb strings.Builder
		collectText(n, &tb)
		id := r.anchorize(tb.String())
		r.out.WriteString("<a href=\"#" + id + "\" aria-hidden=\"true\" class=\"anchor\" id=\"" + id + "\"></a>")
		r.renderChildren(n)
		fmt.Fprintf(&r.out, "</h%d>\n", n.level)
	case mdCodeBlock:
		r.cr()
		info := n.info
		if info == "" {
			r.out.WriteString("<pre><code>")
		} else {
			lang := info
			if i := strings.IndexAny(info, " \t"); i >= 0 {
				lang = info[:i]
			}
			r.out.WriteString("<pre><code class=\"language-" + escapeHTML(lang) + "\">")
		}
		r.out.WriteString(escapeHTML(n.literal))
		r.out.WriteString("</code></pre>\n")
	case mdHTMLBlock:
		r.cr()
		r.out.WriteString(n.literal)
		r.cr()
	case mdThematicBreak:
		r.cr()
		r.out.WriteString("<hr />\n")
	case mdParagraph:
		tight := isTightParagraph(n)
		if !tight {
			r.cr()
			r.out.WriteString("<p>")
		}
		r.renderChildren(n)
		if !tight {
			if n.parent != nil && n.parent.kind == mdFootnoteDefinition && n.next == nil {
				r.out.WriteString(" ")
				r.putFootnoteBackref(n.parent)
			}
			r.out.WriteString("</p>\n")
		}
	case mdFootnoteDefinition:
		if r.footnoteIx == 0 {
			r.out.WriteString("<section class=\"footnotes\" data-footnotes>\n<ol>\n")
		}
		r.footnoteIx++
		r.out.WriteString("<li id=\"fn-" + escapeHref(n.fnName) + "\">")
		r.renderChildren(n)
		if r.putFootnoteBackref(n) {
			r.out.WriteString("\n")
		}
		r.out.WriteString("</li>\n")
	case mdTable:
		r.cr()
		r.out.WriteString("<table>\n")
		first := true
		inBody := false
		for row := n.firstChild; row != nil; row = row.next {
			if row.isHeader {
				r.cr()
				r.out.WriteString("<thead>\n")
			} else if first || !inBody {
				if !inBody {
					r.cr()
					r.out.WriteString("<tbody>\n")
					inBody = true
				}
			}
			first = false
			r.cr()
			r.out.WriteString("<tr>\n")
			i := 0
			for cell := row.firstChild; cell != nil; cell = cell.next {
				tag := "td"
				if row.isHeader {
					tag = "th"
				}
				r.cr()
				r.out.WriteString("<" + tag)
				if i < len(n.alignments) {
					switch n.alignments[i] {
					case 'l':
						r.out.WriteString(" align=\"left\"")
					case 'r':
						r.out.WriteString(" align=\"right\"")
					case 'c':
						r.out.WriteString(" align=\"center\"")
					}
				}
				r.out.WriteString(">")
				r.renderChildren(cell)
				r.out.WriteString("</" + tag + ">")
				i++
			}
			r.cr()
			r.out.WriteString("</tr>\n")
			if row.isHeader {
				r.cr()
				r.out.WriteString("</thead>\n")
			}
		}
		if inBody {
			r.cr()
			r.out.WriteString("</tbody>\n")
		}
		r.cr()
		r.out.WriteString("</table>\n")
	case mdText:
		r.out.WriteString(escapeHTML(n.literal))
	case mdSoftBreak:
		r.out.WriteString("\n")
	case mdLineBreak:
		r.out.WriteString("<br />\n")
	case mdCode:
		r.out.WriteString("<code>" + escapeHTML(n.literal) + "</code>")
	case mdHTMLInline:
		r.out.WriteString(n.literal)
	case mdEmph:
		r.out.WriteString("<em>")
		r.renderChildren(n)
		r.out.WriteString("</em>")
	case mdStrong:
		r.out.WriteString("<strong>")
		r.renderChildren(n)
		r.out.WriteString("</strong>")
	case mdStrikethrough:
		r.out.WriteString("<del>")
		r.renderChildren(n)
		r.out.WriteString("</del>")
	case mdUnderline:
		r.out.WriteString("<u>")
		r.renderChildren(n)
		r.out.WriteString("</u>")
	case mdSpoiler:
		if n.literal == "|" {
			r.out.WriteString("|")
			r.renderChildren(n)
			r.out.WriteString("|")
		} else {
			r.out.WriteString("<span class=\"spoiler\">")
			r.renderChildren(n)
			r.out.WriteString("</span>")
		}
	case mdLink:
		r.out.WriteString("<a href=\"" + escapeHref(n.url) + "\"")
		if n.title != "" {
			r.out.WriteString(" title=\"" + escapeHTML(n.title) + "\"")
		}
		r.out.WriteString(">")
		r.renderChildren(n)
		r.out.WriteString("</a>")
	case mdWikiLink:
		r.out.WriteString("<a href=\"" + escapeHref(n.url) + "\" data-wikilink=\"true\">")
		r.renderChildren(n)
		r.out.WriteString("</a>")
	case mdImage:
		r.out.WriteString("<figure><img src=\"" + escapeHref(n.url) + "\" alt=\"")
		var tb strings.Builder
		collectPlainText(n, &tb)
		r.out.WriteString(escapeHTML(tb.String()))
		r.out.WriteString("\"")
		if n.title != "" {
			r.out.WriteString(" title=\"" + escapeHTML(n.title) + "\"")
		}
		r.out.WriteString(" />")
		if n.title != "" {
			r.out.WriteString("<figcaption>" + escapeHTML(n.title) + "</figcaption>")
		}
		r.out.WriteString("</figure>")
	case mdFootnoteReference:
		refID := "fnref-" + n.fnName
		if n.fnRefIx > 1 {
			refID = fmt.Sprintf("%s-%d", refID, n.fnRefIx)
		}
		fmt.Fprintf(&r.out, "<sup class=\"footnote-ref\"><a href=\"#fn-%s\" id=\"%s\" data-footnote-ref>%d</a></sup>", escapeHref(n.fnName), escapeHref(refID), n.fnIx)
	case mdShortCode:
		r.out.WriteString(n.literal)
	default:
		r.renderChildren(n)
	}
}

func collectPlainText(n *mdNode, b *strings.Builder) {
	for c := n.firstChild; c != nil; c = c.next {
		switch c.kind {
		case mdText, mdCode, mdHTMLInline, mdShortCode:
			b.WriteString(c.literal)
		case mdLineBreak, mdSoftBreak:
			b.WriteByte(' ')
		default:
			collectPlainText(c, b)
		}
	}
}

func (r *mdRenderer) putFootnoteBackref(n *mdNode) bool {
	if r.writtenFootnoteIx >= r.footnoteIx {
		return false
	}
	r.writtenFootnoteIx = r.footnoteIx
	refSuffix := ""
	sup := ""
	for refNum := 1; refNum <= n.fnCount; refNum++ {
		if refNum > 1 {
			refSuffix = fmt.Sprintf("-%d", refNum)
			sup = fmt.Sprintf("<sup class=\"footnote-ref\">%d</sup>", refNum)
			r.out.WriteString(" ")
		}
		fmt.Fprintf(&r.out, "<a href=\"#fnref-%s%s\" class=\"footnote-backref\" data-footnote-backref data-footnote-backref-idx=\"%d%s\" aria-label=\"Back to reference %d%s\">↩%s</a>", escapeHref(n.fnName), refSuffix, r.footnoteIx, refSuffix, r.footnoteIx, refSuffix, sup)
	}
	return true
}

func (r *mdRenderer) renderChildren(n *mdNode) {
	for c := n.firstChild; c != nil; c = c.next {
		r.render(c)
	}
}

// markdownToHTML converts markdown text to HTML using comrak-like options.
func markdownToHTML(text string, broken func(label string)) string {
	opts := mdOptions{}
	if broken != nil {
		opts.brokenLinkCallback = func(label string) (string, string, bool) {
			broken(label)
			return "", "", false
		}
	}
	p := newMdParser(opts)
	root := p.parse(text)
	return renderMarkdownDoc(root)
}
