		if strings.HasPrefix(exp, "-") {
			exp = "-" + strings.TrimLeft(exp[1:], "0")
		}
		return mant + "e" + exp
	}
	return s
}

func toJSON(v Value) string {
	var b strings.Builder
	writeJSON(&b, v, false, "", 0)
	return b.String()
}

func toJSONPretty(v Value) string {
	var b strings.Builder
	writeJSON(&b, v, true, "  ", 0)
	return b.String()
}

func writeJSON(b *strings.Builder, v Value, pretty bool, ind string, level int) {
	switch x := v.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		if x {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case int64:
		b.WriteString(strconv.FormatInt(x, 10))
	case float64:
		b.WriteString(jsonFloat(x))
	case string:
		b.WriteString(jsonEscapeString(x))
	case []Value:
		if len(x) == 0 {
			b.WriteString("[]")
			return
		}
		b.WriteByte('[')
		for i, e := range x {
			if i > 0 {
				b.WriteByte(',')
			}
			if pretty {
				b.WriteByte('\n')
				b.WriteString(strings.Repeat(ind, level+1))
			}
			writeJSON(b, e, pretty, ind, level+1)
		}
		if pretty {
			b.WriteByte('\n')
			b.WriteString(strings.Repeat(ind, level))
		}
		b.WriteByte(']')
	case *OMap:
		if x.Len() == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteByte('{')
		for i, k := range x.keys {
			if i > 0 {
				b.WriteByte(',')
			}
			if pretty {
				b.WriteByte('\n')
				b.WriteString(strings.Repeat(ind, level+1))
			}
			b.WriteString(jsonEscapeString(k))
			b.WriteByte(':')
			if pretty {
				b.WriteByte(' ')
			}
			writeJSON(b, x.m[k], pretty, ind, level+1)
		}
		if pretty {
			b.WriteByte('\n')
			b.WriteString(strings.Repeat(ind, level))
		}
		b.WriteByte('}')
	default:
		b.WriteString("null")
	}
}
