cat > /workspace/tera_parse.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// ---------- AST ----------

type tNode interface{}

type tText struct{ s string }
type tVar struct{ e *tExpr }
type tIfBranch struct {
	cond *tExpr
	body []tNode
}
type tIf struct {
	branches []tIfBranch
	elseBody []tNode
}
type tFor struct {
	key, val  string
	container *tExpr
	body      []tNode
	elseBody  []tNode
}
type tSet struct {
	name   string
	e      *tExpr
	global bool
}
type tInclude struct {
	names         []string
	ignoreMissing bool
}
type tBlock struct {
	name string
	body []tNode
}
type tBreak struct{}
type tContinue struct{}
type tFilterSection struct {
	filter *tFilterCall
	body   []tNode
}
type tMacroArg struct {
	name string
	def  *tExpr
}
type tMacroDef struct {
	name string
	args []tMacroArg
	body []tNode
}
type tImport struct {
	file string
	ns   string
}
type tExtends struct{ name string }

type tFilterCall struct {
	name string
	args []tArg
}

type tArg struct {
	name string
	e    *tExpr
}

type exprKind int

const (
	eLit exprKind = iota
	eIdent
	eArray
	eFunc
	eMacroCall
	eBin
	eNot
	eNeg
	eTest
	eIn
	eConcat
	eFiltered
)

type tPathPart struct {
	name string // field name
	expr *tExpr // subscript expression
}

type tExpr struct {
	kind    exprKind
	lit     Value
	ident   string // root identifier
	path    []tPathPart
	items   []*tExpr
	op      string
	lhs     *tExpr
	rhs     *tExpr
	fname   string
	ns      string
	args    []tArg
	filters []*tFilterCall
	negated bool
	test    string
	targs   []*tExpr
	src     string
}

type tTemplate struct {
	name    string
	nodes   []tNode
	parent  string
	blocks  map[string]*tBlock
	macros  map[string]*tMacroDef
	imports []tImport
}

// ---------- Lexing template source ----------

type tChunkKind int

const (
	ckText tChunkKind = iota
	ckVar
	ckTag
	ckComment
)

type tChunk struct {
	kind       tChunkKind
	content    string
	trimBefore bool
	trimAfter  bool
}

func lexTemplate(src string) ([]tChunk, error) {
	var chunks []tChunk
	i := 0
	textStart := 0
	for i < len(src) {
		if src[i] == '{' && i+1 < len(src) && (src[i+1] == '{' || src[i+1] == '%' || src[i+1] == '#') {
			kindc := src[i+1]
			if textStart < i {
				chunks = append(chunks, tChunk{kind: ckText, content: src[textStart:i]})
			}
			j := i + 2
			trimBefore := false
			if j < len(src) && src[j] == '-' {
				trimBefore = true
				j++
			}
			var closer string
			var kind tChunkKind
			switch kindc {
			case '{':
				closer = "}}"
				kind = ckVar
			case '%':
				closer = "%}"
				kind = ckTag
			case '#':
				closer = "#}"
				kind = ckComment
			}
			// find closer, respecting strings for var/tag
			k := j
			found := -1
			var quote byte
			for k < len(src) {
				c := src[k]
				if kind != ckComment {
					if quote != 0 {
						if c == quote {
							quote = 0
						}
						k++
						continue
					}
					if c == '"' || c == '\'' || c == '`' {
						quote = c
						k++
						continue
					}
				}
				if strings.HasPrefix(src[k:], closer) {
					found = k
					break
				}
				k++
			}
			if found < 0 {
				return nil, fmt.Errorf("unclosed tag")
			}
			end := found
			trimAfter := false
			if end > j && src[end-1] == '-' {
				trimAfter = true
				end--
			}
			content := src[j:end]
			// raw blocks
			if kind == ckTag && strings.TrimSpace(content) == "raw" {
				// find endraw
				rest := src[found+2:]
				idx := findEndRaw(rest)
				if idx < 0 {
					return nil, fmt.Errorf("unclosed raw")
				}
				rawText := rest[:idx.start]
				if trimAfter {
					rawText = strings.TrimLeft(rawText, " \t\r\n")
				}
				if idx.trimBefore {
					rawText = strings.TrimRight(rawText, " \t\r\n")
				}
				chunks = append(chunks, tChunk{kind: ckTag, content: "raw", trimBefore: trimBefore})
				chunks = append(chunks, tChunk{kind: ckText, content: rawText})
				chunks = append(chunks, tChunk{kind: ckTag, content: "endraw", trimAfter: idx.trimAfter})
				i = found + 2 + idx.end
				textStart = i
				continue
			}
			chunks = append(chunks, tChunk{kind: kind, content: content, trimBefore: trimBefore, trimAfter: trimAfter})
			i = found + 2
			textStart = i
			continue
		}
		i++
	}
	if textStart < len(src) {
		chunks = append(chunks, tChunk{kind: ckText, content: src[textStart:]})
	}
	// apply whitespace trimming
	for idx := range chunks {
		c := chunks[idx]
		if c.kind == ckText {
			continue
		}
		if c.trimBefore && idx > 0 && chunks[idx-1].kind == ckText {
			chunks[idx-1].content = strings.TrimRight(chunks[idx-1].content, " \t\r\n")
		}
		if c.trimAfter && idx+1 < len(chunks) && chunks[idx+1].kind == ckText {
			chunks[idx+1].content = strings.TrimLeft(chunks[idx+1].content, " \t\r\n")
		}
	}
	return chunks, nil
}

type endRawPos struct {
	start, end           int
	trimBefore, trimAfter bool
}

func findEndRaw(s string) *endRawPosPtr {
	i := 0
	for i < len(s) {
		k := strings.Index(s[i:], "{%")
		if k < 0 {
			return nil
		}
		k += i
		j := k + 2
		tb := false
		if j < len(s) && s[j] == '-' {
			tb = true
			j++
		}
		e := strings.Index(s[j:], "%}")
		if e < 0 {
			return nil
		}
		e += j
		inner := s[j:e]
		ta := false
		if strings.HasSuffix(inner, "-") {
			ta = true
			inner = inner[:len(inner)-1]
		}
		if strings.TrimSpace(inner) == "endraw" {
			return &endRawPosPtr{start: k, end: e + 2, trimBefore: tb, trimAfter: ta}
		}
		i = e + 2
	}
	return nil
}

type endRawPosPtr = endRawPos

// ---------- Expression tokenizer ----------

type tTokKind int

const (
	tkEOF tTokKind = iota
	tkIdent
	tkInt
	tkFloat
	tkString
	tkOp
)

type tTok struct {
	kind tTokKind
	s    string
}

func tokenizeExpr(s string) ([]tTok, error) {
	var toks []tTok
	i := 0
	for i < len(s) {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		if isASCIIAlpha(c) || c == '_' {
			j := i
			for j < len(s) && (isASCIIAlnum(s[j]) || s[j] == '_') {
				j++
			}
			toks = append(toks, tTok{tkIdent, s[i:j]})
			i = j
			continue
		}
		if isASCIIDigit(c) {
			j := i
			for j < len(s) && isASCIIDigit(s[j]) {
				j++
			}
			if j+1 < len(s) && s[j] == '.' && isASCIIDigit(s[j+1]) {
				j++
				for j < len(s) && isASCIIDigit(s[j]) {
					j++
				}
				toks = append(toks, tTok{tkFloat, s[i:j]})
			} else {
				toks = append(toks, tTok{tkInt, s[i:j]})
			}
			i = j
			continue
		}
		if c == '"' || c == '\'' || c == '`' {
			j := i + 1
			for j < len(s) && s[j] != c {
				j++
			}
			if j >= len(s) {
				return nil, fmt.Errorf("unterminated string")
			}
			toks = append(toks, tTok{tkString, s[i+1 : j]})
			i = j + 1
			continue
		}
		two := ""
		if i+1 < len(s) {
			two = s[i : i+2]
		}
		switch two {
		case "==", "!=", "<=", ">=", "::":
			toks = append(toks, tTok{tkOp, two})
			i += 2
			continue
		}
		switch c {
		case '<', '>', '+', '-', '*', '/', '%', '~', '|', '(', ')', '[', ']', ',', '=', '.', '{', '}', ':':
			toks = append(toks, tTok{tkOp, string(c)})
			i++
			continue
		}
		return nil, fmt.Errorf("unexpected character %q", c)
	}
	return toks, nil
}

type exprParser struct {
	toks []tTok
	pos  int
}

func (p *exprParser) peek() tTok {
	if p.pos < len(p.toks) {
		return p.toks[p.pos]
	}
	return tTok{kind: tkEOF}
}

func (p *exprParser) peekN(n int) tTok {
	if p.pos+n < len(p.toks) {
		return p.toks[p.pos+n]
	}
	return tTok{kind: tkEOF}
}

func (p *exprParser) next() tTok {
	t := p.peek()
	if p.pos < len(p.toks) {
		p.pos++
	}
	return t
}

func (p *exprParser) isOp(s string) bool {
	t := p.peek()
	return t.kind == tkOp && t.s == s
}

func (p *exprParser) isKw(s string) bool {
	t := p.peek()
	return t.kind == tkIdent && t.s == s
}

func (p *exprParser) expectOp(s string) error {
	if !p.isOp(s) {
		return fmt.Errorf("expected %q, got %q", s, p.peek().s)
	}
	p.pos++
	return nil
}

func parseExprString(s string) (*tExpr, error) {
	toks, err := tokenizeExpr(s)
	if err != nil {
		return nil, err
	}
	p := &exprParser{toks: toks}
	e, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tkEOF {
		return nil, fmt.Errorf("unexpected token %q", p.peek().s)
	}
	return e, nil
}

func (p *exprParser) parseExpr() (*tExpr, error) { return p.parseOr() }

func (p *exprParser) parseOr() (*tExpr, error) {
	l, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.isKw("or") {
		p.next()
		r, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		l = &tExpr{kind: eBin, op: "or", lhs: l, rhs: r}
	}
	return l, nil
}

func (p *exprParser) parseAnd() (*tExpr, error) {
	l, err := p.parseNot()
	if err != nil {
		return nil, err
	}
	for p.isKw("and") {
		p.next()
		r, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		l = &tExpr{kind: eBin, op: "and", lhs: l, rhs: r}
	}
	return l, nil
}

func (p *exprParser) parseNot() (*tExpr, error) {
	if p.isKw("not") {
		p.next()
		e, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		return &tExpr{kind: eNot, lhs: e}, nil
	}
	return p.parseCmp()
}

func (p *exprParser) parseCmp() (*tExpr, error) {
	l, err := p.parseFiltered()
	if err != nil {
		return nil, err
	}
	t := p.peek()
	if t.kind == tkOp {
		switch t.s {
		case "==", "!=", "<", ">", "<=", ">=":
			p.next()
			r, err := p.parseFiltered()
			if err != nil {
				return nil, err
			}
			return &tExpr{kind: eBin, op: t.s, lhs: l, rhs: r}, nil
		}
	}
	if p.isKw("not") && p.peekN(1).kind == tkIdent && p.peekN(1).s == "in" {
		p.next()
		p.next()
		r, err := p.parseFiltered()
		if err != nil {
			return nil, err
		}
		return &tExpr{kind: eIn, lhs: l, rhs: r, negated: true}, nil
	}
	if p.isKw("in") {
		p.next()
		r, err := p.parseFiltered()
		if err != nil {
			return nil, err
		}
		return &tExpr{kind: eIn, lhs: l, rhs: r}, nil
	}
	if p.isKw("is") {
		p.next()
		neg := false
		if p.isKw("not") {
			p.next()
			neg = true
		}
		nt := p.next()
		if nt.kind != tkIdent {
			return nil, fmt.Errorf("expected test name")
		}
		e := &tExpr{kind: eTest, lhs: l, test: nt.s, negated: neg}
		if p.isOp("(") {
			p.next()
			for !p.isOp(")") {
				a, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				e.targs = append(e.targs, a)
				if p.isOp(",") {
					p.next()
				}
			}
			p.next()
		}
		return e, nil
	}
	return l, nil
}

func (p *exprParser) parseFiltered() (*tExpr, error) {
	l, err := p.parseConcat()
	if err != nil {
		return nil, err
	}
	if p.isOp("|") {
		var filters []*tFilterCall
		for p.isOp("|") {
			p.next()
			f, err := p.parseFilterCall()
			if err != nil {
				return nil, err
			}
			filters = append(filters, f)
		}
		return &tExpr{kind: eFiltered, lhs: l, filters: filters}, nil
	}
	return l, nil
}

func (p *exprParser) parseFilterCall() (*tFilterCall, error) {
	nt := p.next()
	if nt.kind != tkIdent {
		return nil, fmt.Errorf("expected filter name")
	}
	f := &tFilterCall{name: nt.s}
	if p.isOp("(") {
		args, err := p.parseKwArgs()
		if err != nil {
			return nil, err
		}
		f.args = args
	}
	return f, nil
}

func (p *exprParser) parseKwArgs() ([]tArg, error) {
	if err := p.expectOp("("); err != nil {
		return nil, err
	}
	var args []tArg
	for !p.isOp(")") {
		if p.peek().kind == tkEOF {
			return nil, fmt.Errorf("unterminated args")
		}
		name := ""
		if p.peek().kind == tkIdent && p.peekN(1).kind == tkOp && p.peekN(1).s == "=" {
			name = p.next().s
			p.next()
		}
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, tArg{name: name, e: e})
		if p.isOp(",") {
			p.next()
		}
	}
	p.next()
	return args, nil
}

func (p *exprParser) parseConcat() (*tExpr, error) {
	l, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	if p.isOp("~") {
		items := []*tExpr{l}
		for p.isOp("~") {
			p.next()
			r, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			items = append(items, r)
		}
		return &tExpr{kind: eConcat, items: items}, nil
	}
	return l, nil
}

func (p *exprParser) parseAdd() (*tExpr, error) {
	l, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") {
		op := p.next().s
		r, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		l = &tExpr{kind: eBin, op: op, lhs: l, rhs: r}
	}
	return l, nil
}

func (p *exprParser) parseMul() (*tExpr, error) {
	l, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.isOp("*") || p.isOp("/") || p.isOp("%") {
		op := p.next().s
		r, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		l = &tExpr{kind: eBin, op: op, lhs: l, rhs: r}
	}
	return l, nil
}

func (p *exprParser) parseUnary() (*tExpr, error) {
	if p.isOp("-") {
		p.next()
		e, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &tExpr{kind: eNeg, lhs: e}, nil
	}
	return p.parsePrimary()
}

func (p *exprParser) parsePrimary() (*tExpr, error) {
	t := p.next()
	switch t.kind {
	case tkInt:
		n, err := strconv.ParseInt(t.s, 10, 64)
		if err != nil {
			f, _ := strconv.ParseFloat(t.s, 64)
			return &tExpr{kind: eLit, lit: f}, nil
		}
		return &tExpr{kind: eLit, lit: n}, nil
	case tkFloat:
		f, _ := strconv.ParseFloat(t.s, 64)
		return &tExpr{kind: eLit, lit: f}, nil
	case tkString:
		return &tExpr{kind: eLit, lit: t.s}, nil
	case tkOp:
		if t.s == "(" {
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return e, nil
		}
		if t.s == "[" {
			arr := &tExpr{kind: eArray}
			for !p.isOp("]") {
				if p.peek().kind == tkEOF {
					return nil, fmt.Errorf("unterminated array")
				}
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				arr.items = append(arr.items, e)
				if p.isOp(",") {
					p.next()
				}
			}
			p.next()
			return arr, nil
		}
		return nil, fmt.Errorf("unexpected %q", t.s)
	case tkIdent:
		switch t.s {
		case "true", "True":
			return &tExpr{kind: eLit, lit: true}, nil
		case "false", "False":
			return &tExpr{kind: eLit, lit: false}, nil
		}
		// macro call ns::name(...)
		if p.isOp("::") {
			p.next()
			nt := p.next()
			args, err := p.parseKwArgs()
			if err != nil {
				return nil, err
			}
			return &tExpr{kind: eMacroCall, ns: t.s, fname: nt.s, args: args}, nil
		}
		if p.isOp("(") {
			args, err := p.parseKwArgs()
			if err != nil {
				return nil, err
			}
			return &tExpr{kind: eFunc, fname: t.s, args: args}, nil
		}
		e := &tExpr{kind: eIdent, ident: t.s}
		for {
			if p.isOp(".") {
				p.next()
				nt := p.next()
				if nt.kind != tkIdent && nt.kind != tkInt {
					return nil, fmt.Errorf("bad attribute")
				}
				e.path = append(e.path, tPathPart{name: nt.s})
				continue
			}
			if p.isOp("[") {
				p.next()
				ie, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				if err := p.expectOp("]"); err != nil {
					return nil, err
				}
				e.path = append(e.path, tPathPart{expr: ie})
				continue
			}
			break
		}
		return e, nil
	}
	return nil, fmt.Errorf("unexpected end of expression")
}

// ---------- Template parser ----------

type tplParser struct {
	chunks []tChunk
	pos    int
	tpl    *tTemplate
}

func parseTemplate(name, src string) (*tTemplate, error) {
	chunks, err := lexTemplate(src)
	if err != nil {
		return nil, fmt.Errorf("%s: %v", name, err)
	}
	tp := &tplParser{chunks: chunks, tpl: &tTemplate{name: name, blocks: map[string]*tBlock{}, macros: map[string]*tMacroDef{}}}
	nodes, end, err := tp.parseNodes(nil)
	if err != nil {
		return nil, fmt.Errorf("%s: %v", name, err)
	}
	if end != "" {
		return nil, fmt.Errorf("%s: unexpected %s", name, end)
	}
	tp.tpl.nodes = nodes
	return tp.tpl, nil
}

func tagWord(content string) (string, string) {
	c := strings.TrimSpace(content)
	i := 0
	for i < len(c) && (isASCIIAlnum(c[i]) || c[i] == '_') {
		i++
	}
	return c[:i], strings.TrimSpace(c[i:])
}

// parseNodes parses until one of the end tags; returns the end tag word and rest.
func (tp *tplParser) parseNodes(ends []string) ([]tNode, string, error) {
	var nodes []tNode
	for tp.pos < len(tp.chunks) {
		c := tp.chunks[tp.pos]
		switch c.kind {
		case ckText:
			tp.pos++
			if c.content != "" {
				nodes = append(nodes, &tText{s: c.content})
			}
		case ckComment:
			tp.pos++
		case ckVar:
			tp.pos++
			e, err := parseExprString(c.content)
			if err != nil {
				return nil, "", err
			}
			e.src = strings.TrimSpace(c.content)
			nodes = append(nodes, &tVar{e: e})
		case ckTag:
			word, rest := tagWord(c.content)
			for _, e := range ends {
				if word == e {
					return nodes, word, nil
				}
			}
			tp.pos++
			n, err := tp.parseTag(word, rest)
			if err != nil {
				return nil, "", err
			}
			if n != nil {
				nodes = append(nodes, n)
			}
		}
	}
	if len(ends) > 0 {
		return nil, "", fmt.Errorf("missing end tag %v", ends)
	}
	return nodes, "", nil
}

func (tp *tplParser) curTagRest() string {
	_, rest := tagWord(tp.chunks[tp.pos].content)
	return rest
}

func (tp *tplParser) parseTag(word, rest string) (tNode, error) {
	switch word {
	case "if":
		cond, err := parseExprString(rest)
		if err != nil {
			return nil, err
		}
		n := &tIf{}
		curCond := cond
		for {
			body, end, err := tp.parseNodes([]string{"elif", "else", "endif"})
			if err != nil {
				return nil, err
			}
			n.branches = append(n.branches, tIfBranch{cond: curCond, body: body})
			r := tp.curTagRest()
			tp.pos++
			if end == "elif" {
				curCond, err = parseExprString(r)
				if err != nil {
					return nil, err
				}
				continue
			}
			if end == "else" {
				eb, end2, err := tp.parseNodes([]string{"endif"})
				if err != nil {
					return nil, err
				}
				_ = end2
				tp.pos++
				n.elseBody = eb
			}
			break
		}
		return n, nil
	case "for":
		inIdx := strings.Index(rest, " in ")
		if inIdx < 0 {
			return nil, fmt.Errorf("bad for")
		}
		vars := strings.TrimSpace(rest[:inIdx])
		cont := strings.TrimSpace(rest[inIdx+4:])
		n := &tFor{}
		if strings.Contains(vars, ",") {
			parts := strings.SplitN(vars, ",", 2)
			n.key = strings.TrimSpace(parts[0])
			n.val = strings.TrimSpace(parts[1])
		} else {
			n.val = vars
		}
		ce, err := parseExprString(cont)
		if err != nil {
			return nil, err
		}
		n.container = ce
		body, end, err := tp.parseNodes([]string{"else", "endfor"})
		if err != nil {
			return nil, err
		}
		n.body = body
		tp.pos++
		if end == "else" {
			eb, _, err := tp.parseNodes([]string{"endfor"})
			if err != nil {
				return nil, err
			}
			tp.pos++
			n.elseBody = eb
		}
		return n, nil
	case "break":
		return &tBreak{}, nil
	case "continue":
		return &tContinue{}, nil
	case "set", "set_global":
		eq := strings.Index(rest, "=")
		if eq < 0 {
			return nil, fmt.Errorf("bad set")
		}
		name := strings.TrimSpace(rest[:eq])
		e, err := parseExprString(rest[eq+1:])
		if err != nil {
			return nil, err
		}
		return &tSet{name: name, e: e, global: word == "set_global"}, nil
	case "include":
		n := &tInclude{}
		r := rest
		if strings.HasSuffix(r, "ignore missing") {
			n.ignoreMissing = true
			r = strings.TrimSpace(strings.TrimSuffix(r, "ignore missing"))
		}
		e, err := parseExprString(r)
		if err != nil {
			return nil, err
		}
		switch e.kind {
		case eLit:
			s, _ := e.lit.(string)
			n.names = []string{s}
		case eArray:
			for _, it := range e.items {
				if s, ok := it.lit.(string); ok {
					n.names = append(n.names, s)
				}
			}
		}
		return n, nil
	case "extends":
		e, err := parseExprString(rest)
		if err != nil {
			return nil, err
		}
		s, _ := e.lit.(string)
		tp.tpl.parent = s
		return nil, nil
	case "block":
		name := strings.TrimSpace(rest)
		body, _, err := tp.parseNodes([]string{"endblock"})
		if err != nil {
			return nil, err
		}
		tp.pos++
		b := &tBlock{name: name, body: body}
		if _, exists := tp.tpl.blocks[name]; !exists {
			tp.tpl.blocks[name] = b
		}
		return b, nil
	case "macro":
		paren := strings.Index(rest, "(")
		if paren < 0 {
			return nil, fmt.Errorf("bad macro")
		}
		name := strings.TrimSpace(rest[:paren])
		argsStr := strings.TrimSpace(rest[paren:])
		toks, err := tokenizeExpr(argsStr)
		if err != nil {
			return nil, err
		}
		ep := &exprParser{toks: toks}
		ep.next() // (
		m := &tMacroDef{name: name}
		for !ep.isOp(")") && ep.peek().kind != tkEOF {
			an := ep.next().s
			arg := tMacroArg{name: an}
			if ep.isOp("=") {
				ep.next()
				d, err := ep.parseExpr()
				if err != nil {
					return nil, err
				}
				arg.def = d
			}
			m.args = append(m.args, arg)
			if ep.isOp(",") {
				ep.next()
			}
		}
		body, _, err := tp.parseNodes([]string{"endmacro"})
		if err != nil {
			return nil, err
		}
		tp.pos++
		m.body = body
		tp.tpl.macros[name] = m
		return nil, nil
	case "import":
		// import "file" as ns
		idx := strings.LastIndex(rest, " as ")
		if idx < 0 {
			return nil, fmt.Errorf("bad import")
		}
		fe, err := parseExprString(rest[:idx])
		if err != nil {
			return nil, err
		}
		f, _ := fe.lit.(string)
		tp.tpl.imports = append(tp.tpl.imports, tImport{file: f, ns: strings.TrimSpace(rest[idx+4:])})
		return nil, nil
	case "filter":
		toks, err := tokenizeExpr(rest)
		if err != nil {
			return nil, err
		}
		ep := &exprParser{toks: toks}
		fc, err := ep.parseFilterCall()
		if err != nil {
			return nil, err
		}
		body, _, err := tp.parseNodes([]string{"endfilter"})
		if err != nil {
			return nil, err
		}
		tp.pos++
		return &tFilterSection{filter: fc, body: body}, nil
	case "raw":
		var nodes []tNode
		for tp.pos < len(tp.chunks) {
			c := tp.chunks[tp.pos]
			tp.pos++
			if c.kind == ckTag {
				w, _ := tagWord(c.content)
				if w == "endraw" {
					break
				}
			}
			if c.kind == ckText {
				nodes = append(nodes, &tText{s: c.content})
			}
		}
		return &tFilterSection{filter: nil, body: nodes}, nil
	}
	return nil, fmt.Errorf("unknown tag %q", word)
}
