package main

import (
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
)

type FilterFn func(v Value, args map[string]Value) (Value, error)
type FuncFn func(args map[string]Value) (Value, error)
type TestFn func(v Value, args []Value) (bool, error)

type Tera struct {
	templates map[string]*tTemplate
	filters   map[string]FilterFn
	tests     map[string]TestFn
	functions map[string]FuncFn
}

func NewTera() *Tera {
	t := &Tera{templates: map[string]*tTemplate{}, filters: map[string]FilterFn{}, tests: map[string]TestFn{}, functions: map[string]FuncFn{}}
	registerBuiltinFilters(t)
	registerBuiltinTests(t)
	registerBuiltinFunctions(t)
	return t
}

func (t *Tera) AddTemplate(name, src string) error {
	tpl, err := parseTemplate(name, src)
	if err != nil {
		return err
	}
	t.templates[name] = tpl
	return nil
}

func (t *Tera) HasTemplate(name string) bool {
	_, ok := t.templates[name]
	return ok
}

type tFrame struct {
	vars    map[string]Value
	isLoop  bool
	isMacro bool
}

type tRenderState struct {
	tera      *Tera
	tplName   string
	chain     []*tTemplate
	frames    []*tFrame
	global    *OMap
	blockName string
	blockLvl  int
	macroNS   map[string]*tTemplate
	curTpl    *tTemplate
}

var errBreak = errors.New("break")
var errContinue = errors.New("continue")

type notFoundError struct{ msg string }

func (e *notFoundError) Error() string { return e.msg }

func (t *Tera) Render(name string, ctx *OMap) (string, error) {
	tpl, ok := t.templates[name]
	if !ok {
		return "", fmt.Errorf("Template '%s' not found", name)
	}
	st := &tRenderState{tera: t, tplName: name, global: ctx}
	st.frames = []*tFrame{{vars: map[string]Value{}}}
	chain := []*tTemplate{tpl}
	cur := tpl
	for cur.parent != "" {
		p, ok := t.templates[cur.parent]
		if !ok {
			return "", fmt.Errorf("Template '%s' is inheriting from '%s', which doesn't exist or isn't loaded.", cur.name, cur.parent)
		}
		chain = append(chain, p)
		cur = p
	}
	st.chain = chain
	st.curTpl = tpl
	st.macroNS = map[string]*tTemplate{}
	for _, c := range chain {
		for _, im := range c.imports {
			if mt, ok := t.templates[im.file]; ok {
				st.macroNS[im.ns] = mt
			}
		}
	}
	var b strings.Builder
	root := chain[len(chain)-1]
	if err := st.renderNodes(root.nodes, &b); err != nil {
		if err == errBreak || err == errContinue {
			return b.String(), nil
		}
		return "", fmt.Errorf("Failed to render '%s': %v", name, err)
	}
	return b.String(), nil
}

// RenderString renders an ad-hoc template string.
func (t *Tera) RenderString(src string, ctx *OMap) (string, error) {
	tpl, err := parseTemplate("__tera_one_off", src)
	if err != nil {
		return "", err
	}
	t.templates["__tera_one_off"] = tpl
	defer delete(t.templates, "__tera_one_off")
	return t.Render("__tera_one_off", ctx)
}

func (st *tRenderState) renderNodes(nodes []tNode, b *strings.Builder) error {
	for _, n := range nodes {
		if err := st.renderNode(n, b); err != nil {
			return err
		}
	}
	return nil
}

func (st *tRenderState) renderNode(n tNode, b *strings.Builder) error {
	switch x := n.(type) {
	case *tText:
		b.WriteString(x.s)
	case *tVar:
		v, err := st.evalExpr(x.e)
		if err != nil {
			return err
		}
		b.WriteString(renderValue(v))
	case *tIf:
		for _, br := range x.branches {
			ok, err := st.evalBool(br.cond)
			if err != nil {
				return err
			}
			if ok {
				return st.renderNodes(br.body, b)
			}
		}
		if x.elseBody != nil {
			return st.renderNodes(x.elseBody, b)
		}
	case *tFor:
		return st.renderFor(x, b)
	case *tBreak:
		return errBreak
	case *tContinue:
		return errContinue
	case *tSet:
		v, err := st.evalExpr(x.e)
		if err != nil {
			return err
		}
		if x.global {
			st.frames[0].vars[x.name] = v
		} else {
			st.frames[len(st.frames)-1].vars[x.name] = v
		}
	case *tInclude:
		for _, name := range x.names {
			tpl, ok := st.tera.templates[name]
			if !ok {
				continue
			}
			sub := &tRenderState{tera: st.tera, tplName: name, chain: []*tTemplate{tpl}, frames: st.frames, global: st.global, macroNS: st.macroNS, curTpl: tpl}
			for _, im := range tpl.imports {
				if mt, ok := st.tera.templates[im.file]; ok {
					sub.macroNS[im.ns] = mt
				}
			}
			// includes share frames; sets inside include stay inside? keep simple: new frame
			sub.frames = append(append([]*tFrame{}, st.frames...), &tFrame{vars: map[string]Value{}})
			err := sub.renderNodes(tpl.nodes, b)
			if err != nil {
				return err
			}
			return nil
		}
		if !x.ignoreMissing {
			return fmt.Errorf("Template '%s' not found", strings.Join(x.names, ", "))
		}
	case *tBlock:
		return st.renderBlock(x.name, 0, b)
	case *tFilterSection:
		var sb strings.Builder
		if err := st.renderNodes(x.body, &sb); err != nil {
			return err
		}
		if x.filter == nil {
			b.WriteString(sb.String())
			return nil
		}
		v, err := st.applyFilter(sb.String(), x.filter)
		if err != nil {
			return err
		}
		b.WriteString(renderValue(v))
	}
	return nil
}

func (st *tRenderState) renderBlock(name string, startLvl int, b *strings.Builder) error {
	for lvl := startLvl; lvl < len(st.chain); lvl++ {
		if blk, ok := st.chain[lvl].blocks[name]; ok {
			saveName, saveLvl, saveTpl := st.blockName, st.blockLvl, st.curTpl
			st.blockName, st.blockLvl = name, lvl
			st.curTpl = st.chain[lvl]
			err := st.renderNodes(blk.body, b)
			st.blockName, st.blockLvl, st.curTpl = saveName, saveLvl, saveTpl
			return err
		}
	}
	return nil
}

func (st *tRenderState) renderFor(x *tFor, b *strings.Builder) error {
	cont, err := st.evalExpr(x.container)
	if err != nil {
		return err
	}
	type kv struct {
		k Value
		v Value
	}
	var items []kv
	switch c := cont.(type) {
	case []Value:
		if x.key != "" {
			return fmt.Errorf("Tried to iterate using key value on variable `%s`, but it isn't an object/map", x.container.src)
		}
		for _, v := range c {
			items = append(items, kv{nil, v})
		}
	case *OMap:
		if x.key == "" {
			return fmt.Errorf("Tried to iterate using key value on variable `%s`, but it is missing a key", x.container.src)
		}
		for _, k := range c.keys {
			items = append(items, kv{k, c.m[k]})
		}
	case string:
		for _, r := range c {
			items = append(items, kv{nil, string(r)})
		}
	case nil:
		return fmt.Errorf("Tried to iterate on a container (`%s`) that has a unsupported type", x.container.src)
	default:
		return fmt.Errorf("Tried to iterate on a container (`%s`) that has a unsupported type", x.container.src)
	}
	if len(items) == 0 {
		if x.elseBody != nil {
			return st.renderNodes(x.elseBody, b)
		}
		return nil
	}
	frame := &tFrame{vars: map[string]Value{}, isLoop: true}
	st.frames = append(st.frames, frame)
	defer func() { st.frames = st.frames[:len(st.frames)-1] }()
	for i, it := range items {
		loop := NewOMap()
		loop.Set("index", int64(i+1))
		loop.Set("index0", int64(i))
		loop.Set("first", i == 0)
		loop.Set("last", i == len(items)-1)
		frame.vars["loop"] = loop
		frame.vars[x.val] = it.v
		if x.key != "" {
			frame.vars[x.key] = it.k
		}
		err := st.renderNodes(x.body, b)
		if err == errBreak {
			break
		}
		if err == errContinue {
			continue
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (st *tRenderState) lookupRoot(name string) (Value, bool) {
	for i := len(st.frames) - 1; i >= 0; i-- {
		f := st.frames[i]
		if v, ok := f.vars[name]; ok {
			return v, true
		}
		if f.isMacro {
			return nil, false
		}
	}
	if name == "__tera_context" {
		return st.global, true
	}
	if v, ok := st.global.Get(name); ok {
		return v, true
	}
	return nil, false
}

func identString(e *tExpr) string {
	s := e.ident
	for _, p := range e.path {
		if p.expr != nil {
			s += "[" + exprSrc(p.expr) + "]"
		} else {
			s += "." + p.name
		}
	}
	return s
}

func exprSrc(e *tExpr) string {
	switch e.kind {
	case eIdent:
		return identString(e)
	case eLit:
		if s, ok := e.lit.(string); ok {
			return "\"" + s + "\""
		}
		return renderValue(e.lit)
	}
	return e.src
}

func (st *tRenderState) lookupIdent(e *tExpr) (Value, error) {
	v, ok := st.lookupRoot(e.ident)
	if !ok {
		return nil, &notFoundError{fmt.Sprintf("Variable `%s` not found in context while rendering '%s'", identString(e), st.tplName)}
	}
	for _, p := range e.path {
		var key Value
		if p.expr != nil {
			k, err := st.evalExpr(p.expr)
			if err != nil {
				return nil, err
			}
			key = k
		} else {
			key = p.name
		}
		switch c := v.(type) {
		case *OMap:
			ks := renderValue(key)
			nv, ok := c.Get(ks)
			if !ok {
				return nil, &notFoundError{fmt.Sprintf("Variable `%s` not found in context while rendering '%s'", identString(e), st.tplName)}
			}
			v = nv
		case []Value:
			var idx int64 = -1
			switch k := key.(type) {
			case int64:
				idx = k
			case float64:
				idx = int64(k)
			case string:
				n, err := strconv.ParseInt(k, 10, 64)
				if err == nil {
					idx = n
				}
			}
			if idx < 0 || idx >= int64(len(c)) {
				return nil, &notFoundError{fmt.Sprintf("Variable `%s` not found in context while rendering '%s'", identString(e), st.tplName)}
			}
			v = c[idx]
		default:
			return nil, &notFoundError{fmt.Sprintf("Variable `%s` not found in context while rendering '%s'", identString(e), st.tplName)}
		}
	}
	return v, nil
}

func (st *tRenderState) evalBool(e *tExpr) (bool, error) {
	switch e.kind {
	case eIdent:
		v, err := st.evalExpr(e)
		if err != nil {
			return false, nil
		}
		return isTruthy(v), nil
	case eFiltered:
		if e.lhs.kind == eIdent || e.lhs.kind == eLit {
			v, err := st.evalExpr(e)
			if err != nil {
				return false, nil
			}
			return isTruthy(v), nil
		}
	case eNot:
		r, err := st.evalBool(e.lhs)
		if err != nil {
			return false, err
		}
		return !r, nil
	case eBin:
		switch e.op {
		case "or":
			l, err := st.evalBool(e.lhs)
			if err != nil {
				return false, err
			}
			if l {
				return true, nil
			}
			return st.evalBool(e.rhs)
		case "and":
			l, err := st.evalBool(e.lhs)
			if err != nil {
				return false, err
			}
			if !l {
				return false, nil
			}
			return st.evalBool(e.rhs)
		}
	}
	v, err := st.evalExpr(e)
	if err != nil {
		return false, err
	}
	return isTruthy(v), nil
}

func (st *tRenderState) evalArgs(args []tArg) (map[string]Value, error) {
	m := map[string]Value{}
	for i, a := range args {
		v, err := st.evalExpr(a.e)
		if err != nil {
			return nil, err
		}
		name := a.name
		if name == "" {
			name = fmt.Sprintf("__pos%d", i)
		}
		m[name] = v
	}
	return m, nil
}

func (st *tRenderState) evalExpr(e *tExpr) (Value, error) {
	switch e.kind {
	case eLit:
		return e.lit, nil
	case eIdent:
		return st.lookupIdent(e)
	case eArray:
		arr := make([]Value, 0, len(e.items))
		for _, it := range e.items {
			v, err := st.evalExpr(it)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
		}
		return arr, nil
	case eFunc:
		if e.fname == "super" {
			var b strings.Builder
			if err := st.renderBlock(st.blockName, st.blockLvl+1, &b); err != nil {
				return nil, err
			}
			return b.String(), nil
		}
		f, ok := st.tera.functions[e.fname]
		if !ok {
			return nil, fmt.Errorf("Function '%s' not found", e.fname)
		}
		args, err := st.evalArgs(e.args)
		if err != nil {
			return nil, err
		}
		return f(args)
	case eMacroCall:
		return st.callMacro(e)
	case eNeg:
		v, err := st.evalExpr(e.lhs)
		if err != nil {
			return nil, err
		}
		switch n := v.(type) {
		case int64:
			return -n, nil
		case float64:
			return -n, nil
		}
		return nil, fmt.Errorf("cannot negate non-number")
	case eNot:
		r, err := st.evalBool(e.lhs)
		if err != nil {
			return nil, err
		}
		return !r, nil
	case eConcat:
		var sb strings.Builder
		for _, it := range e.items {
			v, err := st.evalExpr(it)
			if err != nil {
				return nil, err
			}
			sb.WriteString(renderValue(v))
		}
		return sb.String(), nil
	case eFiltered:
		var base Value
		filters := e.filters
		v, err := st.evalExpr(e.lhs)
		if err != nil || v == nil {
			if len(filters) > 0 && filters[0].name == "default" && (e.lhs.kind == eIdent) {
				args, aerr := st.evalArgs(filters[0].args)
				if aerr != nil {
					return nil, aerr
				}
				base = args["value"]
				if base == nil {
					base = args["__pos0"]
				}
				err = nil
			} else if err != nil {
				return nil, err
			} else {
				base = v
			}
		} else {
			base = v
		}
		for _, f := range filters {
			if f.name == "default" || f.name == "safe" {
				continue
			}
			base, err = st.applyFilter(base, f)
			if err != nil {
				return nil, err
			}
		}
		return base, nil
	case eTest:
		return st.evalTest(e)
	case eIn:
		l, err := st.evalExpr(e.lhs)
		if err != nil {
			return nil, err
		}
		r, err := st.evalExpr(e.rhs)
		if err != nil {
			return nil, err
		}
		res := false
		switch c := r.(type) {
		case string:
			ls, ok := l.(string)
			if !ok {
				return nil, fmt.Errorf("Tried to check if a non-string is in a string")
			}
			res = strings.Contains(c, ls)
		case []Value:
			for _, it := range c {
				if valuesEqual(it, l) {
					res = true
					break
				}
			}
		case *OMap:
			ls, ok := l.(string)
			if !ok {
				return nil, fmt.Errorf("Tried to check if a non-string key is in an object")
			}
			_, res = c.Get(ls)
		default:
			return nil, fmt.Errorf("Tried to check if a value is in a container of unsupported type")
		}
		if e.negated {
			res = !res
		}
		return res, nil
	case eBin:
		switch e.op {
		case "or", "and":
			r, err := st.evalBool(e)
			return r, err
		case "==", "!=":
			l, err := st.evalExpr(e.lhs)
			if err != nil {
				return nil, err
			}
			r, err := st.evalExpr(e.rhs)
			if err != nil {
				return nil, err
			}
			eq := false
			if isNumber(l) || isNumber(r) {
				if isNumber(l) && isNumber(r) {
					lf, _ := toFloat(l)
					rf, _ := toFloat(r)
					eq = lf == rf
				}
			} else {
				eq = valuesEqual(l, r)
			}
			if e.op == "==" {
				return eq, nil
			}
			return !eq, nil
		case "<", ">", "<=", ">=":
			l, err := st.evalExpr(e.lhs)
			if err != nil {
				return nil, err
			}
			r, err := st.evalExpr(e.rhs)
			if err != nil {
				return nil, err
			}
			lf, ok1 := toFloat(l)
			rf, ok2 := toFloat(r)
			if !ok1 || !ok2 {
				return nil, fmt.Errorf("Comparison to NaN")
			}
			switch e.op {
			case "<":
				return lf < rf, nil
			case ">":
				return lf > rf, nil
			case "<=":
				return lf <= rf, nil
			default:
				return lf >= rf, nil
			}
		case "+", "-", "*", "/", "%":
			l, err := st.evalExpr(e.lhs)
			if err != nil {
				return nil, err
			}
			r, err := st.evalExpr(e.rhs)
			if err != nil {
				return nil, err
			}
			return mathOp(e.op, l, r)
		}
	}
	return nil, fmt.Errorf("unsupported expression")
}

func mathOp(op string, l, r Value) (Value, error) {
	li, lInt := l.(int64)
	ri, rInt := r.(int64)
	lf, ok1 := toFloat(l)
	rf, ok2 := toFloat(r)
	if !ok1 || !ok2 {
		return nil, fmt.Errorf("Tried to do math with non-numbers")
	}
	switch op {
	case "+":
		if lInt && rInt {
			return li + ri, nil
		}
		return lf + rf, nil
	case "-":
		if lInt && rInt {
			return li - ri, nil
		}
		return lf - rf, nil
	case "*":
		if lInt && rInt {
			return li * ri, nil
		}
		return lf * rf, nil
	case "/":
		if rf == 0 {
			return nil, fmt.Errorf("Tried to divide by zero")
		}
		return lf / rf, nil
	case "%":
		if lInt && rInt {
			if ri == 0 {
				return nil, fmt.Errorf("Tried to do a modulo by zero")
			}
			return li % ri, nil
		}
		return math.Mod(lf, rf), nil
	}
	return nil, fmt.Errorf("bad op")
}

func (st *tRenderState) applyFilter(v Value, f *tFilterCall) (Value, error) {
	fn, ok := st.tera.filters[f.name]
	if !ok {
		return nil, fmt.Errorf("Filter '%s' not found", f.name)
	}
	args, err := st.evalArgs(f.args)
	if err != nil {
		return nil, err
	}
	return fn(v, args)
}

func (st *tRenderState) evalTest(e *tExpr) (Value, error) {
	name := e.test
	var res bool
	if name == "defined" || name == "undefined" {
		_, err := st.evalExpr(e.lhs)
		def := err == nil
		if name == "defined" {
			res = def
		} else {
			res = !def
		}
	} else {
		fn, ok := st.tera.tests[name]
		if !ok {
			return nil, fmt.Errorf("Test '%s' not found", name)
		}
		v, err := st.evalExpr(e.lhs)
		if err != nil {
			return nil, err
		}
		var args []Value
		for _, a := range e.targs {
			av, err := st.evalExpr(a)
			if err != nil {
				return nil, err
			}
			args = append(args, av)
		}
		res, err = fn(v, args)
		if err != nil {
			return nil, err
		}
	}
	if e.negated {
		res = !res
	}
	return res, nil
}

func (st *tRenderState) callMacro(e *tExpr) (Value, error) {
	var tpl *tTemplate
	if e.ns == "self" {
		tpl = st.curTpl
	} else {
		tpl = st.macroNS[e.ns]
	}
	if tpl == nil {
		return nil, fmt.Errorf("Macro namespace `%s` was not found in template `%s`", e.ns, st.tplName)
	}
	m, ok := tpl.macros[e.fname]
	if !ok {
		return nil, fmt.Errorf("Macro `%s::%s` not found", e.ns, e.fname)
	}
	args, err := st.evalArgs(e.args)
	if err != nil {
		return nil, err
	}
	frame := &tFrame{vars: map[string]Value{}, isMacro: true}
	for i, a := range m.args {
		if v, ok := args[a.name]; ok {
			frame.vars[a.name] = v
		} else if v, ok := args[fmt.Sprintf("__pos%d", i)]; ok {
			frame.vars[a.name] = v
		} else if a.def != nil {
			dv, err := st.evalExpr(a.def)
			if err != nil {
				return nil, err
			}
			frame.vars[a.name] = dv
		} else {
			return nil, fmt.Errorf("Macro `%s` is missing the argument `%s`", m.name, a.name)
		}
	}
	sub := &tRenderState{tera: st.tera, tplName: st.tplName, chain: []*tTemplate{tpl}, frames: []*tFrame{frame}, global: NewOMap(), macroNS: map[string]*tTemplate{}, curTpl: tpl}
	for _, im := range tpl.imports {
		if mt, ok := st.tera.templates[im.file]; ok {
			sub.macroNS[im.ns] = mt
		}
	}
	var b strings.Builder
	if err := sub.renderNodes(m.body, &b); err != nil && err != errBreak && err != errContinue {
		return nil, err
	}
	return b.String(), nil
}

// ---------- helpers ----------

func sortValues(arr []Value, key func(Value) (Value, error)) ([]Value, error) {
	out := append([]Value{}, arr...)
	keys := make([]Value, len(out))
	for i, v := range out {
		k, err := key(v)
		if err != nil {
			return nil, err
		}
		keys[i] = k
	}
	idx := make([]int, len(out))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		return compareValues(keys[idx[a]], keys[idx[b]]) < 0
	})
	res := make([]Value, len(out))
	for i, j := range idx {
		res[i] = out[j]
	}
	return res, nil
}

func compareValues(a, b Value) int {
	if fa, ok := toFloat(a); ok {
		if fb, ok2 := toFloat(b); ok2 {
			switch {
			case fa < fb:
				return -1
			case fa > fb:
				return 1
			}
			return 0
		}
	}
	switch x := a.(type) {
	case string:
		if y, ok := b.(string); ok {
			return strings.Compare(x, y)
		}
	case bool:
		if y, ok := b.(bool); ok {
			if x == y {
				return 0
			}
			if !x {
				return -1
			}
			return 1
		}
	case []Value:
		if y, ok := b.([]Value); ok {
			for i := 0; i < len(x) && i < len(y); i++ {
				if c := compareValues(x[i], y[i]); c != 0 {
					return c
				}
			}
			return len(x) - len(y)
		}
	}
	return 0
}
