func escapeHTMLTera(s string) string {
	var b strings.Builder
	for _, c := range s {
		switch c {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&#x27;")
		case '/':
			b.WriteString("&#x2F;")
		default:
			b.WriteRune(c)
		}
	}
	return b.String()
}

func escapeXML(s string) string {
	var b strings.Builder
	for _, c := range s {
		switch c {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		default:
			b.WriteRune(c)
		}
	}
	return b.String()
}

func percentEncode(s string, keep func(c byte) bool) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if keep(c) {
			b.WriteByte(c)
		} else {
			fmt.Fprintf(&b, "%%%02X", c)
		}
	}
	return b.String()
}

func urlencodeKeep(c byte) bool {
	if c < 0x20 || c >= 0x7f {
		return false
	}
	switch c {
	case ' ', '"', '<', '>', '`', '#', '?', '{', '}', ':', ';', '=', '@', '[', '\\', ']', '^', '|', ',':
		return false
	}
	return true
}

func urlencodeStrictKeep(c byte) bool {
	return isASCIIAlnum(c)
}

func rustTrim(s string) string {
	return strings.TrimFunc(s, unicode.IsSpace)
}

func trimStartMatches(s, pat string) string {
	if pat == "" {
		return s
	}
	for strings.HasPrefix(s, pat) {
		s = s[len(pat):]
	}
	return s
}

func trimEndMatches(s, pat string) string {
	if pat == "" {
		return s
	}
	for strings.HasSuffix(s, pat) {
		s = s[:len(s)-len(pat)]
	}
	return s
}

func dottedPointer(v Value, path string) (Value, bool) {
	if path == "" {
		return v, true
	}
	cur := v
	for _, part := range strings.Split(path, ".") {
		switch c := cur.(type) {
		case *OMap:
			nv, ok := c.Get(part)
			if !ok {
				return nil, false
			}
			cur = nv
		case []Value:
			i, err := strconv.Atoi(part)
			if err != nil || i < 0 || i >= len(c) {
				return nil, false
			}
			cur = c[i]
		default:
			return nil, false
		}
	}
	return cur, true
}

func getIndex(i float64, n int) int {
	if i >= 0 {
		return int(i)
	}
	r := int(float64(n) + i)
	if r < 0 {
		return 0
	}
	return r
}

