	ts["object"] = func(v Value, a []Value) (bool, error) { _, ok := v.(*OMap); return ok, nil }
	ts["iterable"] = func(v Value, a []Value) (bool, error) {
		switch v.(type) {
		case []Value, *OMap:
			return true, nil
