// slugify mimics the Rust `slug` crate.
func slugify(s string) string {
	var b []byte
	prevDash := true
	push := func(x byte) {
		switch {
		case (x >= 'a' && x <= 'z') || (x >= '0' && x <= '9'):
			prevDash = false
			b = append(b, x)
		case x >= 'A' && x <= 'Z':
			prevDash = false
			b = append(b, x-'A'+'a')
		default:
			if !prevDash {
				b = append(b, '-')
				prevDash = true
			}
		}
	}
	for _, r := range s {
		if r < 128 {
			push(byte(r))
		} else {
			for _, c := range []byte(deunicodeChar(r)) {
				push(c)
			}
		}
	}
	if len(b) > 0 && b[len(b)-1] == '-' {
		b = b[:len(b)-1]
	}
	return string(b)
