// ---- graphemes (approximation of extended grapheme clusters) ----

func isGraphemeExtend(r rune) bool {
	if r == 0x200D || (r >= 0xFE00 && r <= 0xFE0F) || (r >= 0x1F3FB && r <= 0x1F3FF) || (r >= 0xE0020 && r <= 0xE007F) {
		return true
	}
	return unicode.In(r, unicode.Mn, unicode.Me, unicode.Mc)
}

func isRegionalIndicator(r rune) bool { return r >= 0x1F1E6 && r <= 0x1F1FF }

// graphemeBoundaries returns byte offsets of the start of each grapheme.
func graphemeStarts(s string) []int {
	var starts []int
	i := 0
	var prev rune = -1
	riCount := 0
	for i < len(s) {
		r, size := utf8.DecodeRuneInString(s[i:])
		boundary := true
		if prev == -1 {
			boundary = true
		} else if prev == '\r' && r == '\n' {
			boundary = false
		} else if prev == '\r' || prev == '\n' || r == '\r' || r == '\n' {
			boundary = true
		} else if isGraphemeExtend(r) {
			boundary = false
		} else if prev == 0x200D && (unicode.Is(unicode.So, r) || r >= 0x1F000) {
			boundary = false
		} else if isRegionalIndicator(prev) && isRegionalIndicator(r) && riCount%2 == 1 {
			boundary = false
		} else if isHangulJoin(prev, r) {
			boundary = false
		}
		if isRegionalIndicator(r) {
			riCount++
		} else {
			riCount = 0
		}
		if boundary {
			starts = append(starts, i)
		}
		prev = r
		i += size
	}
	return starts
}

func hangulType(r rune) int {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0xA960 && r <= 0xA97C:
		return 1 // L
	case r >= 0x1160 && r <= 0x11A7, r >= 0xD7B0 && r <= 0xD7C6:
		return 2 // V
	case r >= 0x11A8 && r <= 0x11FF, r >= 0xD7CB && r <= 0xD7FB:
		return 3 // T
	case r >= 0xAC00 && r <= 0xD7A3:
		if (r-0xAC00)%28 == 0 {
			return 4 // LV
		}
		return 5 // LVT
	}
	return 0
}

func isHangulJoin(a, b rune) bool {
	ta, tb := hangulType(a), hangulType(b)
	if ta == 0 || tb == 0 {
		return false
	}
	switch ta {
	case 1:
		return tb == 1 || tb == 2 || tb == 4 || tb == 5
	case 2, 4:
		return tb == 2 || tb == 3
	case 3, 5:
