{"command":"cat > /workspace/yaml.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// A small YAML parser supporting the subset needed for configs and front matter.

type yamlLine struct {
	indent int
	text   string // content without indentation (comments not stripped)
	num    int
}

type yamlParser struct {
	lines []yamlLine
	pos   int
}

func parseYAML(src string) (Value, error) {
	src = strings.ReplaceAll(src, "\r\n", "\n")
	src = strings.TrimPrefix(src, "\ufeff")
	var lines []yamlLine
	for i, l := range strings.Split(src, "\n") {
		t := strings.TrimRight(l, " \t")
		ind := 0
		for ind < len(t) && t[ind] == ' ' {
			ind++
		}
		lines = append(lines, yamlLine{indent: ind, text: t[ind:], num: i + 1})
	}
	// strip document markers
	var filtered []yamlLine
	started := false
	for _, l := range lines {
		if l.indent == 0 && (l.text == "---" || strings.HasPrefix(l.text, "--- ")) {
			if started {
				break
			}
			started = true
			rest := strings.TrimSpace(strings.TrimPrefix(l.text, "---"))
			if rest != "" {
				filtered = append(filtered, yamlLine{indent: 0, text: rest, num: l.num})
			}
			continue
		}
		if l.indent == 0 && l.text == "..." {
			break
		}
		if l.indent == 0 && strings.HasPrefix(l.text, "%") && !started {
			continue
		}
		started = true
		filtered = append(filtered, l)
	}
	p := &yamlParser{lines: filtered}
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	v, err := p.parseNode(p.lines[p.pos].indent)
	if err != nil {
		return nil, err
	}
	p.skipBlank()
	if p.pos < len(p.lines) {
		return nil, fmt.Errorf("did not find expected key at line %d", p.lines[p.pos].num)
	}
	return v, nil
}

func isBlankOrComment(t string) bool {
	return t == "" || strings.HasPrefix(t, "#")
}

func (p *yamlParser) skipBlank() {
	for p.pos < len(p.lines) && isBlankOrComment(p.lines[p.pos].text) {
		p.pos++
	}
}

// stripComment removes a trailing comment from a plain line (outside quotes).
func stripComment(s string) string {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inS:
			if c == '\'' {
				inS = false
			}
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		case c == '\'' && (i == 0 || isYamlFlowStart(s[i-1])):
			inS = true
		case c == '"' && (i == 0 || isYamlFlowStart(s[i-1])):
			inD = true
		case c == '[' || c == '{':
			depth++
		case c == ']' || c == '}':
			depth--
		case c == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t'):
			return strings.TrimRight(s[:i], " \t")
		}
	}
	return s
}

func isYamlFlowStart(c byte) bool {
	return c == ' ' || c == '\t' || c == '[' || c == '{' || c == ',' || c == ':' || c == '-'
}

// findMappingColon finds the position of a key-separating ": " in s (outside quotes/flow), or -1.
func findMappingColon(s string) int {
	if strings.HasPrefix(s, "\"") || strings.HasPrefix(s, "'") {
		q := s[0]
		i := 1
		for i < len(s) {
			if q == '"' && s[i] == '\\' {
				i += 2
				continue
			}
			if s[i] == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			i++
		}
		j := i + 1
		for j < len(s) && s[j] == ' ' {
			j++
		}
		if j < len(s) && s[j] == ':' && (j+1 == len(s) || s[j+1] == ' ' || s[j+1] == '\t') {
			return j
		}
		return -1
	}
	if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "{") {
		return -1
	}
	for i := 0; i < len(s); i++ {
		if s[i] == ':' && (i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\t') {
			return i
		}
		if s[i] == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
			return -1
		}
	}
	return -1
}

func (p *yamlParser) parseNode(indent int) (Value, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	l := p.lines[p.pos]
	t := l.text
	if t == "-" || strings.HasPrefix(t, "- ") || strings.HasPrefix(t, "-\t") {
		return p.parseSeq(l.indent)
	}
	if findMappingColon(stripComment(t)) >= 0 {
		return p.parseMap(l.indent)
	}
	// scalar possibly multi-line
	return p.parseScalarLines(indent)
}

func (p *yamlParser) parseSeq(indent int) (Value, error) {
	arr := []Value{}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent != indent {
			if l.indent > indent {
				return nil, fmt.Errorf("bad indentation of a sequence entry at line %d", l.num)
			}
			break
		}
		t := l.text
		if !(t == "-" || strings.HasPrefix(t, "- ") || strings.HasPrefix(t, "-\t")) {
			break
		}
		rest := strings.TrimLeft(t[1:], " \t")
		if rest == "" || strings.HasPrefix(rest, "#") {
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				v, err := p.parseNode(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				arr = append(arr, v)
			} else {
				arr = append(arr, nil)
			}
			continue
		}
		// inline content: treat as a new node at virtual indent
		off := len(t) - len(rest)
		newIndent := indent + off
		p.lines[p.pos] = yamlLine{indent: newIndent, text: rest, num: l.num}
		v, err := p.parseNode(newIndent)
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
	}
	return arr, nil
}

func (p *yamlParser) parseMap(indent int) (Value, error) {
	m := NewOMap()
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent != indent {
			if l.indent > indent {
				return nil, fmt.Errorf("mapping values are not allowed in this context at line %d", l.num)
			}
			break
		}
		t := stripComment(l.text)
		ci := findMappingColon(t)
		if ci < 0 {
			if strings.HasPrefix(t, "- ") || t == "-" {
				break
			}
			return nil, fmt.Errorf("could not find expected ':' at line %d", l.num)
		}
		keyRaw := strings.TrimSpace(t[:ci])
		key := keyRaw
		if kv, err := parseYAMLScalar(keyRaw); err == nil {
			key = renderYAMLKey(kv)
		}
		rest := strings.TrimSpace(t[ci+1:])
		p.pos++
		if rest == "" {
			p.skipBlank()
			if p.pos < len(p.lines) {
				nl := p.lines[p.pos]
				isSeq := nl.text == "-" || strings.HasPrefix(nl.text, "- ")
				if nl.indent > indent || (nl.indent == indent && isSeq) {
					v, err := p.parseNode(nl.indent)
					if err != nil {
						return nil, err
					}
					m.Set(key, v)
					continue
				}
			}
			m.Set(key, nil)
			continue
		}
		if strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
			v := p.parseBlockScalar(rest, indent)
			m.Set(key, v)
			continue
		}
		// value may continue on following lines (multi-line plain or quoted, or flow)
		valText := strings.TrimSpace(l.text[strings.Index(l.text, ":")+1:])
		if ci2 := findMappingColon(l.text); ci2 >= 0 {
			valText = strings.TrimSpace(l.text[ci2+1:])
		}
		v, err := p.parseInlineValue(valText, indent)
		if err != nil {
			return nil, err
		}
		m.Set(key, v)
	}
	return m, nil
}

func renderYAMLKey(v Value) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		return x
	}
	return renderValue(v)
}

// parseInlineValue parses a value starting on the current line (already consumed) possibly continuing on more-indented lines.
func (p *yamlParser) parseInlineValue(first string, indent int) (Value, error) {
	text := first
	if strings.HasPrefix(text, "\"") || strings.HasPrefix(text, "'") {
		// quoted possibly multi-line
		for !quotedComplete(text) && p.pos < len(p.lines) {
			text += "\n" + strings.Repeat(" ", 0) + p.lines[p.pos].text
			p.pos++
		}
		end := quotedEnd(text)
		if end > 0 && end < len(text) {
			after := strings.TrimSpace(text[end:])
			if after != "" && !strings.HasPrefix(after, "#") {
				return nil, fmt.Errorf("did not find expected key")
			}
			text = text[:end]
		}
		return parseQuoted(text)
	}
	if strings.HasPrefix(text, "[") || strings.HasPrefix(text, "{") {
		text = stripComment(text)
		for !flowComplete(text) && p.pos < len(p.lines) {
			text += " " + stripComment(p.lines[p.pos].text)
			p.pos++
		}
		fp := &flowParser{s: text}
		v, err := fp.parse()
		return v, err
	}
	text = stripComment(text)
	// multi-line plain scalar
	for p.pos < len(p.lines) {
		nl := p.lines[p.pos]
		if nl.text == "" {
			// blank line inside plain scalar folds to newline if followed by continuation
			j := p.pos
			for j < len(p.lines) && p.lines[j].text == "" {
				j++
			}
			if j < len(p.lines) && p.lines[j].indent > indent && !strings.HasPrefix(p.lines[j].text, "#") {
				for k := p.pos; k < j; k++ {
					text += "\n"
				}
				p.pos = j
				text += strings.TrimSpace(stripComment(p.lines[p.pos].text))
				p.pos++
				continue
			}
			break
		}
		if nl.indent <= indent || strings.HasPrefix(nl.text, "#") {
			break
		}
		if strings.HasSuffix(text, "\n") {
			text += strings.TrimSpace(stripComment(nl.text))
		} else {
			text += " " + strings.TrimSpace(stripComment(nl.text))
		}
		p.pos++
	}
	return parseYAMLScalar(text)
}

func quotedEnd(s string) int {
	q := s[0]
	i := 1
	for i < len(s) {
		if q == '"' && s[i] == '\\' {
			i += 2
			continue
		}
		if s[i] == q {
			if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
				i += 2
				continue
			}
			return i + 1
		}
		i++
	}
	return -1
}

func quotedComplete(s string) bool { return quotedEnd(s) > 0 }

func flowComplete(s string) bool {
	depth := 0
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inS:
			if c == '\'' {
				inS = false
			}
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		case c == '\'':
			inS = true
		case c == '"':
			inD = true
		case c == '[' || c == '{':
			depth++
		case c == ']' || c == '}':
			depth--
		}
	}
	return depth <= 0
}

func (p *yamlParser) parseScalarLines(indent int) (Value, error) {
	l := p.lines[p.pos]
	p.pos++
	if strings.HasPrefix(l.text, "|") || strings.HasPrefix(l.text, ">") {
		return p.parseBlockScalar(l.text, indent-1), nil
	}
	return p.parseInlineValue(l.text, indent-1)
}

func (p *yamlParser) parseBlockScalar(header string, parentIndent int) Value {
	header = stripComment(header)
	style := header[0]
	chomp := byte(0)
	explicitIndent := 0
	for _, c := range header[1:] {
		switch {
		case c == '+' || c == '-':
			chomp = byte(c)
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		}
	}
	// collect lines
	var raw []yamlLine
	for p.pos < len(p.lines) {
		nl := p.lines[p.pos]
		if nl.text != "" && nl.indent <= parentIndent {
			break
		}
		raw = append(raw, nl)
		p.pos++
	}
	blockIndent := 0
	if explicitIndent > 0 {
		blockIndent = parentIndent + explicitIndent
		if parentIndent < 0 {
			blockIndent = explicitIndent
		}
	} else {
		for _, r := range raw {
			if r.text != "" {
				blockIndent = r.indent
				break
			}
		}
	}
	var lines []string
	for _, r := range raw {
		if r.text == "" {
			lines = append(lines, "")
			continue
		}
		extra := r.indent - blockIndent
		if extra < 0 {
			extra = 0
		}
		lines = append(lines, strings.Repeat(" ", extra)+r.text)
	}
	// trailing blank lines handling
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	var body string
	if style == '|' {
		body = strings.Join(lines, "\n")
	} else {
		var b strings.Builder
		prevMore := false
		for i, ln := range lines {
			more := strings.HasPrefix(ln, " ") || strings.HasPrefix(ln, "\t")
			if i > 0 {
				prev := lines[i-1]
				if prev == "" {
					// already handled by newline
				} else if ln == "" {
					b.WriteString("\n")
				} else if more || prevMore {
					b.WriteString("\n")
				} else {
					b.WriteString(" ")
				}
			}
			if ln == "" && i > 0 && lines[i-1] != "" {
				// first blank line after text: newline already written
			} else if ln == "" {
				b.WriteString("\n")
			}
			b.WriteString(ln)
			prevMore = more
		}
		body = b.String()
	}
	if len(lines) == 0 {
		if chomp == '+' {
			return strings.Repeat("\n", trailing)
		}
		return ""
	}
	switch chomp {
	case '-':
		return body
	case '+':
		return body + "\n" + strings.Repeat("\n", trailing)
	default:
		return body + "\n"
	}
}

var reYamlInt = regexp.MustCompile(`^[-+]?[0-9]+$`)
var reYamlOct = regexp.MustCompile(`^0o[0-7]+$`)
var reYamlHex = regexp.MustCompile(`^0x[0-9a-fA-F]+$`)
var reYamlFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)

func parseYAMLScalar(s string) (Value, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	if s[0] == '"' || s[0] == '\'' {
		return parseQuoted(s)
	}
	if s[0] == '[' || s[0] == '{' {
		fp := &flowParser{s: s}
		return fp.parse()
	}
	// strip tags like !!str
	if strings.HasPrefix(s, "!!str ") {
		return strings.TrimSpace(s[6:]), nil
	}
	if s[0] == '&' || s[0] == '*' || s[0] == '!' {
		// anchors/aliases/tags not supported: treat as string after token
		if sp := strings.IndexByte(s, ' '); sp > 0 && s[0] != '*' {
			return parseYAMLScalar(s[sp+1:])
		}
	}
	return resolvePlain(s), nil
}

func resolvePlain(s string) Value {
	switch s {
	case "~", "null", "Null", "NULL":
		return nil
	case "true", "True", "TRUE":
		return true
	case "false", "False", "FALSE":
		return false
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return math.Inf(1)
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1)
	case ".nan", ".NaN", ".NAN":
		return math.NaN()
	}
	if reYamlInt.MatchString(s) {
		if n, err := strconv.ParseInt(s, 10, 64); err == nil {
			return n
		}
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return f
		}
	}
	if reYamlHex.MatchString(s) {
		if n, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return n
		}
	}
	if reYamlOct.MatchString(s) {
		if n, err := strconv.ParseInt(s[2:], 8, 64); err == nil {
			return n
		}
	}
	if reYamlFloat.MatchString(s) {
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return f
		}
	}
	return s
}

func parseQuoted(s string) (Value, error) {
	if len(s) < 2 {
		return nil, fmt.Errorf("found unexpected end of stream")
	}
	q := s[0]
	if s[len(s)-1] != q {
		return nil, fmt.Errorf("found unexpected end of stream")
	}
	inner := s[1 : len(s)-1]
	// fold line breaks
	inner = foldQuotedLines(inner, q == '"')
	if q == '\'' {
		return strings.ReplaceAll(inner, "''", "'"), nil
	}
	var b strings.Builder
	for i := 0; i < len(inner); i++ {
		c := inner[i]
		if c != '\\' || i+1 >= len(inner) {
			b.WriteByte(c)
			continue
		}
		i++
		switch inner[i] {
		case 'n':
			b.WriteByte('\n')
		case 't', '\t':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case '0':
			b.WriteByte(0)
		case 'a':
			b.WriteByte(7)
		case 'b':
			b.WriteByte(8)
		case 'e':
			b.WriteByte(0x1b)
		case 'f':
			b.WriteByte(0xc)
		case 'v':
			b.WriteByte(0xb)
		case ' ':
			b.WriteByte(' ')
		case '"':
			b.WriteByte('"')
		case '/':
			b.WriteByte('/')
		case '\\':
			b.WriteByte('\\')
		case 'N':
			b.WriteString("\u0085")
		case '_':
			b.WriteString("\u00a0")
		case 'L':
			b.WriteString("\u2028")
		case 'P':
			b.WriteString("\u2029")
		case 'x', 'u', 'U':
			n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[inner[i]]
			if i+n < len(inner)+0 && i+1+n <= len(inner) {
				code, err := strconv.ParseUint(inner[i+1:i+1+n], 16, 32)
				if err == nil {
					b.WriteRune(rune(code))
					i += n
					continue
				}
			}
			return nil, fmt.Errorf("invalid escape")
		case '\n':
			// escaped line break: skip
		default:
			return nil, fmt.Errorf("found unknown escape character while parsing a quoted scalar")
		}
	}
	return b.String(), nil
}

func foldQuotedLines(s string, double bool) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	lines := strings.Split(s, "\n")
	var b strings.Builder
	for i, l := range lines {
		if i > 0 {
			l = strings.TrimLeft(l, " \t")
		}
		if i < len(lines)-1 {
			l = strings.TrimRight(l, " \t")
		}
		if i == 0 {
			b.WriteString(l)
			continue
		}
		if l == "" {
			b.WriteString("\n")
			continue
		}
		prev := lines[i-1]
		if strings.TrimSpace(prev) == "" && i > 1 {
			b.WriteString(l)
		} else if double && strings.HasSuffix(b.String(), "\\") {
			str := b.String()
			b.Reset()
			b.WriteString(str[:len(str)-1])
			b.WriteString(l)
		} else {
			b.WriteString(" ")
			b.WriteString(l)
		}
	}
	return b.String()
}

// ---- flow parser ----

type flowParser struct {
	s   string
	pos int
}

func (f *flowParser) skipWS() {
	for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t' || f.s[f.pos] == '\n') {
		f.pos++
	}
}

func (f *flowParser) parse() (Value, error) {
	f.skipWS()
	v, err := f.parseValue()
	if err != nil {
		return nil, err
	}
	f.skipWS()
	if f.pos < len(f.s) {
		rest := strings.TrimSpace(f.s[f.pos:])
		if rest != "" && !strings.HasPrefix(rest, "#") {
			return nil, fmt.Errorf("did not find expected <document end>")
		}
	}
	return v, nil
}

func (f *flowParser) parseValue() (Value, error) {
	f.skipWS()
	if f.pos >= len(f.s) {
		return nil, nil
	}
	c := f.s[f.pos]
	switch c {
	case '[':
		f.pos++
		arr := []Value{}
		for {
			f.skipWS()
			if f.pos >= len(f.s) {
				return nil, fmt.Errorf("did not find expected ',' or ']'")
			}
			if f.s[f.pos] == ']' {
				f.pos++
				return arr, nil
			}
			v, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			f.skipWS()
			// single-pair mapping inside sequence
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				vv, err := f.parseValue()
				if err != nil {
					return nil, err
				}
				m := NewOMap()
				m.Set(renderYAMLKey(v), vv)
				v = m
				f.skipWS()
			}
			arr = append(arr, v)
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
			}
		}
	case '{':
		f.pos++
		m := NewOMap()
		for {
			f.skipWS()
			if f.pos >= len(f.s) {
				return nil, fmt.Errorf("did not find expected ',' or '}'")
			}
			if f.s[f.pos] == '}' {
				f.pos++
				return m, nil
			}
			k, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			f.skipWS()
			var v Value
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				v, err = f.parseValue()
				if err != nil {
					return nil, err
				}
			}
			m.Set(renderYAMLKey(k), v)
			f.skipWS()
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
			}
		}
	case '"', '\'':
		end := quotedEnd(f.s[f.pos:])
		if end < 0 {
			return nil, fmt.Errorf("found unexpected end of stream")
		}
		v, err := parseQuoted(f.s[f.pos : f.pos+end])
		f.pos += end
		return v, err
	}
	// plain scalar in flow context: until , ] } or ": "
	start := f.pos
	for f.pos < len(f.s) {
		ch := f.s[f.pos]
		if ch == ',' || ch == ']' || ch == '}' {
			break
		}
		if ch == ':' && (f.pos+1 >= len(f.s) || f.s[f.pos+1] == ' ' || f.s[f.pos+1] == ',' || f.s[f.pos+1] == ']' || f.s[f.pos+1] == '}') {
			break
		}
		if ch == '#' && f.pos > 0 && f.s[f.pos-1] == ' ' {
			break
		}
		f.pos++
	}
	return resolvePlain(strings.TrimSpace(f.s[start:f.pos])), nil
}
