// splitFrontmatter separates front matter from the markdown body.
// Returns parsed front matter map (may be nil), the body, and error.
func splitFrontmatter(src string) (*OMap, string, error) {
	s := strings.ReplaceAll(src, "\r\n", "\n")
	trimmed := strings.TrimLeft(s, " \t\n")
	if strings.HasPrefix(trimmed, "---") {
		rest := trimmed[3:]
		nl := strings.IndexByte(rest, '\n')
		if nl >= 0 && strings.TrimSpace(rest[:nl]) == "" {
			body := rest[nl+1:]
			// find closing delimiter line
			idx := findDelimLine(body, "---")
			if idx >= 0 {
				fmText := body[:idx]
				after := body[idx+3:]
				if i := strings.IndexByte(after, '\n'); i >= 0 {
					after = after[i+1:]
				} else {
					after = ""
				}
				v, err := parseYAML(fmText)
				if err != nil {
					return nil, s, err
				}
				m, _ := v.(*OMap)
				if m == nil {
					m = NewOMap()
				}
				return m, after, nil
			}
		}
	}
	if strings.HasPrefix(trimmed, "+++") {
		rest := trimmed[3:]
		nl := strings.IndexByte(rest, '\n')
		if nl >= 0 && strings.TrimSpace(rest[:nl]) == "" {
			body := rest[nl+1:]
			idx := findDelimLine(body, "+++")
			if idx >= 0 {
				fmText := body[:idx]
				after := body[idx+3:]
				if i := strings.IndexByte(after, '\n'); i >= 0 {
