		end := strings.Index(s[1:], "'")
		if end < 0 {
			return nil, fmt.Errorf("bad string")
		}
		return s[1 : 1+end], nil
	}
	if strings.HasPrefix(s, "[") {
		fp := &flowParser{s: s}
		return fp.parse()
	}
	if strings.HasPrefix(s, "{") {
		fp := &flowParser{s: strings.ReplaceAll(s, "=", ":")}
		return fp.parse()
	}
	if i := strings.Index(s, " #"); i >= 0 {
		s = strings.TrimSpace(s[:i])
	}
