// ----- YAML serialization (serde_yaml style) -----

func yamlNeedsQuote(s string) bool {
	if s == "" {
		return true
	}
	switch strings.ToLower(s) {
	case "null", "~", "true", "false", "yes", "no", "on", "off", "y", "n":
		return true
	}
	if reYamlInt.MatchString(s) || reYamlFloat.MatchString(s) || reYamlHex.MatchString(s) || reYamlOct.MatchString(s) {
		return true
	}
	if strings.HasPrefix(s, ".") && (strings.EqualFold(s, ".inf") || strings.EqualFold(s, ".nan")) {
		return true
	}
	first := s[0]
	if strings.IndexByte("-?:,[]{}#&*!|>'\"%@`", first) >= 0 {
		if !(first == '-' && len(s) > 1 && s[1] != ' ' && false) {
			return true
		}
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		return true
	}
	if strings.Contains(s, ": ") || strings.Contains(s, " #") || strings.HasSuffix(s, ":") {
		return true
	}
	for _, r := range s {
		if r < 0x20 && r != '\t' {
			return true
		}
	}
	return false
}

func yamlScalar(s string) string {
	if strings.Contains(s, "\n") {
		return jsonEscapeString(s)
	}
	if yamlNeedsQuote(s) {
		return "'" + strings.ReplaceAll(s, "'", "''") + "'"
	}
	return s
}

func yamlValue(v Value, indent string) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return jsonFloat(x)
	case string:
		return yamlScalar(x)
	}
	return ""
}

func writeYAML(b *strings.Builder, v Value, indent string, inSeq bool) {
	switch x := v.(type) {
	case []Value:
		if len(x) == 0 {
			b.WriteString(" []\n")
			return
		}
		b.WriteString("\n")
		for _, e := range x {
			b.WriteString(indent + "-")
			writeYAMLSeqItem(b, e, indent+"  ")
		}
	case *OMap:
		if x.Len() == 0 {
			b.WriteString(" {}\n")
			return
		}
		b.WriteString("\n")
		for _, k := range x.Keys() {
			b.WriteString(indent + yamlScalar(k) + ":")
			writeYAML(b, x.m[k], indent+"  ", false)
		}
	default:
		b.WriteString(" " + yamlValue(v, indent) + "\n")
	}
}

func writeYAMLSeqItem(b *strings.Builder, v Value, indent string) {
	switch x := v.(type) {
	case []Value:
		if len(x) == 0 {
			b.WriteString(" []\n")
			return
		}
		for i, e := range x {
			if i == 0 {
				b.WriteString(" -")
			} else {
				b.WriteString(indent + "-")
			}
			writeYAMLSeqItem(b, e, indent+"  ")
		}
	case *OMap:
		if x.Len() == 0 {
			b.WriteString(" {}\n")
			return
		}
		for i, k := range x.Keys() {
			if i == 0 {
				b.WriteString(" " + yamlScalar(k) + ":")
			} else {
				b.WriteString(indent + yamlScalar(k) + ":")
			}
			writeYAML(b, x.m[k], indent+"  ", false)
		}
	default:
		b.WriteString(" " + yamlValue(v, indent) + "\n")
	}
}

func configToYAML(c *Config) string {
	m := c.ToValue()
	var b strings.Builder
	for _, k := range m.Keys() {
		b.WriteString(k + ":")
		writeYAML(&b, m.m[k], "", false)
	}
	return b.String()
}

func sortedKeys(m map[string]bool) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func fileExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func isDir(p string) bool {
	st, err := os.Stat(p)
	return err == nil && st.IsDir()
}
