// walkFiles walks a directory tree in readdir order (like walkdir).
func walkFiles(root string, skip func(path string, isDir bool) bool, fn func(path string)) {
	f, err := os.Open(root)
	if err != nil {
		return
	}
	names, err := f.Readdirnames(-1)
	f.Close()
	if err != nil {
		return
	}
	for _, name := range names {
		p := filepath.Join(root, name)
		if root == "." {
			p = "./" + name
		} else {
			p = root + "/" + name
		}
		st, err := os.Stat(p)
		if err != nil {
			continue
		}
		if skip != nil && skip(p, st.IsDir()) {
			continue
		}
		if st.IsDir() {
			fn(p)
			walkFiles(p, skip, fn)
		} else {
			fn(p)
		}
	}
}

func (s *Site) loadFragments() {
	s.fragments = map[string]string{}
	for _, n := range fragmentNames {
		p := s.contentDir + "/_" + n + ".md"
