	if sv, ok := fm.Get("stream"); ok {
		if ss, ok := sv.(string); ok {
			c.Stream = ss
		} else if sv != nil {
			c.Stream = fmPlain(sv)
		}
	} else if streamFromFile != "" {
		c.Stream = streamFromFile
	}
	if c.Stream == nil && c.Date != nil {
		c.Stream = "index"
	}
	// slug
	if sv, ok := fm.Get("slug"); ok {
		c.Slug = slugify(fmPlain(sv))
	} else if tv, ok := fm.Get("title"); ok {
		c.Slug = slugify(fmPlain(tv))
	} else {
		c.Slug = slugFromFilename(stem, streamFromFile != "")
	}
	if st, ok := c.Stream.(string); ok && st != "index" {
		c.Slug = st + "-" + c.Slug
	}
	// tags
	if tv, ok := fm.Get("tags"); ok {
		c.Tags = fmStringList(tv)
	}
	if c.Tags == nil {
		c.Tags = []string{}
	}
	// authors
	if av, ok := fm.Get("authors"); ok {
		c.Authors = fmStringList(av)
	} else if av, ok := fm.Get("author"); ok {
		c.Authors = fmStringList(av)
	}
	if len(c.Authors) == 0 && s.cfg.DefaultAuthor != "" && c.Date != nil {
		c.Authors = []string{s.cfg.DefaultAuthor}
	}
	if c.Authors == nil {
		c.Authors = []string{}
	}
	// series
	if sv, ok := fm.Get("series"); ok {
		if ss, ok := sv.(string); ok {
			c.Series = ss
		} else if sv != nil {
			c.Series = fmPlain(sv)
		}
	}
	if pv, ok := fm.Get("pinned"); ok {
		if pb, ok := pv.(bool); ok {
			c.Pinned = pb
		}
	}
	if ev, ok := fm.Get("extra"); ok {
		c.Extra = ev
	}
	if cv, ok := fm.Get("comments"); ok {
		c.Comments = cv
	}
	if bv, ok := fm.Get("banner_image"); ok {
		c.BannerImage = fmPlain(bv)
	}
	c.ModifiedTime = fileModTime(path)
	// markdown assembly
	body2 = normalizeBody(body2)
	c.Markdown = body
	md := s.fragments["markdown_header"] + "\n\n" + body2 + "\n" + s.fragments["markdown_footer"] + "\n\n" + s.fragments["references"]
	html := s.renderMarkdown(md)
	html, links := fixInternalLinks(html)
	c.HTML = html
	if len(links) > 0 {
