type Group struct {
	kind string
	keys []string
	m    map[string][]*Content
}

func newGroup(kind string) *Group {
	return &Group{kind: kind, m: map[string][]*Content{}}
}

func (g *Group) add(key string, c *Content) {
	if _, ok := g.m[key]; !ok {
		g.keys = append(g.keys, key)
	}
	for _, e := range g.m[key] {
		if e == c {
			return
		}
	}
	g.m[key] = append(g.m[key], c)
}

func dateLess(a, b *Content) bool {
	// a newer than b
	if a.Date == nil || b.Date == nil {
		return a.Date != nil && b.Date == nil
	}
	return a.Date.After(*b.Date)
}

func sortByDateDesc(list []*Content) {
	sort.SliceStable(list, func(i, j int) bool { return dateLess(list[i], list[j]) })
}

func sortByDateAsc(list []*Content) {
	sort.SliceStable(list, func(i, j int) bool {
		a, b := list[i], list[j]
		if a.Date == nil || b.Date == nil {
			return false
		}
		return a.Date.Before(*b.Date)
	})
}

func pinnedFirst(list []*Content) []*Content {
	out := append([]*Content{}, list...)
	sort.SliceStable(out, func(i, j int) bool { return out[i].Pinned && !out[j].Pinned })
	return out
}

func (g *Group) sortAll() {
	for _, k := range g.keys {
		if g.kind == "series" {
			sortByDateAsc(g.m[k])
		} else {
			sortByDateDesc(g.m[k])
		}
	}
}

// orderedKeys returns group keys in the order used by the `group` function.
func (g *Group) orderedKeys() []string {
	keys := append([]string{}, g.keys...)
	switch g.kind {
	case "tag":
		sort.SliceStable(keys, func(i, j int) bool { return len(g.m[keys[i]]) > len(g.m[keys[j]]) })
	case "archive":
		sort.SliceStable(keys, func(i, j int) bool { return keys[i] > keys[j] })
	default:
		sort.Strings(keys)
		sort.SliceStable(keys, func(i, j int) bool { return len(g.m[keys[i]]) > len(g.m[keys[j]]) })
	}
	return keys
}

// urlKeys returns keys in the order used for generated urls.
func (g *Group) urlKeys() []string {
	keys := append([]string{}, g.keys...)
	switch g.kind {
	case "tag":
		sort.SliceStable(keys, func(i, j int) bool { return len(g.m[keys[i]]) > len(g.m[keys[j]]) })
	case "archive":
		sort.SliceStable(keys, func(i, j int) bool { return keys[i] > keys[j] })
	default:
		sort.Strings(keys)
	}
	return keys
}

type Site struct {
	cfg          *Config
	cli          *CLI
