var fragmentNames = []string{"announce", "header", "footer", "htmlhead", "htmltail", "hero", "sidebar", "comments", "404", "references", "markdown_header", "markdown_footer"}

// walkFiles walks a directory tree in readdir order (like walkdir).
func walkFiles(root string, skip func(path string, isDir bool) bool, fn func(path string)) {
	f, err := os.Open(root)
	if err != nil {
		return
	}
	names, err := f.Readdirnames(-1)
	f.Close()
	if err != nil {
		return
	}
	for _, name := range names {
		p := filepath.Join(root, name)
		if root == "." {
			p = "./" + name
		} else {
			p = root + "/" + name
		}
		st, err := os.Stat(p)
		if err != nil {
			continue
		}
		if skip != nil && skip(p, st.IsDir()) {
			continue
		}
		if st.IsDir() {
			fn(p)
			walkFiles(p, skip, fn)
		} else {
			fn(p)
		}
	}
}

func (s *Site) loadFragments() {
	s.fragments = map[string]string{}
	for _, n := range fragmentNames {
		p := s.contentDir + "/_" + n + ".md"
		if b, err := os.ReadFile(p); err == nil {
			s.fragments[n] = string(b)
		}
	}
}

func (s *Site) brokenLinkCallback() func(string) {
	return func(label string) {
		logWarn("marmite::parser", fmt.Sprintf("Reference missing: [%s] - add '[%s]: url' to the end of your content file or to the '_references.md' file.", label, label))
	}
}

func (s *Site) renderMarkdown(md string) string {
	return markdownToHTML(md, s.brokenLinkCallback())
}

// parseContentFile parses one markdown file into a Content.
func (s *Site) parseContentFile(path string) (*Content, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	raw := string(b)
	fm, body, ferr := splitFrontmatter(raw)
	if ferr != nil {
		return nil, ferr
	}
	if fm == nil {
		fm = NewOMap()
	}
	c := &Content{SourcePath: path, SourceFile: path}
	title, body2 := extractTitle(fm, body)
	c.Title = title
	// description
	if d, ok := fm.Get("description"); ok {
		c.Description = fmDisplay(d)
	}
	stem := stemOf(path)
	// date
	var streamFromFile string
	if dv, ok := fm.Get("date"); ok {
		if ds, ok := dv.(string); ok {
			t, err := tryParseDate(ds)
			if err != nil {
				logError("marmite::content", fmt.Sprintf("ERROR: Invalid date format %s when parsing %s, %s", ds, path, err.Error()))
				os.Exit(1)
			}
			c.Date = &t
		}
		_, streamFromFile = dateFromFilename(stem)
	} else {
		c.Date, streamFromFile = dateFromFilename(stem)
	}
	// stream
	if sv, ok := fm.Get("stream"); ok {
		if ss, ok := sv.(string); ok {
			c.Stream = ss
		} else if sv != nil {
			c.Stream = fmPlain(sv)
		}
	} else if streamFromFile != "" {
		c.Stream = streamFromFile
	}
	if c.Stream == nil && c.Date != nil {
		c.Stream = "index"
	}
	// slug
	if sv, ok := fm.Get("slug"); ok {
		c.Slug = slugify(fmPlain(sv))
	} else if tv, ok := fm.Get("title"); ok {
		c.Slug = slugify(fmPlain(tv))
	} else {
		c.Slug = slugFromFilename(stem, streamFromFile != "")
	}
	if st, ok := c.Stream.(string); ok && st != "index" {
		c.Slug = st + "-" + c.Slug
	}
	// tags
	if tv, ok := fm.Get("tags"); ok {
		c.Tags = fmStringList(tv)
	}
	if c.Tags == nil {
		c.Tags = []string{}
	}
	// authors
	if av, ok := fm.Get("authors"); ok {
		c.Authors = fmStringList(av)
	} else if av, ok := fm.Get("author"); ok {
		c.Authors = fmStringList(av)
	}
	if len(c.Authors) == 0 && s.cfg.DefaultAuthor != "" && c.Date != nil {
		c.Authors = []string{s.cfg.DefaultAuthor}
	}
	if c.Authors == nil {
		c.Authors = []string{}
	}
	// series
	if sv, ok := fm.Get("series"); ok {
		if ss, ok := sv.(string); ok {
			c.Series = ss
		} else if sv != nil {
			c.Series = fmPlain(sv)
		}
	}
	if pv, ok := fm.Get("pinned"); ok {
		if pb, ok := pv.(bool); ok {
			c.Pinned = pb
		}
	}
	if ev, ok := fm.Get("extra"); ok {
		c.Extra = ev
	}
	if cv, ok := fm.Get("comments"); ok {
		c.Comments = cv
	}
	if bv, ok := fm.Get("banner_image"); ok {
		c.BannerImage = fmPlain(bv)
	}
	c.ModifiedTime = fileModTime(path)
	// markdown assembly
	body2 = normalizeBody(body2)
	c.Markdown = body
	md := s.fragments["markdown_header"] + "\n\n" + body2 + "\n" + s.fragments["markdown_footer"] + "\n\n" + s.fragments["references"]
	html := s.renderMarkdown(md)
	html, links := fixInternalLinks(html)
	c.HTML = html
	if len(links) > 0 {
		c.LinksTo = links
		c.hasLinksTo = true
	}
	// card image
	if cv, ok := fm.Get("card_image"); ok {
		c.CardImage = fmDisplay(cv)
	} else if img := firstImageSrc(html); img != "" {
		c.CardImage = img
	}
	// toc
	tocEnabled := s.cfg.Toc
	if tv, ok := fm.Get("toc"); ok {
		if tb, ok := tv.(bool); ok {
			tocEnabled = tb
		}
	}
	if tocEnabled {
		c.Toc = generateTOC(html)
	}
	return c, nil
}

var reImgSrc = regexp.MustCompile(`<img[^>]*\ssrc="([^"]+)"`)

func firstImageSrc(html string) string {
	m := reImgSrc.FindStringSubmatch(html)
	if m != nil {
		return m[1]
	}
	return ""
}

var reTOCHeading = regexp.MustCompile(`<h([1-6])><a href="#([^"]*)" aria-hidden="true" class="anchor" id="[^"]*"></a>(.*?)</h[1-6]>`)

func generateTOC(html string) string {
	var b strings.Builder
	b.WriteString("<ul>\n")
	level := 1
	for _, m := range reTOCHeading.FindAllStringSubmatch(html, -1) {
		l := int(m[1][0] - '0')
		for level < l {
			b.WriteString("<ul>\n")
			level++
		}
		for level > l {
			b.WriteString("</ul>\n")
			level--
		}
		b.WriteString("<li><a href=\"#" + m[2] + "\">" + m[3] + "</a></li>\n")
	}
	for level > 1 {
		b.WriteString("</ul>\n")
		level--
	}
	b.WriteString("</ul>\n")
	return b.String()
}

// ---------- internal link fixing ----------

var reAnchorHref = regexp.MustCompile(`<a\s+((?:[^>]*?\s)?)href="([^"]*)"`)
var reWikiAnchor = regexp.MustCompile(`(<a href="[^"]*" data-wikilink="true">)([^<]*)(</a>)`)

var keepExtensions = []string{".pdf", ".png", ".jpg", ".jpeg", ".gif", ".svg", ".webp", ".ico", ".avif", ".bmp", ".tiff", ".tif", ".mp3", ".mp4", ".wav", ".ogg", ".webm", ".mov", ".avi", ".mkv", ".flac", ".zip", ".tar", ".gz", ".rar", ".7z", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".txt", ".csv", ".json", ".xml", ".yaml", ".yml", ".toml", ".html"}

func fixHref(href string) (string, bool) {
	if strings.HasPrefix(href, ".") || strings.Contains(href, ":") {
		return href, false
	}
	lower := strings.ToLower(href)
	for _, e := range keepExtensions {
		if strings.HasSuffix(lower, e) && !(e == ".html" && false) {
			if e == ".html" {
				break
			}
			return href, false
		}
	}
	path := href
	frag := ""
	hasFrag := false
	if i := strings.IndexByte(path, '#'); i >= 0 {
		frag = path[i+1:]
		path = path[:i]
		hasFrag = true
	}
	if i := strings.IndexByte(path, '?'); i >= 0 {
		path = path[:i]
	}
	if path == "" {
		if hasFrag && frag != "" {
			return href, false
		}
		return "", false
	}
	if strings.HasSuffix(path, ".md") {
		path = strings.TrimSuffix(path, ".md")
	} else if strings.HasSuffix(path, ".html") {
		path = strings.TrimSuffix(path, ".html")
	}
	slug := slugify(path)
	if slug == "" {
		if hasFrag && frag != "" {
			return "#" + slugify(frag), false
		}
		return "", false
	}
	res := slug + ".html"
	link := slug
	if hasFrag && frag != "" {
		res += "#" + slugify(frag)
		link += "#" + slugify(frag)
	}
	return res, true
}

func fixInternalLinks(html string) (string, []string) {
	var links []string
	out := reAnchorHref.ReplaceAllStringFunc(html, func(m string) string {
		sm := reAnchorHref.FindStringSubmatch(m)
		pre := sm[1]
		href := sm[2]
		fixed, internal := fixHref(href)
		if internal {
			l := strings.Replace(fixed, ".html", "", 1)
			links = append(links, l)
		}
		ws := m[2 : len(m)-len(pre)-len(`href="`)-len(href)-1]
		return "<a" + ws + pre + `href="` + fixed + `"`
	})
	out = reWikiAnchor.ReplaceAllStringFunc(out, func(m string) string {
		sm := reWikiAnchor.FindStringSubmatch(m)
		text := sm[2]
		if i := strings.IndexByte(text, '#'); i >= 0 {
			before, after := text[:i], text[i+1:]
			if before == "" {
				text = after
			} else {
				text = before + " > " + after
			}
		} else if strings.HasSuffix(text, ".html") {
			text = strings.TrimSuffix(text, ".html")
		} else if strings.HasSuffix(text, ".md") {
			text = strings.TrimSuffix(text, ".md")
		}
		return sm[1] + text + sm[3]
	})
	return out, links
}

// resolveWikilinks updates wikilink hrefs whose text matches a content title.
func (s *Site) resolveWikilinks(html string) string {
	return reWikiLinkFull.ReplaceAllStringFunc(html, func(m string) string {
		sm := reWikiLinkFull.FindStringSubmatch(m)
		text := sm[3]
		lt := strings.ToLower(text)
		for _, c := range s.all {
			if strings.ToLower(c.Title) == lt {
				return sm[1] + c.Slug + ".html" + sm[2] + text + sm[4]
			}
		}
		return m
	})
}

var reWikiLinkFull = regexp.MustCompile(`(<a href=")[^"]*(" data-wikilink="true">)([^<]*)(</a>)`)

// ---------- helpers ----------

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
		return err
	}
	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()
	_, err = io.Copy(out, in)
	return err
}

func copyDir(src, dst string) error {
	return filepath.Walk(src, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(src, p)
		target := filepath.Join(dst, rel)
		if info.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		return copyFile(p, target)
	})
}

func writeFile(path, content string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(content), 0o644)
}
