func jaro(a, b string) float64 {
	ar, br := []rune(a), []rune(b)
	if len(ar) == 0 && len(br) == 0 {
		return 1
	}
	if len(ar) == 0 || len(br) == 0 {
		return 0
	}
	matchDist := len(ar)
	if len(br) > matchDist {
		matchDist = len(br)
	}
	matchDist = matchDist/2 - 1
	if matchDist < 0 {
		matchDist = 0
	}
	aM := make([]bool, len(ar))
	bM := make([]bool, len(br))
	matches := 0
	for i := range ar {
		lo := i - matchDist
		if lo < 0 {
			lo = 0
		}
		hi := i + matchDist + 1
		if hi > len(br) {
			hi = len(br)
		}
		for j := lo; j < hi; j++ {
			if bM[j] || ar[i] != br[j] {
				continue
			}
			aM[i], bM[j] = true, true
			matches++
			break
		}
	}
	if matches == 0 {
		return 0
	}
	t := 0
	k := 0
	for i := range ar {
		if !aM[i] {
			continue
		}
