func parseCLI(args []string) *CLI {
	c := &CLI{Flags: map[string]bool{}, Values: map[string]string{}}
	var used []*argSpec
	usedSet := map[*argSpec]bool{}
	var positionals []string
	helpReq, versionReq := false, false
	markUsed := func(s *argSpec) {
		if usedSet[s] && !s.count {
			clapError(fmt.Sprintf("the argument '%s' cannot be used multiple times", specDisplay(s)), usageLine(nil, nil))
		}
		if !usedSet[s] {
			used = append(used, s)
		}
		usedSet[s] = true
	}
	isNewArg := func(a string) bool {
		return strings.HasPrefix(a, "-") && a != "-"
	}
	setValue := func(s *argSpec, val string) {
		name := specName(s)
		if s.isBool {
			if val != "true" && val != "false" {
				msg := fmt.Sprintf("invalid value '%s' for '%s'\n  [possible values: true, false]", val, specDisplay(s))
				if strings.EqualFold(val, "true") || strings.EqualFold(val, "false") {
					msg += fmt.Sprintf("\n\n  tip: a similar value exists: '%s'", strings.ToLower(val))
				} else if jaro(val, "true") > 0.7 {
					msg += "\n\n  tip: a similar value exists: 'true'"
				} else if jaro(val, "false") > 0.7 {
					msg += "\n\n  tip: a similar value exists: 'false'"
				}
				clapError(msg, "")
			}
		}
		if s.isUsize {
			if val == "" {
				clapError(fmt.Sprintf("invalid value '%s' for '%s': cannot parse integer from empty string", val, specDisplay(s)), "")
			}
			for _, ch := range val {
				if ch < '0' || ch > '9' {
					if ch == '+' && strings.HasPrefix(val, "+") && len(val) > 1 {
						continue
					}
					clapError(fmt.Sprintf("invalid value '%s' for '%s': invalid digit found in string", val, specDisplay(s)), "")
				}
			}
			if _, err := strconv.ParseUint(strings.TrimPrefix(val, "+"), 10, 64); err != nil {
				clapError(fmt.Sprintf("invalid value '%s' for '%s': number too large to fit in target type", val, specDisplay(s)), "")
			}
		}
		c.Values[name] = val
	}
	missingValue := func(s *argSpec) {
		msg := fmt.Sprintf("a value is required for '%s' but none was supplied", specDisplay(s))
		if s.isBool {
			msg += "\n  [possible values: true, false]"
		}
		clapError(msg, "")
	}
	unexpected := func(a string) {
		clapError(fmt.Sprintf("unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'", a, a, a), usageLine(nil, nil))
	}
	i := 0
	trailing := false
	for i < len(args) {
		a := args[i]
		i++
		if trailing {
			positionals = append(positionals, a)
			continue
		}
		if a == "--" {
			trailing = true
			continue
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			val := ""
			hasEq := false
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				hasEq = true
			}
			var spec *argSpec
			for k := range argSpecs {
				if argSpecs[k].long == name && name != "" {
					spec = &argSpecs[k]
					break
				}
			}
			if spec == nil {
				if sim := findSimilar(name); sim != nil {
					clapError(fmt.Sprintf("unexpected argument '%s' found\n\n  tip: a similar argument exists: '--%s'", "--"+name, sim.long), usageLine(append(append([]*argSpec{}, used...)), sim))
				}
				unexpected("--" + name)
			}
			if spec.long == "help" {
				helpReq = true
				continue
			}
			if spec.long == "version" {
				versionReq = true
				continue
			}
			if spec.value == "" {
				if hasEq {
					markUsed(spec)
					clapError(fmt.Sprintf("unexpected value '%s' for '--%s' found; no more were expected", val, spec.long), usageLine(used, nil))
				}
				markUsed(spec)
				if spec.count {
					c.Verbose++
				} else {
					c.Flags[specName(spec)] = true
				}
				continue
			}
			markUsed(spec)
			if hasEq {
				if val == "" && !spec.isUsize {
					missingValue(spec)
				}
				setValue(spec, val)
				continue
			}
			if i >= len(args) {
				missingValue(spec)
			}
			next := args[i]
			if isNewArg(next) {
				// check whether next is a known arg
				checkKnown(next, unexpected)
				missingValue(spec)
			}
			i++
			setValue(spec, next)
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			shorts := a[1:]
			for j := 0; j < len(shorts); j++ {
				ch := shorts[j]
				var spec *argSpec
				for k := range argSpecs {
					if argSpecs[k].short == ch && ch != 0 {
						spec = &argSpecs[k]
						break
					}
				}
				if spec == nil {
					unexpected("-" + string(ch))
				}
				if spec.long == "help" {
					helpReq = true
					continue
				}
				if spec.long == "version" {
					versionReq = true
					continue
				}
				if spec.value == "" {
					markUsed(spec)
					if spec.count {
						c.Verbose++
					} else {
						c.Flags[specName(spec)] = true
					}
					continue
				}
				markUsed(spec)
				rest := shorts[j+1:]
				if rest != "" {
					rest = strings.TrimPrefix(rest, "=")
					setValue(spec, rest)
					break
				}
				if i >= len(args) {
					missingValue(spec)
				}
				next := args[i]
				if isNewArg(next) {
					checkKnown(next, unexpected)
					missingValue(spec)
				}
				i++
				setValue(spec, next)
				break
			}
			continue
		}
		positionals = append(positionals, a)
	}
	if helpReq {
		fmt.Print(strings.ReplaceAll(helpText, "Usage: executable ", "Usage: "+binName()+" "))
		os.Exit(0)
	}
	if versionReq {
		fmt.Println("marmite " + versionString)
		os.Exit(0)
	}
	if len(positionals) > 2 {
		clapError(fmt.Sprintf("unexpected argument '%s' found", positionals[2]), usageLine(nil, nil))
	}
	var missing []string
	needNew := false
	for _, u := range used {
		if u.requires == "new" && !usedSet[&argSpecs[13]] {
			needNew = true
		}
	}
	if needNew {
		missing = append(missing, "--new <NEW>")
	}
	if len(positionals) < 1 {
		missing = append(missing, "<INPUT_FOLDER>")
	}
	if len(missing) > 0 {
		var extra *argSpec
		if needNew {
			extra = &argSpecs[13]
		}
		msg := "the following required arguments were not provided:\n  " + strings.Join(missing, "\n  ")
		clapError(msg, usageLine(used, extra))
	}
	c.Input = positionals[0]
	if len(positionals) > 1 {
		c.Output = positionals[1]
		c.HasOut = true
	}
	return c
}

func checkKnown(a string, unexpected func(string)) {
	if strings.HasPrefix(a, "--") {
		name := a[2:]
		if eq := strings.IndexByte(name, '='); eq >= 0 {
			name = name[:eq]
		}
		for k := range argSpecs {
			if argSpecs[k].long == name && name != "" {
				return
			}
		}
		unexpected(a)
	}
	ch := a[1]
	for k := range argSpecs {
		if argSpecs[k].short == ch {
			return
		}
	}
	unexpected("-" + string(ch))
}
