	}
	str("footer", &c.Footer)
	str("language", &c.Language)
	if v, ok := cli.Str("pagination"); ok {
		var n int64
		fmt.Sscanf(strings.TrimPrefix(v, "+"), "%d", &n)
		c.Pagination = n
	}
	bl("enable-search", &c.EnableSearch)
	bl("enable-related-content", &c.EnableRelatedContent)
	str("content-path", &c.ContentPath)
	str("templates-path", &c.TemplatesPath)
	str("static-path", &c.StaticPath)
	str("media-path", &c.MediaPath)
	str("default-date-format", &c.DefaultDateFormat)
	if v, ok := cli.Str("colorscheme"); ok {
		em, isMap := c.Extra.(*OMap)
		if !isMap || em == nil {
			em = NewOMap()
		} else {
			em = em.Clone()
		}
		em.Set("colorscheme", v)
		em.SortKeys()
		c.Extra = em
	}
	bl("toc", &c.Toc)
	bl("json-feed", &c.JSONFeed)
	bl("show-next-prev-links", &c.ShowNextPrevLinks)
	bl("publish-md", &c.PublishMD)
	if v, ok := cli.Str("source-repository"); ok {
		c.SourceRepository = v
	}
	if v, ok := cli.Str("image-provider"); ok {
		c.ImageProvider = v
	}
	if v, ok := cli.Str("theme"); ok {
		c.Theme = v
	}
	bl("build-sitemap", &c.BuildSitemap)
	bl("publish-urls-json", &c.PublishURLsJSON)
	bl("enable-shortcodes", &c.EnableShortcodes)
	if v, ok := cli.Str("shortcode-pattern"); ok {
		c.ShortcodePattern = v
	}
	bl("skip-image-resize", &c.SkipImageResize)
}

func (s *Site) collectContent() {
	s.loadFragments()
	outAbs, _ := filepath.Abs(s.outputDir)
	var files []string
	walkFiles(s.contentDir, func(p string, isDir bool) bool {
		abs, _ := filepath.Abs(p)
		if abs == outAbs {
			return true
		}
		return false
	}, func(p string) {
		if strings.HasSuffix(p, ".md") && !isDir(p) {
			base := filepath.Base(p)
			if strings.HasPrefix(base, "_") {
				return
			}
			files = append(files, p)
		}
	})
	for _, f := range files {
		c, err := s.parseContentFile(f)
		if err != nil {
			logError("marmite::site", fmt.Sprintf("Failed to process file %s: %v", f, err))
			continue
		}
		if c.Date != nil {
			s.posts = append(s.posts, c)
		} else {
			s.pages = append(s.pages, c)
		}
	}
	sortByDateDesc(s.posts)
	sort.SliceStable(s.pages, func(i, j int) bool { return s.pages[i].Title > s.pages[j].Title })
	s.all = append(append([]*Content{}, s.posts...), s.pages...)
}

func (s *Site) buildGroups() {
	s.groups = map[string]*Group{
		"tag": newGroup("tag"), "archive": newGroup("archive"), "author": newGroup("author"),
		"stream": newGroup("stream"), "series": newGroup("series"),
	}
	for _, c := range s.posts {
		draft := c.StreamStr() == "draft"
		if !draft {
			for _, t := range c.Tags {
				s.groups["tag"].add(t, c)
				if sl := slugify(t); sl != t {
					s.groups["tag"].add(sl, c)
				}
			}
			s.groups["archive"].add(c.Date.Format("2006"), c)
			for _, a := range c.Authors {
				s.groups["author"].add(a, c)
			}
		}
		if st := c.StreamStr(); st != "" {
			s.groups["stream"].add(st, c)
		}
		if se := c.SeriesStr(); se != "" && !draft {
			s.groups["series"].add(se, c)
		}
	}
	for _, g := range s.groups {
		g.sortAll()
	}
}

func (s *Site) computeRelations() {
	// back links
	for _, target := range s.all {
		for _, src := range s.all {
			if src == target {
				continue
			}
			for _, l := range src.LinksTo {
				if l == target.Slug || strings.HasPrefix(l, target.Slug+"#") {
					target.BackLinks = append(target.BackLinks, src)
					break
				}
			}
		}
	}
	// next / previous
	byStream := map[string][]*Content{}
	bySeries := map[string][]*Content{}
	for _, c := range s.posts {
		if se := c.SeriesStr(); se != "" {
			bySeries[se] = append(bySeries[se], c)
		} else {
			st := c.StreamStr()
			byStream[st] = append(byStream[st], c)
		}
	}
	link := func(list []*Content) {
		l := append([]*Content{}, list...)
		sortByDateAsc(l)
		for i, c := range l {
			if i > 0 {
				c.Previous = l[i-1]
			}
			if i+1 < len(l) {
				c.Next = l[i+1]
			}
		}
	}
	for _, l := range byStream {
		link(l)
	}
	for _, l := range bySeries {
		link(l)
	}
}

func (s *Site) groupValue(g *Group, kindName string) *OMap {
	m := NewOMap()
	m.Set("kind", kindName)
	mm := NewOMap()
	for _, k := range g.keys {
		var arr []Value
		for _, c := range g.m[k] {
			arr = append(arr, c.ToValue())
		}
		mm.Set(k, arr)
	}
	m.Set("map", mm)
	return m
}

func (s *Site) buildURLs() {
	u := &GeneratedURLs{}
	for _, c := range s.posts {
		u.Posts = append(u.Posts, c.Slug+".html")
	}
	for _, c := range s.pages {
		u.Pages = append(u.Pages, c.Slug+".html")
	}
	if len(s.pages) > 0 {
		u.Pages = append(u.Pages, "pages.html")
	}
	tg := s.groups["tag"]
	seen := map[string]bool{}
	var tagSlugs []string
	for _, k := range tg.urlKeys() {
		sl := slugify(k)
		if !seen[sl] {
			seen[sl] = true
			tagSlugs = append(tagSlugs, sl)
		}
	}
	for _, sl := range tagSlugs {
		u.Tags = append(u.Tags, "tag-"+sl+".html")
	}
	if len(tagSlugs) > 0 {
		u.Tags = append(u.Tags, "tags.html")
	}
	ag := s.groups["author"]
	for _, k := range ag.urlKeys() {
		u.Authors = append(u.Authors, "author-"+slugify(k)+".html")
	}
	if len(ag.keys) > 0 {
		u.Authors = append(u.Authors, "authors.html")
	}
	sg := s.groups["series"]
	for _, k := range sg.urlKeys() {
		u.Series = append(u.Series, "series-"+slugify(k)+".html")
	}
	if len(sg.keys) > 0 {
		u.Series = append(u.Series, "series.html")
	}
	stg := s.groups["stream"]
	for _, k := range stg.urlKeys() {
		if k == "index" {
			continue
		}
		u.Streams = append(u.Streams, slugify(k)+".html")
	}
	if len(stg.keys) > 0 {
		u.Streams = append(u.Streams, "streams.html")
	}
	arg := s.groups["archive"]
	for _, k := range arg.urlKeys() {
		u.Archives = append(u.Archives, "archive-"+k+".html")
	}
	if len(arg.keys) > 0 {
		u.Archives = append(u.Archives, "archive.html")
	}
	// feeds
	feedExts := []string{".rss"}
	if s.cfg.JSONFeed {
		feedExts = append(feedExts, ".json")
	}
	for _, ext := range feedExts {
		indexPosts := s.groups["stream"].m["index"]
		if len(indexPosts) > 0 {
			u.Feeds = append(u.Feeds, "index"+ext)
		}
		for _, k := range stg.urlKeys() {
			if k == "index" {
				continue
			}
			u.Feeds = append(u.Feeds, slugify(k)+ext)
		}
		for _, k := range sg.urlKeys() {
			u.Feeds = append(u.Feeds, "series-"+slugify(k)+ext)
		}
		for _, sl := range tagSlugs {
			u.Feeds = append(u.Feeds, "tag-"+sl+ext)
		}
		for _, k := range ag.urlKeys() {
			u.Feeds = append(u.Feeds, "author-"+slugify(k)+ext)
		}
		for _, k := range arg.urlKeys() {
			u.Feeds = append(u.Feeds, "archive-"+k+ext)
		}
	}
	// pagination
	per := int(s.cfg.Pagination)
	pages := func(n int) int {
		if per <= 0 {
			return 0
		}
		return int(math.Ceil(float64(n) / float64(per)))
	}
	addPag := func(base string, n int) {
		for i := 1; i <= pages(n); i++ {
			u.Pagination = append(u.Pagination, fmt.Sprintf("%s-%d.html", base, i))
		}
	}
	addPag("pages", len(s.pages))
	for _, sl := range tagSlugs {
		addPag("tag-"+sl, s.tagListCount(sl))
	}
	for _, k := range ag.urlKeys() {
		addPag("author-"+slugify(k), len(ag.m[k]))
	}
	for _, k := range sg.urlKeys() {
		addPag("series-"+slugify(k), len(sg.m[k]))
	}
	for _, k := range stg.urlKeys() {
		if k == "index" {
			continue
		}
		addPag(slugify(k), len(stg.m[k]))
	}
	for _, k := range arg.urlKeys() {
		addPag("archive-"+k, len(arg.m[k]))
	}
	if np := pages(len(s.indexPosts())); np > 1 {
		addPag("index", len(s.indexPosts()))
	}
	u.Misc = []string{"index.html"}
	s.urls = u
}

func (s *Site) tagListCount(slug string) int {
	return len(s.groups["tag"].m[slug])
}

func (s *Site) indexPosts() []*Content {
	var out []*Content
	for _, c := range s.posts {
		if c.StreamStr() == "index" {
			out = append(out, c)
		}
	}
	return pinnedFirst(out)
}

func (s *Site) buildSiteData() {
	sd := NewOMap()
	sd.Set("site", s.siteValue)
	var posts, pages []Value
	for _, c := range s.posts {
		posts = append(posts, c.ToValue())
	}
	for _, c := range s.pages {
		pages = append(pages, c.ToValue())
	}
	if posts == nil {
		posts = []Value{}
	}
	if pages == nil {
		pages = []Value{}
	}
	sd.Set("posts", posts)
	sd.Set("pages", pages)
	sd.Set("tag", s.groupValue(s.groups["tag"], "Tag"))
	sd.Set("archive", s.groupValue(s.groups["archive"], "Archive"))
	sd.Set("author", s.groupValue(s.groups["author"], "Author"))
	sd.Set("stream", s.groupValue(s.groups["stream"], "Stream"))
	sd.Set("series", s.groupValue(s.groups["series"], "Series"))
	sd.Set("latest_timestamp", nil)
	sd.Set("config_path", s.configPath)
	sd.Set("force_render", s.cli.Flags["force"])
	gu := s.urlsValue(false)
	sd.Set("generated_urls", gu)
	sd.Set("galleries", NewOMap())
	s.siteData = sd
}

func (s *Site) baseContext() *OMap {
	ctx := NewOMap()
	ctx.Set("site", s.siteValue)
	ctx.Set("menu", s.cfg.Menu)
	ctx.Set("language", s.cfg.Language)
	mf := NewOMap()
	mf.Set("references", s.fragments["references"])
	mf.Set("markdown_footer", s.fragments["markdown_footer"])
	mf.Set("markdown_header", s.fragments["markdown_header"])
	ctx.Set("markdown_fragments", mf)
	ctx.Set("site_data", s.siteData)
	for k, v := range s.fragHTML {
		ctx.Set(k, v)
	}
	return ctx
}

func (s *Site) renderFragments() {
	s.fragHTML = map[string]string{}
	base := s.baseContext()
	for _, n := range []string{"announce", "header", "footer", "htmlhead", "htmltail", "hero", "sidebar", "comments"} {
		src, ok := s.fragments[n]
		if !ok {
			continue
		}
		rendered, err := s.tera.RenderString(src, base)
		if err != nil {
			logError("marmite::site", fmt.Sprintf("Failed to render fragment %s: %v", n, err))
			rendered = src
		}
		s.fragHTML[n] = s.renderMarkdown(rendered + "\n\n" + s.fragments["references"])
	}
}

func cloneCtx(base *OMap) *OMap {
	return base.Clone()
}

func sortedCtx(ctx *OMap) *OMap {
	c := ctx.Clone()
	c.SortKeys()
	return c
}

func (s *Site) renderTemplate(tplName string, ctx *OMap, outName string, isContent bool) {
	html, err := s.tera.Render(tplName, sortedCtx(ctx))
	if err != nil {
		logError("marmite::site", fmt.Sprintf("Error rendering template `%s` -> %s: %v", tplName, outName, err))
		logError("marmite::site", fmt.Sprintf("Failed to render templates: \"Failed to render '%s'\"", tplName))
		os.Exit(1)
	}
	if isContent {
		if s.cfg.EnableShortcodes && s.shortcodes != nil {
			html = s.shortcodes.Process(html, ctx)
		}
		html = s.resolveWikilinks(html)
	}
	out := filepath.Join(s.outputDir, outName)
	if err := writeFile(out, html); err != nil {
		logError("marmite::site", fmt.Sprintf("Failed to write %s: %v", out, err))
		os.Exit(1)
	}
	logInfo("marmite::site", "Generated "+joinOut(s.outputDir, outName))
}

func joinOut(dir, name string) string {
	return strings.TrimSuffix(dir, "/") + "/" + name
}

func contentListValue(list []*Content) []Value {
	out := []Value{}
	for _, c := range list {
		out = append(out, c.ToValue())
	}
	return out
}

func (s *Site) renderList(tplName, base, title string, list []*Content, extra map[string]Value, emptyTitle string) {
	per := int(s.cfg.Pagination)
	total := len(list)
	totalPages := 0
	if per > 0 {
		totalPages = int(math.Ceil(float64(total) / float64(per)))
	}
	if total == 0 {
		ctx := s.baseContext()
		t := title
		if emptyTitle != "" {
			t = emptyTitle
		}
		ctx.Set("title", t)
		ctx.Set("current_page", base+".html")
		ctx.Set("content_list", []Value{})
		ctx.Set("per_page", int64(per))
		ctx.Set("total_content", int64(0))
		ctx.Set("total_pages", int64(0))
		ctx.Set("current_page_number", int64(1))
		for k, v := range extra {
			ctx.Set(k, v)
		}
		s.renderTemplate(tplName, ctx, base+".html", false)
		return
	}
	for p := 1; p <= totalPages; p++ {
		st := (p - 1) * per
		en := st + per
		if en > total {
			en = total
		}
		ctx := s.baseContext()
		ctx.Set("content_list", contentListValue(list[st:en]))
		ctx.Set("per_page", int64(per))
		ctx.Set("total_content", int64(total))
		ctx.Set("total_pages", int64(totalPages))
		ctx.Set("current_page_number", int64(p))
		if p > 1 {
			ctx.Set("previous_page", fmt.Sprintf("%s-%d.html", base, p-1))
		}
		if p < totalPages {
			ctx.Set("next_page", fmt.Sprintf("%s-%d.html", base, p+1))
		}
		for k, v := range extra {
			ctx.Set(k, v)
		}
		pageTitle := fmt.Sprintf("%s - %d", title, p)
		if title == "" {
			pageTitle = fmt.Sprintf("Page - %d", p)
		}
		ctx.Set("title", pageTitle)
		ctx.Set("current_page", fmt.Sprintf("%s-%d.html", base, p))
		s.renderTemplate(tplName, ctx, fmt.Sprintf("%s-%d.html", base, p), false)
		if p == 1 {
			ctx2 := ctx.Clone()
			ctx2.Set("title", title)
			ctx2.Set("current_page", base+".html")
			s.renderTemplate(tplName, ctx2, base+".html", false)
		}
	}
}

func displayName(m *OMap, key string) string {
	if v, ok := m.Get(key); ok {
		if om, ok := v.(*OMap); ok {
			if dn, ok := om.Get("display_name"); ok {
				if ds, ok := dn.(string); ok && ds != "" {
					return ds
				}
			}
		}
	}
	return key
}

func (s *Site) authorValue(username string) *OMap {
	if v, ok := s.cfg.Authors.Get(username); ok {
		if om, ok := v.(*OMap); ok {
			return om
		}
	}
	a := NewOMap()
	a.Set("name", username)
	a.Set("avatar", "static/avatar-placeholder.png")
	a.Set("bio", nil)
	a.Set("links", nil)
	return a
}

func (s *Site) tagDisplayName(slug string) string {
	list := s.groups["tag"].m[slug]
	for _, c := range list {
		for _, t := range c.Tags {
			if slugify(t) == slug {
				return t
			}
		}
	}
	return slug
}

func (s *Site) generate() {
	s.renderFragments()
	// index
	idx := s.indexPosts()
	s.renderList(s.indexTemplate(), "index", "", idx, nil, "Welcome to Marmite")
	if len(idx) > 0 {
		s.writeFeeds("index", idx)
	}
	// tags
	s.renderGroupPage("tags.html", "tag", s.cfg.TagsTitle)
	tg := s.groups["tag"]
	doneTag := map[string]bool{}
	for _, k := range tg.urlKeys() {
		sl := slugify(k)
		if doneTag[sl] {
			continue
		}
		doneTag[sl] = true
		name := s.tagDisplayName(sl)
		list := tg.m[sl]
		if list == nil {
			list = tg.m[k]
		}
		title := strings.ReplaceAll(s.cfg.TagsContentTitle, "$tag", name)
		s.renderList("list.html", "tag-"+sl, title, list, nil, "")
		s.writeFeeds("tag-"+sl, list)
	}
	// authors
	s.renderGroupPage("authors.html", "author", s.cfg.AuthorsTitle)
	ag := s.groups["author"]
	for _, k := range ag.urlKeys() {
		sl := slugify(k)
		author := s.authorValue(k)
		name := renderValue(func() Value { v, _ := author.Get("name"); return v }())
		list := pinnedFirst(ag.m[k])
		s.renderList("list.html", "author-"+sl, name, list, map[string]Value{"author": author}, "")
		s.writeFeeds("author-"+sl, ag.m[k])
	}
	// streams
	s.renderGroupPage("streams.html", "stream", s.cfg.StreamsTitle)
	stg := s.groups["stream"]
	for _, k := range stg.urlKeys() {
		if k == "index" {
			continue
		}
		sl := slugify(k)
		title := strings.ReplaceAll(s.cfg.StreamsContentTitle, "$stream", displayName(s.cfg.Streams, k))
		list := pinnedFirst(stg.m[k])
		s.renderList("list.html", sl, title, list, nil, "")
		if k != "draft" {
			s.writeFeeds(sl, stg.m[k])
		}
	}
	// series
	s.renderGroupPage("series.html", "series", s.cfg.SeriesTitle)
	sg := s.groups["series"]
	for _, k := range sg.urlKeys() {
		sl := slugify(k)
		title := strings.ReplaceAll(s.cfg.SeriesContentTitle, "$series", displayName(s.cfg.Series, k))
		s.renderList("list.html", "series-"+sl, title, sg.m[k], nil, "")
		s.writeFeeds("series-"+sl, sg.m[k])
	}
	// archive
	s.renderGroupPage("archive.html", "archive", s.cfg.ArchivesTitle)
	arg := s.groups["archive"]
	for _, k := range arg.urlKeys() {
		title := strings.ReplaceAll(s.cfg.ArchivesContentTitle, "$year", k)
		s.renderList("list.html", "archive-"+k, title, arg.m[k], nil, "")
		s.writeFeeds("archive-"+k, arg.m[k])
	}
	// pages
	s.renderList("list.html", "pages", s.cfg.PagesTitle, s.pages, nil, "")
	// 404
	s.render404()
	// content
	for _, c := range s.all {
		s.renderContent(c)
	}
}

func (s *Site) indexTemplate() string {
	if s.tera.HasTemplate("custom_index.html") {
		return "custom_index.html"
	}
	return "list.html"
}

func (s *Site) renderGroupPage(outName, kind, title string) {
	ctx := s.baseContext()
	ctx.Set("title", title)
	ctx.Set("kind", kind)
	ctx.Set("current_page", outName)
	s.renderTemplate("group.html", ctx, outName, false)
}

func (s *Site) renderContent(c *Content) {
	ctx := s.baseContext()
	ctx.Set("title", c.Title)
	ctx.Set("content", c.ToValue())
	ctx.Set("current_page", c.Slug+".html")
	if cb, ok := c.Comments.(bool); ok && !cb {
		ctx.Delete("comments")
	}
	s.renderTemplate("content.html", ctx, c.Slug+".html", true)
}

func (s *Site) render404() {
	c := &Content{Title: "Page not found", HTML: "Page not found :/", Slug: "404", Tags: []string{}, Authors: []string{}}
	if src, ok := s.fragments["404"]; ok {
		_, body, _ := splitFrontmatter(src)
		title, rest := extractTitle(nil, body)
		_ = rest
		c.Title = title
		html := s.renderMarkdown(normalizeBody(body) + "\n\n" + s.fragments["references"])
		c.HTML = html
		c.SourcePath = ""
	}
	ctx := s.baseContext()
	ctx.Set("title", c.Title)
	v := c.ToValue()
	v.Set("source_path", nil)
	ctx.Set("content", v)
	ctx.Set("current_page", "404.html")
	s.renderTemplate("content.html", ctx, "404.html", true)
}

func (s *Site) writeSitemap() {
	if !s.cfg.BuildSitemap {
		return
	}
	var urls []Value
	for _, sec := range s.urls.sections() {
		for _, u := range sec {
			urls = append(urls, s.absURL(u))
		}
	}
	ctx := s.baseContext()
	if urls == nil {
		urls = []Value{}
	}
	ctx.Set("sitemap_urls", urls)
	out, err := s.tera.Render("sitemap.xml", sortedCtx(ctx))
	if err != nil {
		logError("marmite::site", fmt.Sprintf("Failed to render sitemap: %v", err))
		return
	}
	writeFile(filepath.Join(s.outputDir, "sitemap.xml"), out)
	logInfo("marmite::site", fmt.Sprintf("Generated sitemap.xml with %d URLs", len(urls)))
}

func (s *Site) writeURLsJSON() {
	if !s.cfg.PublishURLsJSON {
		return
	}
	writeFile(filepath.Join(s.outputDir, "urls.json"), toJSONPretty(s.urlsValue(true)))
	logInfo("marmite::site", "Generated urls.json")
}

func (s *Site) writeBuildInfo() {
	now := time.Now().UTC()
	m := NewOMap()
	m.Set("marmite_version", versionString)
	m.Set("posts", int64(len(s.posts)))
	m.Set("pages", int64(len(s.pages)))
	m.Set("generated_at", now.Format("2006-01-02 15:04:05.000000000 +00:00"))
	m.Set("timestamp", now.Unix())
	m.Set("elapsed_time", time.Since(s.startTime).Seconds())
	m.Set("config", s.siteValue)
	writeFile(filepath.Join(s.outputDir, "marmite.json"), toJSONPretty(m))
	logInfo("marmite::site", "Generated build info at marmite.json")
}

// ---------- static assets ----------

func (s *Site) writeEmbeddedStatic() {
	staticOut := filepath.Join(s.outputDir, "static")
	fs.WalkDir(assetsFS, "assets/static", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		rel := strings.TrimPrefix(p, "assets/static/")
		data, _ := assetsFS.ReadFile(p)
		target := filepath.Join(staticOut, rel)
		writeFile(target, string(data))
		logInfo("marmite::embedded", "Generated "+joinOut(staticOut, rel))
		return nil
	})
}

func (s *Site) copyStatic() {
	staticOut := filepath.Join(s.outputDir, "static")
	if s.staticDir != "" && isDir(s.staticDir) {
		copyDir(s.staticDir, staticOut)
		logInfo("marmite::site", fmt.Sprintf("Copied '%s' to '%s/'", s.staticDir, s.outputDir))
	} else {
		s.writeEmbeddedStatic()
	}
	media := s.contentDir + "/" + s.cfg.MediaPath
	if isDir(media) {
		copyDir(media, filepath.Join(s.outputDir, s.cfg.MediaPath))
		logInfo("marmite::site", fmt.Sprintf("Copied '%s' to '%s/'", media, s.outputDir))
	}
	for _, f := range []string{"custom.css", "custom.js"} {
		src := s.inputDir + "/" + f
		if fileExists(src) {
			copyFile(src, filepath.Join(staticOut, f))
			logInfo("marmite::site", fmt.Sprintf("Copied %s to %s", src, joinOut(staticOut, f)))
		}
	}
	for _, f := range []string{"favicon.ico", "robots.txt"} {
		src := s.inputDir + "/" + f
		if fileExists(src) {
			copyFile(src, filepath.Join(s.outputDir, f))
		} else if fileExists(filepath.Join(staticOut, f)) && f == "robots.txt" {
			copyFile(filepath.Join(staticOut, f), filepath.Join(s.outputDir, f))
		}
	}
	s.copyFileMappings()
}

func (s *Site) copyFileMappings() {
	arr, ok := s.cfg.FileMapping.([]Value)
	if !ok {
		return
	}
	for _, it := range arr {
		m, ok := it.(*OMap)
		if !ok {
			continue
		}
		srcV, _ := m.Get("source")
		dstV, _ := m.Get("dest")
		src, _ := srcV.(string)
		dst, _ := dstV.(string)
		if src == "" || dst == "" {
			continue
		}
		sp := src
		if !filepath.IsAbs(sp) {
			sp = s.inputDir + "/" + src
		}
		dp := filepath.Join(s.outputDir, dst)
		if isDir(sp) {
			copyDir(sp, dp)
		} else if fileExists(sp) {
			copyFile(sp, dp)
		}
		s.urls.FileMappings = append(s.urls.FileMappings, strings.TrimPrefix(dst, "/"))
	}
}

// ---------- templates ----------

func (s *Site) loadTemplates() {
	s.tera = NewTera()
	fs.WalkDir(assetsFS, "assets/templates", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		name := strings.TrimPrefix(p, "assets/templates/")
		data, _ := assetsFS.ReadFile(p)
		if err := s.tera.AddTemplate(name, string(data)); err != nil {
			logError("marmite::site", fmt.Sprintf("Failed to load embedded template %s: %v", name, err))
		}
		return nil
	})
	if s.templatesDir != "" && isDir(s.templatesDir) {
		filepath.Walk(s.templatesDir, func(p string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() {
				return nil
			}
			rel, _ := filepath.Rel(s.templatesDir, p)
			data, err := os.ReadFile(p)
			if err != nil {
				return nil
			}
			if err := s.tera.AddTemplate(rel, string(data)); err != nil {
				logError("marmite::site", fmt.Sprintf("Failed to load template %s: Failed to parse '%s'", rel, rel))
			}
			return nil
		})
	}
	registerMarmiteFunctions(s)
	s.shortcodes = newShortcodeProcessor(s)
}

func registerMarmiteFunctions(s *Site) {
	t := s.tera
	t.functions["url_for"] = func(a map[string]Value) (Value, error) {
		pv, ok := a["path"]
		if !ok {
			return nil, fmt.Errorf("Function `url_for` was called without a `path` argument")
		}
		path, ok := pv.(string)
		if !ok {
			return nil, fmt.Errorf("Function `url_for` received path=%s but `path` can only be a string", toJSON(pv))
		}
		abs := argBool(a, "abs", false)
		return s.urlFor(path, abs), nil
	}
	t.functions["group"] = func(a map[string]Value) (Value, error) {
		kind, _ := argStr(a, "kind", "")
		g, ok := s.groups[kind]
		if !ok {
			return nil, fmt.Errorf("Invalid kind: %s", kind)
		}
		ord, _ := argStr(a, "ord", "")
		items := 0
		if n, ok := argNum(a, "items"); ok {
			items = int(n)
		}
		keys := g.orderedKeys()
		if ord == "asc" {
			for i, j := 0, len(keys)-1; i < j; i, j = i+1, j-1 {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
		if items > 0 && items < len(keys) {
			keys = keys[:items]
		}
		m := NewOMap()
		for _, k := range keys {
			m.Set(k, contentListValue(g.m[k]))
		}
		return m, nil
	}
	t.functions["stream_display_name"] = func(a map[string]Value) (Value, error) {
		st, _ := argStr(a, "stream", "")
		return displayName(s.cfg.Streams, st), nil
	}
	t.functions["series_display_name"] = func(a map[string]Value) (Value, error) {
		st, _ := argStr(a, "series", "")
		return displayName(s.cfg.Series, st), nil
	}
	t.functions["source_link"] = func(a map[string]Value) (Value, error) {
		cv, _ := a["content"].(*OMap)
		if cv == nil {
			return "", nil
		}
		spv, _ := cv.Get("source_path")
		sp, _ := spv.(string)
		if sp == "" {
			return "", nil
		}
		if repo, ok := s.cfg.SourceRepository.(string); ok && repo != "" {
			fname := filepath.Base(sp)
			return strings.TrimRight(repo, "/") + "/" + fname, nil
		}
		if s.cfg.PublishMD {
			slugV, _ := cv.Get("slug")
			return renderValue(slugV) + ".md", nil
		}
		return "", nil
	}
	t.filters["default_date_format"] = func(v Value, a map[string]Value) (Value, error) {
		str, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("Filter `default_date_format` received an incorrect type for arg `value`")
		}
		tm, ok := parseTeraDate(str)
		if !ok {
			return nil, fmt.Errorf("Error parsing date")
		}
		return strftime(tm, s.cfg.DefaultDateFormat), nil
	}
	t.filters["remove_draft"] = func(v Value, a map[string]Value) (Value, error) {
		arr, ok := v.([]Value)
		if !ok {
			return v, nil
		}
		out := []Value{}
		for _, e := range arr {
			if m, ok := e.(*OMap); ok {
				if st, _ := m.Get("stream"); st == "draft" {
					continue
				}
			}
			out = append(out, e)
		}
		return out, nil
	}
}

func (s *Site) urlFor(path string, abs bool) string {
	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		return path
	}
	p := strings.TrimLeft(path, "/")
	if abs {
		if s.cfg.URL == "" {
			return "/" + p
		}
		return strings.TrimRight(s.cfg.URL, "/") + "/" + p
	}
	prefix := "/"
	if s.cfg.URL != "" {
		if u, err := url.Parse(s.cfg.URL); err == nil && u.Scheme != "" && u.Host != "" {
			up := strings.Trim(u.Path, "/")
			if up != "" {
				prefix = "/" + up + "/"
			}
		}
	}
	return prefix + p
}
