package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

const defaultShortcodePattern = `<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->`

type shortcodeDef struct {
	name        string
	isMarkdown  bool
	description string
}

type ShortcodeProcessor struct {
	site  *Site
	re    *regexp.Regexp
	defs  map[string]*shortcodeDef
	names []string
}

func newShortcodeProcessor(s *Site) *ShortcodeProcessor {
	sp := &ShortcodeProcessor{site: s, defs: map[string]*shortcodeDef{}}
	pat := defaultShortcodePattern
	if p, ok := s.cfg.ShortcodePattern.(string); ok && p != "" {
		pat = p
	}
	re, err := regexp.Compile(pat)
	if err != nil {
		re = regexp.MustCompile(defaultShortcodePattern)
	}
	sp.re = re
	fs.WalkDir(assetsFS, "assets/shortcodes", func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		base := filepath.Base(p)
		ext := filepath.Ext(base)
		if ext != ".html" && ext != ".md" {
			return nil
		}
		name := strings.TrimSuffix(base, ext)
		data, _ := assetsFS.ReadFile(p)
		sp.add(name, string(data), ext == ".md")
		return nil
	})
	dir := s.inputDir + "/shortcodes"
	if isDir(dir) {
		entries, _ := os.ReadDir(dir)
		for _, e := range entries {
			ext := filepath.Ext(e.Name())
			if ext != ".html" && ext != ".md" {
				continue
			}
			data, err := os.ReadFile(filepath.Join(dir, e.Name()))
			if err != nil {
				continue
			}
			sp.add(strings.TrimSuffix(e.Name(), ext), string(data), ext == ".md")
		}
	}
	sort.Strings(sp.names)
	return sp
}

var reShortcodeDesc = regexp.MustCompile(`^\{#\s*([\s\S]*?)\s*#\}`)

func (sp *ShortcodeProcessor) add(name, src string, md bool) {
	if err := sp.site.tera.AddTemplate("shortcodes/"+name, src); err != nil {
		logWarn("marmite::shortcodes", fmt.Sprintf("Failed to load shortcode %s: %v", name, err))
		return
	}
	desc := ""
	if m := reShortcodeDesc.FindStringSubmatch(strings.TrimSpace(src)); m != nil {
		desc = m[1]
	}
	if _, ok := sp.defs[name]; !ok {
		sp.names = append(sp.names, name)
	}
	sp.defs[name] = &shortcodeDef{name: name, isMarkdown: md, description: desc}
}

var reShortcodeParam = regexp.MustCompile(`(\w+)=(?:"([^"]*)"|'([^']*)'|(\S+))`)

func parseShortcodeParams(s string) *OMap {
	m := NewOMap()
	for _, sm := range reShortcodeParam.FindAllStringSubmatch(s, -1) {
		v := sm[4]
		if sm[2] != "" || strings.Contains(sm[0], "=\"") {
			v = sm[2]
		} else if sm[3] != "" || strings.Contains(sm[0], "='") {
			v = sm[3]
		}
		m.Set(sm[1], resolveParam(v))
	}
	return m
}

func resolveParam(v string) Value {
	return v
}

func (sp *ShortcodeProcessor) Process(html string, ctx *OMap) string {
	return sp.re.ReplaceAllStringFunc(html, func(m string) string {
		sm := sp.re.FindStringSubmatch(m)
		if len(sm) < 2 {
			return m
		}
		name := sm[1]
		params := ""
		if len(sm) > 2 {
			params = sm[2]
		}
		def, ok := sp.defs[name]
		if !ok {
			msg := fmt.Sprintf("Shortcode '%s' not found", name)
			logWarn("marmite::shortcodes", fmt.Sprintf("Shortcode '%s' failed to render: %s", name, msg))
			return shortcodeError(msg)
		}
		c := ctx.Clone()
		pm := parseShortcodeParams(params)
		for _, k := range pm.Keys() {
			v, _ := pm.Get(k)
			c.Set(k, v)
		}
		out, err := sp.site.tera.Render("shortcodes/"+name, sortedCtx(c))
		if err != nil {
			logWarn("marmite::shortcodes", fmt.Sprintf("Shortcode '%s' failed to render: %v", name, err))
			return shortcodeError(err.Error())
		}
		if def.isMarkdown {
			out = sp.site.renderMarkdown(out)
		}
		return out
	})
}

func shortcodeError(msg string) string {
	return "<div class=\"shortcode-error\" style=\"border: 2px solid red; padding: 10px; margin: 10px 0; background-color: #ffeeee; color: #cc0000;\">\n                        <strong>Shortcode Error:</strong> " + escapeHTMLAttr(msg) + "</div>"
}

func escapeHTMLAttr(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;")
	return r.Replace(s)
}
