package main

import (
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

func serveAndWatch(s *Site, cli *CLI) {
	bind := "0.0.0.0:8000"
	if v, ok := cli.Str("bind"); ok {
		bind = v
	}
	if cli.Flags["watch"] {
		go watchLoop(cli)
	}
	if cli.Flags["serve"] {
		logInfo("marmite::server", fmt.Sprintf("Starting built-in HTTP server on http://%s", bind))
		fsrv := http.FileServer(http.Dir(s.outputDir))
		err := http.ListenAndServe(bind, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			p := filepath.Join(s.outputDir, filepath.Clean(r.URL.Path))
			if st, err := os.Stat(p); err != nil || (st.IsDir() && !fileExists(filepath.Join(p, "index.html"))) {
				if b, err := os.ReadFile(filepath.Join(s.outputDir, "404.html")); err == nil {
					w.Header().Set("Content-Type", "text/html")
					w.WriteHeader(404)
					w.Write(b)
					return
				}
			}
			fsrv.ServeHTTP(w, r)
		}))
		if err != nil {
			logError("marmite::server", fmt.Sprintf("Failed to start server: %v", err))
			os.Exit(1)
		}
		return
	}
	select {}
}

func latestMtime(dir string) time.Time {
	var latest time.Time
	filepath.Walk(dir, func(p string, info os.FileInfo, err error) error {
		if err == nil && info.ModTime().After(latest) {
			latest = info.ModTime()
		}
		return nil
	})
	return latest
}

func watchLoop(cli *CLI) {
	last := latestMtime(cli.Input)
	for {
		time.Sleep(time.Second)
		m := latestMtime(cli.Input)
		if m.After(last) {
			last = m
			s := newSite(cli)
			s.build()
			last = latestMtime(cli.Input)
		}
	}
}
