func writeYAML(b *strings.Builder, v Value, indent string, inSeq bool) {
	switch x := v.(type) {
	case []Value:
		if len(x) == 0 {
			b.WriteString(" []\\n")
			return
		}
		b.WriteString("\\n")
		for _, e := range x {
			b.WriteString(indent + "-")
			writeYAMLSeqItem(b, e, indent+"  ")
		}
	case *OMap:
		if x.Len() == 0 {
			b.WriteString(" {}\\n")
			return
		}
		b.WriteString("\\n")
		for _, k := range x.Keys() {
			b.WriteString(indent + "  " + yamlScalar(k) + ":")
			writeYAML(b, x.m[k], indent+"  ", false)
		}
	default:
		b.WriteString(" " + yamlValue(v, indent) + "\\n")
	}
}

// writeYAMLSeqItem writes a sequence item after "-"; indent is the indentation for continuation lines.
func writeYAMLSeqItem(b *strings.Builder, v Value, indent string) {
	switch x := v.(type) {
	case []Value:
		if len(x) == 0 {
			b.WriteString(" []\\n")
			return
		}
		for i, e := range x {
			if i == 0 {
				b.WriteString(" -")
			} else {
				b.WriteString(indent + "-")
			}
			writeYAMLSeqItem(b, e, indent+"  ")
		}
	case *OMap:
		if x.Len() == 0 {
			b.WriteString(" {}\\n")
			return
		}
		for i, k := range x.Keys() {
			if i == 0 {
				b.WriteString(" " + yamlScalar(k) + ":")
			} else {
				b.WriteString(indent + yamlScalar(k) + ":")
			}
			writeYAML(b, x.m[k], indent, false)
		}
	default:
		b.WriteString(" " + yamlValue(v, indent) + "\\n")
	}
}

