func (s *Site) dataBySlug(slug string) (Value, error) {
	mk := func(image, slug, title, text, ctype string) *OMap {
		m := NewOMap()
		m.Set("image", image)
		m.Set("slug", slug)
		m.Set("title", title)
		m.Set("text", text)
		m.Set("content_type", ctype)
		return m
	}
	for _, c := range s.posts {
		if c.Slug == slug {
			img := ""
			if bi, ok := c.BannerImage.(string); ok {
				img = bi
			}
			return mk(img, c.Slug, c.Title, c.Date.Format("2006-01-02"), "post"), nil
		}
	}
	for _, c := range s.pages {
		if c.Slug == slug {
			img := ""
			if bi, ok := c.BannerImage.(string); ok {
				img = bi
			}
			return mk(img, c.Slug, c.Title, "", "page"), nil
		}
	}
	count := func(n int) string { return fmt.Sprintf("%d posts", n) }
	if strings.HasPrefix(slug, "tag-") {
		name := strings.TrimPrefix(slug, "tag-")
		g := s.groups["tag"]
		for _, k := range g.keys {
			if k == name || slugify(k) == name {
				return mk("", slug, k, count(len(g.m[k])), "tag"), nil
			}
		}
		return nil, fmt.Errorf("Tag not found: %s", name)
	}
	if strings.HasPrefix(slug, "author-") {
		name := strings.TrimPrefix(slug, "author-")
		g := s.groups["author"]
		for _, k := range g.keys {
			if k == name || slugify(k) == name {
				av := s.authorValue(k)
				n, _ := av.Get("name")
				img, _ := av.Get("avatar")
				return mk(renderValue(img), slug, renderValue(n), count(len(g.m[k])), "author"), nil
			}
		}
		return nil, fmt.Errorf("Author not found: %s", name)
	}
	if strings.HasPrefix(slug, "series-") {
		name := strings.TrimPrefix(slug, "series-")
		g := s.groups["series"]
		for _, k := range g.keys {
			if k == name || slugify(k) == name {
				return mk("", slug, displayName(s.cfg.Series, k), count(len(g.m[k])), "series"), nil
			}
		}
		return nil, fmt.Errorf("Series not found: %s", name)
	}
	if strings.HasPrefix(slug, "archive-") {
		name := strings.TrimPrefix(slug, "archive-")
		g := s.groups["archive"]
		if l, ok := g.m[name]; ok {
			return mk("", slug, "Posts from "+name, count(len(l)), "archive"), nil
		}
		return nil, fmt.Errorf("Archive not found: %s", name)
	}
	g := s.groups["stream"]
	for _, k := range g.keys {
		if k == slug || slugify(k) == slug {
			return mk("", slug, displayName(s.cfg.Streams, k), count(len(g.m[k])), "stream"), nil
		}
	}
	return nil, fmt.Errorf("Content not found for slug: %s", slug)
}

