	var b strings.Builder
	b.WriteString("Shortcodes:\n")
	fmt.Fprintf(&b, "Enabled: %v\n", s.cfg.EnableShortcodes)
	pat := defaultShortcodePattern
	if p, ok := s.cfg.ShortcodePattern.(string); ok && p != "" {
		pat = p
	}
	b.WriteString("Pattern: " + pat + "\n\n")
	b.WriteString("Reusable blocks of content that can be used in your markdown files.\n")
	b.WriteString("They are defined in the shortcodes/ directory and are rendered using the Tera template engine.\n")
	b.WriteString("Check the documentation for details on how to use and create shortcodes.\n")
	b.WriteString("================\n")
	b.WriteString("Examples based on your configuration:\n")
	// pick up to 3 shortcodes (map iteration order is random, like the original)
	picked := 0
	for name := range sp.defs {
		if picked >= 3 {
			break
		}
		picked++
		b.WriteString("  " + shortcodeExample(pat, name, "") + "\n")
		if sp.hasParams(name) {
			b.WriteString("  " + shortcodeExample(pat, name, "param=value") + "\n")
		}
	}
	b.WriteString("\nNote: Replace 'param' and 'value' with actual parameter names and values.\n")
	b.WriteString("--------------------------------\n")
	b.WriteString("Available shortcodes:\n")
