	for _, n := range names {
		d := sp.defs[n]
		if d.description != "" {
			b.WriteString("  - " + n + ": " + d.description + "\n")
		} else {
			b.WriteString("  - " + n + "\n")
		}
	}
	fmt.Print(b.String())
}

func shortcodeExample(pat, name, params string) string {
	if pat == defaultShortcodePattern {
		if params != "" {
			return "<!-- ." + name + " " + params + " -->"
		}
		return "<!-- ." + name + " -->"
	}
	ex := pat
	ex = strings.ReplaceAll(ex, `(\w+)`, name)
	ex = strings.ReplaceAll(ex, `\`, "")
	if params != "" {
		return ex + " " + params
	}
	return ex
}

func (sp *ShortcodeProcessor) hasParams(name string) bool {
	tpl := sp.site.tera.templates["shortcodes/"+name]
	if tpl == nil {
		return false
	}
	m, ok := tpl.macros[name]
	return ok && len(m.args) > 0
}
