func (p *mdParser) processAutolinks(n *mdNode) *mdNode {
	text := n.literal
	mask := n.escMask
	isEsc := func(i int) bool { return i >= 0 && i < len(mask) && mask[i] }
	for i := 0; i < len(text); i++ {
