			}
			p := filepath.Join(out, filepath.FromSlash(reqPath))
			st, err := os.Stat(p)
			if err == nil && st.IsDir() {
				p = filepath.Join(p, "index.html")
				st, err = os.Stat(p)
			}
			if err != nil {
				logError("marmite::server", fmt.Sprintf("\"%s %s %s\" 404 -", r.Method, reqPath, r.Proto))
				w.Header().Set("Server", "tiny-http (Rust)")
				if b, err := os.ReadFile(filepath.Join(out, "404.html")); err == nil {
					w.WriteHeader(404)
					w.Write(b)
				} else {
					w.WriteHeader(404)
				}
				return
			}
			b, _ := os.ReadFile(p)
			logInfo("marmite::server", fmt.Sprintf("\"%s %s %s\" 200 -", r.Method, reqPath, r.Proto))
			w.Header().Set("Server", "tiny-http (Rust)")
			if ct := mime.TypeByExtension(filepath.Ext(p)); ct != "" {
				w.Header().Set("Content-Type", ct)
			}
			w.WriteHeader(200)
			w.Write(b)
		}))
		return
	}
	select {}
}

func latestMtime(dir string, skip string) time.Time {
	var latest time.Time
	skipAbs, _ := filepath.Abs(skip)
	filepath.Walk(dir, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			if abs, _ := filepath.Abs(p); abs == skipAbs {
				return filepath.SkipDir
			}
		}
		if info.ModTime().After(latest) {
			latest = info.ModTime()
		}
		return nil
	})
	return latest
}

func watchLoop(cli *CLI, outDir string) {
	last := latestMtime(cli.Input, outDir)
	for {
		time.Sleep(time.Second)
		m := latestMtime(cli.Input, outDir)
		if m.After(last) {
			last = m
			logInfo("marmite", "Change detected. Rebuilding site...")
			s := newSite(cli)
			s.build()
			last = latestMtime(cli.Input, outDir)
		}
	}
}
