	s := strings.ReplaceAll(src, "\\r\\n", "\\n")
	trimmed := strings.TrimLeft(s, "\\n")
	for _, delim := range []string{"---", "+++"} {
		if !strings.HasPrefix(trimmed, delim) {
			continue
		}
		nl := strings.IndexByte(trimmed, '\\n')
		first := trimmed
		if nl >= 0 {
			first = trimmed[:nl]
		}
		if strings.Trim(first, delim[:1]) != "" {
			return nil, s, &fmError{"Invalid front matter format"}
		}
		if nl < 0 {
			return nil, s, &fmError{"Invalid front matter format"}
		}
		rest := trimmed[nl+1:]
		lines := strings.SplitAfter(rest, "\\n")
		var fmLines []string
		found := false
		for _, l := range lines {
			if strings.HasPrefix(l, delim) {
				found = true
				break
			}
			fmLines = append(fmLines, l)
		}
		if !found {
			return nil, s, &fmError{"Invalid front matter format"}
		}
		fmText := strings.TrimSuffix(strings.Join(fmLines, ""), "\\n")
		if strings.TrimSpace(fmText) == "" {
			return nil, s, &fmError{"Invalid front matter format"}
		}
		body := ""
		if i := strings.Index(trimmed, "\\n"+delim+"\\n"); i >= 0 {
			body = trimmed[i+len(delim)+2:]
		}
		if delim == "---" {
			v, err := parseYAML(fmText)
			if err != nil {
				return nil, s, &fmError{"Failed to parse YAML: " + err.Error()}
			}
			m, ok := v.(*OMap)
			if !ok {
				return nil, s, &fmError{"Invalid front matter format"}
			}
			return m, body, nil
		}
		m, err := parseTOML(fmText)
		if err != nil {
			return nil, s, &fmError{"Failed to parse TOML: " + err.Error()}
		}
		return m, body, nil
	}
	if strings.HasPrefix(trimmed, "{") {
		jp := &jsonParser{s: trimmed}
		v, err := jp.parseValue()
		if err == nil {
			if m, ok := v.(*OMap); ok {
				after := trimmed[jp.pos:]
				if i := strings.IndexByte(after, '\\n'); i >= 0 {
					after = after[i+1:]
				} else {
					after = ""
				}
				return m, after, nil
			}
		}
	}
	return nil, s, nil
}

