// downloadBannerImages emulates the picsum image provider.
func (s *Site) downloadBannerImages() {
	prov, _ := s.cfg.ImageProvider.(string)
	if prov != "picsum" {
		return
	}
	mediaDir := joinPath(s.contentDir, s.cfg.MediaPath)
	for _, c := range s.posts {
		if bi, ok := c.BannerImage.(string); ok && bi != "" {
			continue
		}
		fname := c.Slug + ".banner.jpg"
		target := joinPath(mediaDir, fname)
		if fileExists(target) {
			c.BannerImage = s.cfg.MediaPath + "/" + fname
			continue
		}
		u := fmt.Sprintf("https://picsum.photos/seed/%s-%s/1200/300", slugify(s.cfg.Name), c.Slug)
		logInfo("marmite::image_provider", "Downloading banner image from: "+u)
		os.MkdirAll(mediaDir, 0o755)
		if data, err := httpGetWithTimeout(u); err == nil && len(data) > 0 {
			if os.WriteFile(target, data, 0o644) == nil {
				c.BannerImage = s.cfg.MediaPath + "/" + fname
			}
		}
	}
}
