}

func rustIOError(err error) string {
	var dnsErr *net.DNSError
	if errors.As(err, &dnsErr) {
		return "io: failed to lookup address information: Temporary failure in name resolution"
	}
	if strings.Contains(err.Error(), "connection refused") {
		return "io: Connection refused (os error 111)"
	}
	return "io: " + err.Error()
}

