src=open('/workspace/generate.go').read()
start=src.index('func (s *Site) copyFileMappings() {')
end=src.index('// ---------- templates ----------')
new='''func (s *Site) copyFileMappings() {
	arr, ok := s.cfg.FileMapping.([]Value)
	if !ok {
		return
	}
	for _, it := range arr {
		m, ok := it.(*OMap)
		if !ok {
			continue
		}
		srcV, _ := m.Get("source")
		dstV, _ := m.Get("dest")
		src, _ := srcV.(string)
		dst, _ := dstV.(string)
		if src == "" || dst == "" {
			continue
		}
		sp := src
		if !filepath.IsAbs(sp) {
			sp = joinPath(s.inputDir, src)
		}
		dp := dst
		if !filepath.IsAbs(dp) {
			dp = joinOut(s.htmlDir(), dst)
		}
		mkParent := func(dir string) bool {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				top := dir
				for {
					parent := filepath.Dir(top)
					if parent == top || isDir(parent) {
						break
					}
					top = parent
				}
				logError("marmite::site", fmt.Sprintf("Failed to create destination directory %s: %s", top, rustOSError(err)))
				return false
			}
			return true
		}
		if st, err := os.Stat(sp); err == nil && !st.IsDir() {
			if mkParent(filepath.Dir(dp)) {
				copyFile(sp, dp)
				logInfo("marmite::site", fmt.Sprintf("Copied file mapping: %s -> %s", sp, dp))
			}
		} else if err == nil && st.IsDir() {
			target := filepath.Join(dp, filepath.Base(sp))
			if mkParent(target) {
				var total int64
				filepath.Walk(sp, func(p string, info os.FileInfo, err error) error {
					if err == nil && !info.IsDir() {
						total += info.Size()
					}
					return nil
				})
				copyDir(sp, target)
				logInfo("marmite::site", fmt.Sprintf("Copied directory mapping: %s -> %s (%d bytes)", sp, dp, total))
			}
		} else {
			matches, _ := filepath.Glob(sp)
			for _, mt := range matches {
				if st, err := os.Stat(mt); err == nil && !st.IsDir() {
					if mkParent(dp) {
						copyFile(mt, filepath.Join(dp, filepath.Base(mt)))
					}
				}
			}
			logInfo("marmite::site", fmt.Sprintf("Processed glob mapping: %s -> %s", sp, dp))
		}
