	v, ok := st.lookupRoot(e.ident)
	evaluated := e.ident
	hasSubscript := false
	notFound := func() error {
		msg := fmt.Sprintf("Variable `%s` not found in context while rendering '%s'", identString(e), st.tplName)
		if hasSubscript {
			msg += fmt.Sprintf(": the evaluated version was `%s`. Maybe the index is out of bounds?", evaluated)
		}
		return &notFoundError{msg}
	}
	for _, p := range e.path {
		if p.expr != nil {
			hasSubscript = true
		}
	}
	if hasSubscript {
		// compute evaluated path string
		for _, p := range e.path {
			if p.expr != nil {
				k, err := st.evalExpr(p.expr)
				if err != nil {
					return nil, err
				}
				switch kk := k.(type) {
				case string:
					evaluated += "." + jsonEscapeString(kk)
				default:
					evaluated += "." + renderValue(kk)
				}
			} else {
				evaluated += "." + p.name
			}
		}
	}
	if !ok {
		return nil, notFound()
	}
	for _, p := range e.path {
		var key Value
		if p.expr != nil {
			k, err := st.evalExpr(p.expr)
			if err != nil {
				return nil, err
			}
			key = k
		} else {
			key = p.name
		}
		switch c := v.(type) {
		case *OMap:
			ks := renderValue(key)
			nv, ok := c.Get(ks)
			if !ok {
				return nil, notFound()
			}
			v = nv
		case []Value:
			var idx int64 = -1
			switch k := key.(type) {
			case int64:
				idx = k
			case float64:
				idx = int64(k)
			case string:
				n, err := strconv.ParseInt(k, 10, 64)
				if err == nil {
					idx = n
				}
			}
			if idx < 0 || idx >= int64(len(c)) {
				return nil, notFound()
			}
			v = c[idx]
		default:
			return nil, notFound()
		}
	}
	return v, nil
}

